export type ContentBlock = { type: 'paragraph' | 'heading' | 'verse' | 'meta'; text: string };
export type Chapter = { number: number; roman: string; slug: string; title: string; subtitle: string; blocks: readonly ContentBlock[]; };

const ROMANS = ['', 'I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX','XXI'];

const makeChapter = (number: number, slug: string, title: string, subtitle: string, blocks: readonly ContentBlock[]): Chapter => ({ number, roman: ROMANS[number], slug, title, subtitle, blocks });

export const chapters: readonly Chapter[] = [
  makeChapter(1, "prefacio-e-titulo-enganador", "Introdução editorial", "A origem do título e do Caderno Amarelo", [
    {"type": "heading", "text": "Últimas conversas: um título enganador"},
    {"type": "paragraph", "text": "Em fevereiro de 1909, Madre Agnès entregou ao vice-postulador, Monsenhor de Teil, cinco cadernos verdes contendo uma seleção das palavras de Teresa durante a doença. Ela queria fazê-lo tomar consciência da dor dos últimos meses, enquanto ele considerava excessivamente hagiográfica a maneira como a História de uma alma descrevia esses momentos derradeiros, apresentando-os como um «abandono na alegria e na paz contínuas». Monsenhor de Teil queria mostrar que a futura santa «penou e sofreu para chegar à santidade». Essa vontade de realismo esclarece o título dado por Madre Agnès à coletânea: «Perfil moral da irmã Teresa do Menino Jesus durante sua última doença, segundo suas palavras textuais»."},
    {"type": "paragraph", "text": "Dezoito meses mais tarde, ao contar ao tribunal os últimos momentos de Teresa, a prioresa entregou aos juízes uma coletânea das palavras de sua irmã para que ela figurasse nos autos do processo. O título era o mesmo, com esta explicação: as palavras haviam sido «recolhidas por mim (irmã Agnès de Jesus) da própria boca da Serva de Deus e registradas à medida que eram ditas num caderno». Eram piedosas imprecisões, sugeridas por Monsenhor de Teil, para fazer crer que Teresa se exprimia diretamente por meio das palavras que sua irmã havia recolhido."},
    {"type": "paragraph", "text": "Entre 1921 e 1924, quando o processo se aproximava do fim, Madre Agnès passou a limpo, para si mesma, a coletânea mais completa das palavras de Teresa num caderno encadernado em marrom-claro, tendendo ao amarelo. Deu-lhe um título neutro: «Palavras recolhidas durante os últimos meses de nossa santa Teresinha»."},
    {"type": "paragraph", "text": "Em 1927, ela entregou ao público as últimas palavras de Teresa: Novissima verba — Últimas conversas de Santa Teresa do Menino Jesus, maio-setembro de 1897. O título havia sido sugerido por M. Dubosq, promotor da fé no processo diocesano. Ele vinha acompanhado da citação latina «Colligite fragmenta ne pereant» — «Recolham os pedaços para que nada se perca» (Jo 6,12) —, alusão aos pães multiplicados por Jesus e não consumidos pela multidão."},
    {"type": "paragraph", "text": "As palavras de Teresa são fragmentos preciosos que não devem perecer. O título latino da coletânea pretendia ecoar o célebre poema de Lamartine, cujo subtítulo, «Minha alma está triste até a morte», evocava a agonia de Jesus:"},
    {"type": "verse", "text": "Toda alma tem seu segredo que deseja revelar,\nSua palavra a dizer ao mundo, à morte, à vida,\nAntes que para sempre, extinta, esvaecida,\nEla tenha desaparecido, como um fogo da noite,\nQue não deixa depois de si nem luz nem som!"},
    {"type": "heading", "text": "O Caderno Amarelo de Pauline"},
    {"type": "meta", "text": "Palavras recolhidas durante os últimos meses de nossa santa Teresinha — Agnès de Jesus"},
  ]),
  makeChapter(2, "6-de-abril-de-1897", "6 de abril de 1897", "As primeiras anotações do Caderno Amarelo", [
    {"type": "heading", "text": "6 abril 1897"},
    {"type": "paragraph", "text": "Quando somos incompreendidas e julgadas desfavoravelmente, de que adianta nos defender, explicar‑nos? Deixemos isso cair, não digamos nada, é tão doce nada dizer, deixar‑se julgar como for! Não vemos no Evangelho que Sta. Madalena se tenha explicado quando sua irmã a acusava de ficar aos pés de Jesus sem fazer nada. Ela não disse: «Ó Marta, se soubesses a felicidade de que desfruto, se ouvisses as palavras que eu ouço! E, além disso, foi Jesus quem me disse para ficar aqui.» Não, ela preferiu ficar em silêncio. Ó bem‑aventurado silêncio que dá tanta paz à alma!"},
    {"type": "paragraph", "text": "«Que a espada do espírito, que é a palavra de Deus, permaneça perpetuamente em nossa boca e em nossos corações.» Se estamos às voltas com uma alma desagradável, não nos afastemos, não a deixemos jamais. Tenhamos sempre «a espada do espírito» na boca para lhe corrigir seus erros; não deixemos as coisas irem embora para conservar nosso repouso; combatamos sempre mesmo sem esperança de ganhar a batalha. Que importa o sucesso? O que o bom Deus nos pede é que não nos detenhamos diante das fadigas da luta, que não nos desanimemos dizendo: «Tanto faz! não há nada a fazer; ela deve ser abandonada.» Oh! isso é covardia; é preciso cumprir o dever até o fim."},
    {"type": "paragraph", "text": "Ah! como não devemos julgar nada sobre a terra. Isso é o que me aconteceu na recreação, há alguns meses. É um nada, mas que me ensinou muito:"},
    {"type": "paragraph", "text": "Batiam dois golpes, e estando a Depositária ausente, era preciso uma ajudante para a minha Ir. Teresa de Sto. Agostinho. Ordinariamente, é cansativo servir de ajudante, mas dessa vez isso me atraía mais, porque havia de abrir‑se a porta para receber os ramos de árvore para o presépio."},
    {"type": "paragraph", "text": "A Ir. Maria de Sto. José estava ao meu lado e eu pressentia que ela partilhava meu desejo infantil. — «Quem vai servir de ajudante para mim?» disse minha Ir. Teresa de Sto. Agostinho. Logo desfiz meu avental, mas devagar, a fim de que a Ir. Maria de Sto. José estivesse pronta antes de mim e tomasse o lugar, o que aconteceu. Então, a Ir. Teresa de Sto. Agostinho disse rindo e olhando‑me: «Pois bem, é minha Ir. M. de Sto. J. que vai ter essa pérola em sua coroa. Você estava indo muito devagar.» Eu não respondi senão com um sorriso e voltei ao trabalho, dizendo para mim mesma: «Ó meu Deus como os vossos juízos são diferentes dos dos homens! É assim que muitas vezes nos enganamos na terra, tomando por imperfeição em nossas irmãs o que é mérito diante de vós!»"},
    {"type": "paragraph", "text": "Quando se está muito doente de corpo, todo mundo se empenha em vos aliviar; se é do peito, evitam‑se as correntes de ar, a enfermeira está ali que vela para que nada te falte. Ah! por que não fazemos o mesmo para as doenças espirituais de nossas irmãs? É isso que o bom Deus me pede a mim e, se eu curar, continuarei a fazê‑lo de todo o meu coração. Se uma Irmã está doente espiritualmente, desagradável em tudo, todo mundo se afasta dela, olha‑se para ela com maus olhos, e em vez de procurar aliviá‑la, é a ela que às vezes se lançam palavras ferinas... a ela que é sem forças e incapaz de as suportar! É antes com as que estão sãs que se deveria agir assim, porque estas, encontrando‑se bem, suportariam com felicidade a humilhação, a falta de consideração, o abandono. Pois bem! é às almas doentes que quero reservar meus sorrisos, meu afeto e minhas delicadezas, é aí que encontro a verdadeira caridade."},
    {"type": "heading", "text": "7 abril"},
    {"type": "paragraph", "text": "Perguntei‑lhe de que maneira eu morreria, deixando‑lhe ver minhas apreensões. Ela respondeu com um sorriso cheio de ternura:"},
    {"type": "paragraph", "text": "«O bom Deus a esvaziará como uma pequenina gota de orvalho...»"},
    {"type": "heading", "text": "18 abril"},
    {"type": "paragraph", "text": "Ela acabara de me confiar algumas humilhações bem penosas que lhe tinham sido feitas por irmãs."},
    {"type": "paragraph", "text": "«O bom Deus dá‑me assim todos os meios para permanecer bem pequena; mas é isso que é necessário; estou sempre contente; eu me ajeito, mesmo no meio da tempestade, de maneira a me conservar bem em paz por dentro. Se me contam combates contra as irmãs, esforço‑me para não me animar por minha vez contra aquela ou aquela. É preciso, por exemplo, que, enquanto escuto, eu possa olhar pela janela e gozar interiormente a vista do Céu, das árvores... Entende? Há pouco, durante minha luta por causa da Ir. X. eu olhava com prazer as belas pegas a esvoaçar no prado, e eu estava tão em paz quanto na oração... Lutei bastante com... estou bem cansada! mas não temo a guerra. É vontade do bom Deus que eu lute até a morte. Oh! minha pequena Mãe, reze por mim!"},
    {"type": "paragraph", "text": "... Eu, quando rezo por vós, não digo um Pai‑nosso nem uma Ave‑Maria, digo simplesmente com um impulso do coração: «Ó meu Deus, enchei minha pequena Mãe de toda sorte de bens, amai‑a mais, se podeis.»"},
    {"type": "paragraph", "text": "Eu era muito pequena quando minha tia me deu para ler uma história que muito me espantou. Vi, de fato, que se louvava uma mestra de pensionato, porque ela sabia habilmente safar‑se sem ferir ninguém. Notei sobretudo esta frase: «Ela dizia a uma: Você não está errada; à outra: Você tem razão.» E pensei para comigo: Isso não é bom! Essa mestra devia não ter medo nenhum e dizer às suas meninas que elas estavam erradas quando era verdade."},
    {"type": "paragraph", "text": "E agora não mudei de opinião. Tenho bem mais sofrimento, eu o confesso, pois é sempre tão fácil pôr o erro nos ausentes, e isso acalma de imediato a queixa. Sim, mas... eu faço precisamente o contrário. Se não sou amada, paciência! Eu digo a verdade toda, que não venham me procurar, se não quiserem sabê‑la."},
    {"type": "paragraph", "text": "Não se deve deixar que a bondade degenere em fraqueza. Quando se arrancou com justiça, é preciso ficar por aí, sem deixar‑se enternecer ao ponto de se martirizar por ter feito sofrer, por ver sofrer e chorar. Correr atrás da afligida para consolá‑la é lhe fazer mais mal que bem. Deixá‑la a si própria é obrigá‑la a recorrer ao bom Deus para ver seus erros e humilhar‑se. Do contrário, acostumada que estaria a receber consolo depois de uma justa repreensão, agiria sempre, nas mesmas circunstâncias, como uma criança mimada que salta e grita até que sua mãe venha enxugar suas lágrimas."},
  ]),
  makeChapter(3, "maio-de-1897", "Maio de 1897", "A confiança no caminho pequeno", [
    {"type": "paragraph", "text": "1º de maio de 1897"},
    {"type": "paragraph", "text": "Não será “a morte” que virá me buscar, será o bom Deus. A morte não é um fantasma, um espectro horrível, como a representam nas imagens. Está dito no catecismo que “a morte é a separação da alma e do corpo”, isso é tudo!"},
    {"type": "paragraph", "text": "Hoje meu coração encheu-se de uma paz celestial. Eu havia rezado tanto à Santa Virgem ontem à noite, pensando que seu belo mês ia começar!"},
    {"type": "paragraph", "text": "Vocês não estavam na recreação esta noite. Nossa Mãe nos disse que um dos missionários embarcados com o P. Roulland morreu antes de chegar à sua missão. Esse jovem missionário havia comungado no navio com as hóstias do Carmelo dadas ao P. Roulland... E agora ele morreu... sem ter feito nenhum apostolado, sem ter se empenhado em nada, como aprender chinês. O bom Deus lhe deu a palma do desejo; mas vejam como ele não precisa de ninguém."},
    {"type": "paragraph", "text": "Eu então não sabia que Madre Marie de Gonzague lhe havia dado o P. Roulland como segundo irmão espiritual. As palavras que acabo de relatar lhe foram escritas a ela pelo P.R., mas, tendo ordem de Nossa Mãe para não me confiar, ela só me falava sobre o que havia ouvido na recreação."},
    {"type": "paragraph", "text": "Foi um grande sacrifício para ela esse silêncio de quase 2 anos sobre seus relatos com o Missionário em questão..."},
    {"type": "paragraph", "text": "Nossa Mãe lhe havia pedido para pintar para ele uma imagem em pergaminho. Como eu era sua primeira para pintura, ela poderia ter aproveitado a circunstância para me pedir um conselho e assim me fazer adivinhar tudo. Mas, ao contrário, ela se escondia de mim o melhor que podia, vindo buscar às escondidas — soube disso mais tarde — o brunidor para fazer o ouro brilhar e que eu guardava sobre nossa mesa. Ela o devolvia quando eu estava ausente."},
    {"type": "paragraph", "text": "Só três meses antes de sua morte foi que Nossa Mãe lhe disse por vontade própria para me falar livremente sobre esse assunto como sobre qualquer outro."},
    {"type": "paragraph", "text": "7 mai"},
    {"type": "paragraph", "text": "7 horas da manhã."},
    {"type": "paragraph", "text": "É licença hoje, cantei “ma Joie” ao me vestir."},
    {"type": "paragraph", "text": "Nossa família não ficará muito tempo sobre a terra... Quando eu estiver no Céu, chamarei vocês bem depressa... Oh! como seremos felizes! Todas nós nascemos coroadas..."},
    {"type": "paragraph", "text": "Eu tosso! Eu tosso! Parece a locomotiva de uma ferrovia quando chega à estação. Eu também chego a uma estação; é a do Céu, e eu a anuncio!"},
    {"type": "paragraph", "text": "9 mai"},
    {"type": "paragraph", "text": "Podemos bem dizer, sem nos vangloriar, que recebemos graças e luzes bem particulares. Estamos na verdade; vemos as coisas sob sua verdadeira aparência."},
    {"type": "paragraph", "text": "A propósito dos sentimentos dos quais às vezes não se pode se defender, quando depois de ter prestado um serviço não se recebe nenhum testemunho de agradecimento."},
    {"type": "paragraph", "text": "Eu também, asseguro-lhes, experimento o sentimento de que vocês me falam; mas nunca sou apanhada, porque não espero na terra nenhuma retribuição: faço tudo para o bom Deus, assim não posso perder nada e sempre sou bem paga pelo mal que me dou em servir o próximo."},
    {"type": "paragraph", "text": "Se, por hipótese, o próprio bom Deus não visse minhas boas ações, eu não ficaria nenhum pouco aflita. Eu o amo tanto, que gostaria de poder agradá-lo sem que ele soubesse que fui eu. Sabendo e vendo, ele fica como obrigado “a me retribuir”, eu não gostaria de lhe dar esse trabalho..."},
    {"type": "paragraph", "text": "15 mai"},
    {"type": "paragraph", "text": "Estou muito contente de ir logo para o Céu, mas quando penso nesta palavra do bom Deus: “Eu levo minha recompensa comigo para retribuir a cada um segundo suas obras”, digo a mim mesma que, para mim, ele ficará bem constrangido. Eu não tenho obras! ele portanto não poderá me retribuir “segundo minhas obras”... Bem! ele me retribuirá “segundo as obras dele...”"},
    {"type": "paragraph", "text": "Faço-me uma ideia tão grande do Céu que, às vezes, me pergunto como, na minha morte, o bom Deus fará para me surpreender. Minha esperança é tão grande, é para mim um tal motivo de alegria, não pelo sentimento, mas pela fé, que me fará falta alguma coisa acima de todo pensamento para me satisfazer plenamente. Antes de ser desapontada, eu preferiria conservar uma esperança eterna."},
    {"type": "paragraph", "text": "Enfim penso já que, se eu não for suficientemente surpreendida, farei de conta que o sou, para agradar ao bom Deus. Não haverá perigo de que eu lhe mostre minha decepção; saberei bem manejar-me para que ele não perceba. Além disso, me arranjarei sempre de maneira a ser feliz. Para isso tenho minhas pequenas rubricas que vocês conhecem e que são infalíveis... Depois, só de ver o bom Deus feliz, isso bastará plenamente à minha felicidade."},
    {"type": "paragraph", "text": "Lhe tinha falado de certas práticas de devoção e de perfeição aconselhadas pelos santos e que me desencorajavam."},
    {"type": "paragraph", "text": "Para mim, não encontro mais nada nos livros, senão no Evangelho. Esse livro me basta. Escuto com deleite esta palavra de Jesus que me diz tudo o que tenho a fazer: “Apprenez de moi que je suis doux et humble de coeur”; então tenho a paz, segundo sua doce promessa: ... “et vous trouverez le repos de vos âmes.”"},
    {"type": "paragraph", "text": "“...Et vous trouverez le repos de vos petites âmes...”"},
    {"type": "paragraph", "text": "Nem sombra! Nem mais do que se fosse a de um chinês, lá, a duas mil léguas de nós."},
    {"type": "paragraph", "text": "Jogo à direita, à esquerda, aos meus passarinhos as boas sementes que o bom Deus põe na minha mãozinha. E então, que seja como quiser! Não me ocupo mais. Às vezes é como se eu nada houvesse semeado; em outros momentos faz bem; mas o bom Deus me diz:"},
    {"type": "paragraph", "text": "Eu gostaria muito de ir para Hanói, para sofrer muito pelo bom Deus. Gostaria de ir para lá para ficar inteiramente só, para não ter nenhuma consolação na terra. Quanto ao pensamento de me tornar útil lá, nem passa pela minha cabeça, sei muito bem que não faria nada."},
    {"type": "paragraph", "text": "Afinal, tanto faz para mim viver ou morrer. Não vejo bem o que teria a mais depois da morte do que já tenho nesta vida. Verei o bom Deus, é verdade! mas para estar com ele, já estou completamente aqui na terra."},
    {"type": "paragraph", "text": "18 mai"},
    {"type": "paragraph", "text": "Fui dispensada de todo ofício; pensei que minha morte não causaria o menor transtorno na Comunidade."},
    {"type": "paragraph", "text": "Oh! quanto a isso, é a menor das minhas preocupações, tanto me faz!"},
    {"type": "paragraph", "text": "Por favor, não me impeçam de dizer meus “pequenos” ofícios dos Mortos. É tudo o que posso fazer pelas irmãs que estão no purgatório, e isso não me cansa nada. Às vezes, ao fim de um silêncio, tenho um pequeno momento; isso me relaxa antes."},
    {"type": "paragraph", "text": "Sempre preciso ter trabalho preparado; assim não fico preocupada e nunca perco meu tempo."},
    {"type": "paragraph", "text": "Tinha pedido ao bom Deus seguir os exercícios de comunidade até a minha morte; mas ele não quer! Eu poderia, disso tenho certeza, ir a todos os ofícios, não morreria um minuto mais cedo. Às vezes parece-me que, se eu nada dissesse, não me acharíamos doente."},
    {"type": "paragraph", "text": "19 mai"},
    {"type": "paragraph", "text": "Por que vocês estão tão alegres hoje?"},
    {"type": "paragraph", "text": "Porque, esta manhã, tive duas “pequenas” dores. Oh! bem sensíveis!... Nada me dá “pequenas” alegrias como as “pequenas” dores..."},
    {"type": "paragraph", "text": "20 mai"},
    {"type": "paragraph", "text": "Dizem-me que terei medo da morte. Isso pode muito bem ser. Não há aqui ninguém mais desconfiada desses seus sentimentos do que eu. Nunca me apoio nos meus próprios pensamentos; sei o quanto sou fraca; mas quero gozar do sentimento que o bom Deus me dá agora. Haverá sempre tempo de sofrer o contrário."},
    {"type": "heading", "text": "Eu lhe mostrava sua fotografia:"},
    {"type": "paragraph", "text": "Sim, mas... é o invólucro; quando se verá a carta? Oh! como eu gostaria ver a carta!..."},
    {"type": "heading", "text": "De 21 a 26 de maio"},
    {"type": "paragraph", "text": "Théophane Vénard me agrada ainda mais do que S t Louis de Gonzague, porque a vida de S t Louis de Gonzague é extraordinária e a dele totalmente ordinária. Além disso é ele quem fala, enquanto que para o santo é outro quem narra e o faz falar; então quase nada se sabe de sua “pequena” alma!"},
    {"type": "paragraph", "text": "Théophane Vénard amava muito sua família; e eu também amo muito a minha “pequena” família. Não compreendo os santos que não amam sua família... Minha pequena família de agora, oh! eu a amo muito! Amo muito, muito, minha pequena Mère."},
    {"type": "paragraph", "text": "Vou morrer em breve; mas quando? Oh! quando?... Isso não vem! Sou como uma criancinha a quem prometem sempre um bolo: mostram-no de longe; depois, quando ela se aproxima para tomá-lo, a mão se retira... Mas, no fundo, estou bem abandonada para viver, para morrer, para sarar, e para ir à Cochinchina, se o bom Deus o quiser."},
    {"type": "paragraph", "text": "Depois da minha morte, não será preciso me cercar de coroas como Madre Geneviève. Às pessoas que quisessem dá-las, vocês dirão que eu prefiro que elas ponham esse dinheiro para resgatar pequenos negros. Isso sim me faria prazer."},
    {"type": "paragraph", "text": "Há algum tempo, eu tinha muita pena de tomar remédios caros; mas agora isso não me importa nada, ao contrário. É desde que li na vida de S te Gertrude que ela se alegrava por isso mesma, dizendo que tudo seria em proveito daqueles que nos fazem bem. Ela se apoiava na palavra de Nosso Senhor: “Ce que vous ferez au plus petit d’entre les miens, c’est à moi-même que vous le ferez.”"},
    {"type": "paragraph", "text": "Estou convencida da inutilidade dos remédios para me curar; mas arreglei-me com o bom Deus, para que ele faça deles beneficiar pobres missionários doentes, que não têm nem tempo nem meios para se cuidar. Peço-lhe que os cure no lugar de mim pelos medicamentos e pelo repouso que me obrigam a tomar."},
    {"type": "paragraph", "text": "Disseram-me tantas vezes que eu tenho coragem, e é tão pouco verdade, que me disse: Mas, enfim, não se deve fazer mentir todo mundo! E pus-me, com a ajuda da graça, a adquirir essa coragem. Fiz como um guerreiro que, ouvindo-se felicitar por sua bravura, sabendo muito bem que não é mais que um covarde, acabaria ficando envergonhado dos elogios e quisesse merecê-los."},
    {"type": "paragraph", "text": "Quando eu estiver no Céu, quantas graças pedirei por vocês! Oh! atormentarei tanto o bom Deus que, se ele quisesse primeiro me recusar, minha importunação o forçaria a preencher meus desejos. Essa história está no Evangelho..."},
    {"type": "paragraph", "text": "... Se os santos me demonstrarem menos afeto que minhas pequenas irmãs, isso me parecerá bem duro... e irei chorar num cantinho..."},
    {"type": "paragraph", "text": "Os santos Inocentes não serão menininhos no Céu; terão apenas os encantos indefiníveis da infância. Apresentamo-los “crianças”, porque precisamos de imagens para compreender as coisas espirituais."},
    {"type": "paragraph", "text": "... Sim, espero juntar-me a eles! Se quiserem, serei sua pequena paje, segurarei suas pequenas caudas..."},
    {"type": "paragraph", "text": "Se eu não tivesse essa provação de alma que é impossível de entender, creio bem que morreria de alegria ao pensamento de deixar em breve a terra."},
    {"type": "heading", "text": "De 21 a 26 de maio"},
    {"type": "paragraph", "text": "Estava um pouco triste esta noite, perguntando-me se o bom Deus realmente estava contente comigo. Pensava no que cada uma das irmãs diria de mim, se fosse interrogada. Tal diria: “É uma boa pequena alma, pode tornar-se santa.” — Outra: “Ela é bem mansa, bem piedosa, mas isto... mas aquilo...” — Outras ainda teriam pensamentos diferentes; várias me acharam bem imperfeita, o que é verdade... Para minha pequena Mère, ela me ama tanto, isso a cega, então não posso acreditar. Oh! o que o bom Deus pensa, quem me dirá? Eu estava nessas reflexões, quando chegou o seu bilhetinho. Vocês me diziam que tudo em mim lhes agradava, que eu era particularmente querida do bom Deus, que ele não me fizera subir como aos outros a ruda escada da perfeição, mas que me pôs num elevador para que eu fosse mais depressa levada a Ele. Já estava comovida, mas sempre o pensamento de que o seu amor lhes fazia ver o que não é, impedia-me de gozar plenamente; então peguei meu pequeno Evangelho, pedindo ao bom Deus que me consolasse, que me respondesse ele mesmo... e eis que caí neste trecho que nunca havia notado: “Celui que Dieu a envoyé dit les mêmes choses que Dieu, parce qu’il ne lui a pas communiqué son Esprit avec mesure.” Oh! então derramei lágrimas de alegria, e esta manhã, ao acordar, estava ainda toda embalsamada. Foi você, minha pequena Mère, que Deus enviou para mim, foi você quem me educou, quem me fez entrar no Carmelo; todas as grandes graças da minha vida, as recebi por sua intercessão; assim, você diz as mesmas coisas que Deus, e agora, creio que o bom Deus está muito contente comigo, já que você me o diz."},
    {"type": "paragraph", "text": "26 mai"},
    {"type": "paragraph", "text": "Véspera da Ascensão"},
    {"type": "paragraph", "text": "Esta manhã durante a procissão, eu estava no eremitério de S t Joseph e olhava de longe pela janela a Comunidade no jardim. Era ideal, essa procissão de religiosas com manteletes brancos; fazia-me lembrar o cortejo das virgens no Céu. Na curva do passeio dos castanheiros, eu via vocês todas meio escondidas pelas altas ervas e pelas ranúnculas do prado. Era cada vez mais delicioso. Mas eis que entre essas religiosas vejo uma, das mais gentis, que olha do meu lado, que se inclina sorrindo para me dar um sinal de reconhecimento. Era minha pequena Mère! Logo me lembrei do meu sonho: o sorriso, as carícias da Madre Anne de Jésus e a mesma impressão de doçura me invadiu. Dizia a mim mesma: é assim que os santos me conhecem, que me amam, que me sorriem lá de cima e me convidam a juntarme a eles!"},
    {"type": "paragraph", "text": "Então vieram as lágrimas... Faz muitos anos que não chorava tanto assim. Ah! eram lágrimas doces."},
    {"type": "paragraph", "text": "27 mai"},
    {"type": "paragraph", "text": "Ascensão"},
    {"type": "paragraph", "text": "Aceito uma “circular”, porque sempre pensei que devia pagar o ofício dos mortos que cada carmelita dirá por mim. Não entendo muito por que há quem não queira circular; é tão doce conhecer-se, saber um pouco com quem viveremos eternamente."},
    {"type": "paragraph", "text": "Não tenho nenhum medo das últimas batalhas, nem dos sofrimentos, por grandes que sejam, da doença. O bom Deus sempre me socorreu; ajudou-me e conduziu-me pela mão desde minha mais tenra infância... conto com ele. Estou certa de que continuará seu socorro até o fim. Posso muito bem não mais poder, mas nunca terei de mais, disso estou segura."},
    {"type": "paragraph", "text": "Não sei quando morrerei, mas creio que será em breve; tenho muitas razões para esperá-lo."},
    {"type": "paragraph", "text": "Não desejo mais morrer do que viver; isto é dizer que, se tivesse que escolher, preferiria morrer; mas, já que é o bom Deus quem escolhe por mim, prefiro o que ele quer. É o que Ele faz que eu amo."},
    {"type": "paragraph", "text": "Que não se creia que, se eu sarar, isso me desconcertará e destruirá meus pequenos planos. Nem pensar! A idade não é nada aos olhos do bom Deus, e eu me arreganho bem para continuar pequena criança, mesmo vivendo muito tempo."},
    {"type": "paragraph", "text": "Vejo sempre o lado bom das coisas. Há quem toma tudo de maneira a se fazer o maior mal. Para mim, é o contrário. Se tenho apenas o puro sofrimento, se o céu está tão escuro que não vejo nenhuma clareira, pois então faço disso minha alegria... Faço... jabot! como provas do papai que me tornam mais gloriosa que uma rainha."},
    {"type": "paragraph", "text": "Notaram, na leitura do refeitório, aquela carta dirigida à mãe de S t Louis de Gonzague, onde se diz dele que não poderia ter aprendido mais nem ter sido mais santo, mesmo se tivesse chegado à idade de Noé?"},
    {"type": "paragraph", "text": "A propósito de sua morte."},
    {"type": "paragraph", "text": "Sou como uma pessoa que, tendo um bilhete de loteria, corre maior chance de ganhar do que outra que não teria nenhum; mas, no entanto, ela ainda não tem certeza de obter um prêmio. Enfim, tenho um bilhete, é minha doença, e posso manter boa esperança!"},
    {"type": "paragraph", "text": "Lembro-me que uma pequena vizinha dos Buissonnets, de 3 anos, ouvindo ser chamada por outras crianças, dizia à sua mãe: “Mamãe! elas me querem! deixa-me ir, eu te imploro... elas me querem!...”"},
    {"type": "paragraph", "text": "Pois bem, parece-me que hoje os pequeninos anjos me chamam, e eu lhes digo como a menininha: “Deixem-me partir então, elas me querem!”"},
    {"type": "paragraph", "text": "Não os ouço, mas os sinto."},
    {"type": "paragraph", "text": "No momento em que meu envio para o Tonquim foi projetado, por volta de novembro, lembram-se que, para ter um sinal da vontade do bom Deus, começou-se uma novena a Théophane Vénard? Naquele momento voltei a todos os exercícios de comunidade, mesmo às Matinas. Pois bem! justamente durante a novena recomecei a tossir, e desde então vou de mal a pior. É ele que me chama. Oh! eu bem gostaria de ter seu retrato; é uma alma que me agrada. S t Louis de Gonzague era sério, mesmo na recreação, mas Théophane Vénard era sempre alegre."},
    {"type": "paragraph", "text": "Naquele momento liam no refeitório a vida de St L. de Gonzague."},
    {"type": "paragraph", "text": "29 mai"},
    {"type": "paragraph", "text": "Pontas de fogo pela segunda vez. À noite estava triste e abri diante dela o Evangelho para me consolar. Caí nestas palavras que lhe li: “Il est ressuscité, il n’est plus ici, voyez le lieu où on l’avait mis.”"},
    {"type": "paragraph", "text": "Sim, é bem isso! Não estou mais, de fato, como na minha infância, acessível a toda dor; estou como ressuscitada, não estou mais no lugar onde se me crê... Oh! não se preocupem por mim, cheguei a um ponto em que não mais posso sofrer, porque todo sofrimento me é doce."},
    {"type": "paragraph", "text": "30 mai"},
    {"type": "paragraph", "text": "Naquele dia, foi-lhe permitido confiar-me seu cuspido de sangue da Sexta-feira Santa de 1896. Como eu lhe mostrava grande pena por não ter sido avisada imediatamente, ela me consolou o melhor que pôde e escreveu-me à noite este bilhete:"},
    {"type": "paragraph", "text": "“N não tenhas pena, minha pequena Madre querida que tua filhinha tenha parecido te esconder alguma coisa, porque sabes bem, se ela escondeu um cantinho do invólucro, nunca te escondeu uma só linha da carta. E quem acaso conhece melhor do que tu essa pequenina carta que tanto amas? Aos outros, pode-se muito bem mostrar o invólucro por todos os lados, já que eles não podem ver senão isso; mas a ti!!!... Oh! pequena Mère, sabes agora que foi na Sexta-feira Santa que Jesus começou a rasgar um pouco o invólucro da tua pequenina carta; não estás contente que ele se disponha a ler essa carta que tu escreves há 24 anos? Ah! se soubesses como ela saberá bem lhe dizer teu amor durante toda a eternidade!”"},
    {"type": "paragraph", "text": "Talvez padeças muito antes de morrer!.."},
    {"type": "paragraph", "text": "Oh! não tenhas pena, eu tenho tanto desejo!"},
    {"type": "paragraph", "text": "Não sei como farei no Céu para passar sem vocês!"},
  ]),
  makeChapter(4, "junho-de-1897", "Junho de 1897", "A escola do sofrimento", [
    {"type": "heading", "text": "4 de junho de 1897"},
    {"type": "paragraph", "text": "Ela nos fez seus adeuses na cela da Ir. Geneviève da Santa Face que ficava voltada para a terraço, do lado do Capítulo. Ela estava deitada no baldinho da Ir. Geneviève. Naquele dia, parecia não mais sofrer e tinha um rosto como transfigurado. Não nos cansávamos de olhá-la e de ouvir suas doces palavras."},
    {"type": "paragraph", "text": "Pedi à Santíssima Virgem que eu não ficasse mais sonolenta e absorvida como eu estava todos esses dias; eu sentia bem que lhes causava aflição. Esta noite, ela me atendeu."},
    {"type": "paragraph", "text": "Oh! minhas pequeninas irmãs, como estou feliz! Vejo que vou morrer em breve, tenho certeza agora."},
    {"type": "paragraph", "text": "Não estranhem se eu não lhes aparecer depois da minha morte, e se vocês não virem nada de extraordinário como sinal da minha felicidade. Vocês se lembrarão que é “minha pequena via” de nada desejar ver. Vocês bem sabem o que eu disse tantas vezes a Deus, aos Anjos e aos Santos:"},
    {"type": "paragraph", "text": "Que meu desejo não é"},
    {"type": "paragraph", "text": "De os ver aqui abaixo..."},
    {"type": "paragraph", "text": "Os Anjos virão buscá-las, disse Ir. Geneviève. Oh! no entanto como gostaríamos de os ver!"},
    {"type": "paragraph", "text": "Não creio que vocês os vejam, mas isso não os impedirá de estar lá..."},
    {"type": "paragraph", "text": "Eu, contudo, gostaria muito de ter uma bela morte, para lhes agradar. Pedi isso à Santíssima Virgem. Não pedi ao bom Deus, porque quero deixá-lo fazer como quiser. Pedir à Santíssima Virgem não é a mesma coisa. Ela bem sabe o que tem a fazer de meus pequenos desejos, se deve dizê-los ou não dizê-los... enfim, cabe a ela ver para não forçar o bom Deus a me atender, para deixá-lo fazer em tudo a sua vontade."},
    {"type": "paragraph", "text": "Esta noite obtive poder consolar vocês um pouco e ser bem gentil, mas não se deve esperar ver-me assim na hora da morte... Não sei! Logo, a Santíssima Virgem talvez tenha feito isso por si mesma, sem dizer ao bom Deus, então isso não prova nada para mais tarde."},
    {"type": "paragraph", "text": "Não sei se irei ao purgatório, não me preocupo nenhum pouco; mas, se for, não me arrependo de não ter feito nada para o evitar. Nunca me arrependeria de ter trabalhado unicamente para salvar as almas. Como fiquei feliz em saber que N. M. Sainte Thérèse pensava assim!"},
    {"type": "paragraph", "text": "Minha pequena Mãe, se você for novamente prioresa um dia, não se preocupe; verá que não se fará mais as mesmas penas de antes. Você estará acima de tudo. Deixará pensar e dizer o que quisermos, cumprirá seu dever em paz... etc... etc."},
    {"type": "paragraph", "text": "Nunca façam nada para o ser, e nada também para não o ser... Aliás, prometo que não permitirei que o coloquem lá se for prejudicial à sua alma."},
    {"type": "heading", "text": "Quando a abracei:"},
    {"type": "paragraph", "text": "Eu disse tudo! em particular à minha pequena Mãe, para mais tarde..."},
    {"type": "paragraph", "text": "Não se perturbem, minhas pequeninas irmãs, se eu sofrer muito e se vocês não virem em mim, como já lhes disse, nenhum sinal de felicidade no momento da minha morte. Nosso Senhor morreu bem Vítima de Amor, e vejam qual foi sua agonia!... Tudo isso não diz nada."},
    {"type": "paragraph", "text": "Um pouco mais tarde, estando só com ela, e vendo-a de novo sofrer muito, eu lhe disse: “Bem, você desejava sofrer, o bom Deus não o esqueceu.”"},
    {"type": "paragraph", "text": "Eu desejava sofrer, e fui atendida. Sofri muito durante vários dias. Uma manhã, durante minha ação de graças, depois da comunhão, senti como as angústias da morte... e com isso nenhuma consolação!"},
    {"type": "paragraph", "text": "Aceito tudo por amor ao bom Deus, até os mais diversos pensamentos extravagantes que me vêm à cabeça."},
    {"type": "heading", "text": "5 de junho"},
    {"type": "paragraph", "text": "Durante Matinas"},
    {"type": "paragraph", "text": "Minha pequena Mãe, vi que você me ama de um amor desinteressado. Pois bem! se sei que você é minha pequena mãe, saberá um dia que eu sou sua pequena filha! Oh! como eu a amo!"},
    {"type": "paragraph", "text": "Releio o peça sobre Joana d’Arc que compus. Vocês verão aí meus sentimentos sobre a morte; estão todos expressos; isso lhes fará prazer. Mas não acreditem que me pareço com Joana d’Arc quando ela teve medo um momento... Ela arrancava os cabelos!... eu não arranco os “pequenos” cabelos..."},
    {"type": "paragraph", "text": "Minha pequena mãe, foi você quem me preparou para minha primeira Comunhão, prepare-me agora para morrer..."},
    {"type": "paragraph", "text": "Se você me encontrasse morta uma manhã, não se aflija: é que Papai, o bom Deus, teria vindo simplesmente me buscar. Sem dúvida, é uma grande graça receber os Sacramentos; mas quando o bom Deus não o permite, é bom mesmo assim, tudo é graça."},
    {"type": "heading", "text": "6 de junho"},
    {"type": "paragraph", "text": "Agradeço por terem pedido que me dessem um pedacinho da santa Hóstia. Tive ainda muita dificuldade para engoli-la. Mas como eu estava feliz por ter o bom Deus no meu coração! Chorei como no dia da minha primeira Comunhão."},
    {"type": "paragraph", "text": "Pe. Youf me disse a respeito das minhas tentações contra a fé: “Não se detenha nisso, é muito perigoso.” Não é muito consolador ouvir isso, mas felizmente eu não me impressiono. Fiquem tranquilas, não vou quebrar minha “pequena” cabeça a me atormentar."},
    {"type": "paragraph", "text": "Pe. Youf me disse ainda: “Você está resignada a morrer?” Eu lhe respondi: “Ah! meu Padre, acho que só é preciso resignação para viver. Para morrer, é alegria o que eu sinto.”"},
    {"type": "paragraph", "text": "Pergunto-me como farei para morrer. Contudo, gostaria de me sair bem com “honra”! Enfim, creio que isso não depende de nós."},
    {"type": "paragraph", "text": "Ela pensava em nós."},
    {"type": "paragraph", "text": "Na minha infância, os grandes acontecimentos da minha vida me pareciam como montanhas intransponíveis. Quando via as menininhas fazerem a primeira Comunhão, dizia-me: Como farei na minha primeira Comunhão?... Mais tarde: Como farei para entrar no Carmelo?... E depois: para vestir o Hábito? para fazer a Profissão? Agora é para morrer!"},
    {"type": "paragraph", "text": "“Vou fazer vocês fotografar para agradar à Nossa Mãe.” Ela sorriu com um ar maroto:"},
    {"type": "paragraph", "text": "Diga antes que é para vocês!... “Ventinho de brisa, pare de soprar! Não é para mim, é para meu companheiro que não tem casaco...”"},
    {"type": "paragraph", "text": "Ela me lembrava assim uma pequena história de auvergnats que papai nos contava. Ela colocava o tom, e era muito bem aplicado, porque o camarada tão caridoso em aparente, pleiteava por ele na realidade."},
    {"type": "paragraph", "text": "Não se queria lhe dizer, com medo de a enjoar, que o xarope que ela tomava era xarope de caracol, mas ela se apercebeu e riu de nossos receios;"},
    {"type": "paragraph", "text": "Que me importa tomar xarope de caracol, contanto que eu não veja os chifres! Agora eu como caracóis como os patinhos! Ontem, fazia como as avestruzes, comia ovos crus!"},
    {"type": "paragraph", "text": "Eu amo vocês muito, muito!"},
    {"type": "paragraph", "text": "Eu lhe disse: “Os Anjos a carregarão em suas mãos, para que não bata o pé contra a pedra.” Ela respondeu:"},
    {"type": "paragraph", "text": "Ah! isso é bom para logo; porque mais tarde, depois da minha morte, não ficarei embaraçada!!!"},
    {"type": "paragraph", "text": "Depois da visita do Sr. de Cornière que a encontrou melhor, eu lhe disse: “Você está triste?”"},
    {"type": "paragraph", "text": "Oh! não... Tirei do Evangelho: “Em breve vereis o Filho do Homem sentado sobre as nuvens do Céu.”"},
    {"type": "paragraph", "text": "Respondi: “Senhor, quando?” E em frente da página, li estas palavras: “Hoje mesmo.”"},
    {"type": "paragraph", "text": "Mas tudo isso... é não preocupar-se de nada, não querer nem viver nem morrer..."},
    {"type": "heading", "text": "Alguns instantes depois:"},
    {"type": "paragraph", "text": "Tenho, no entanto, muita vontade de ir embora! Digo isso à Santíssima Virgem que faz dela o que quiser."},
    {"type": "heading", "text": "7 de junho"},
    {"type": "paragraph", "text": "Domingo"},
    {"type": "paragraph", "text": "No banco, ao fundo do cemitério, ela ficou algum tempo sentada perto de mim. No fim, apoiou ternamente a cabeça no meu peito e cantou baixinho:"},
    {"type": "paragraph", "text": "Eu te esquecer, Mãe querida,"},
    {"type": "paragraph", "text": "Não, não, jamais! . . . . . . . . . . . . . . . . . . . . ."},
    {"type": "paragraph", "text": "Ao descer os degraus, viu, à direita, debaixo do nêspero, a galinha branca que tinha todos os seus pintinhos sob as asas. Alguns mostravam só suas cabecinhas. Parou toda pensativa a olhá-los. Ao cabo de um momento, fiz-lhe sinal de que era hora de voltar. Tinha os olhos cheios de lágrimas. Eu lhe disse: “Você chora!” Então ela pôs a mão diante dos olhos, chorando mais, e me respondeu:"},
    {"type": "paragraph", "text": "Não posso dizer por que neste momento; estou demasiado comovida..."},
    {"type": "paragraph", "text": "À noite, em sua cela, disse-me com uma expressão celestial:"},
    {"type": "paragraph", "text": "Chorei pensando que o bom Deus tomou essa comparação para nos fazer crer em sua ternura. Toda minha vida foi isso que ele fez por mim! Ele me escondeu inteiramente debaixo de suas asas!... Há pouco, ao despedir-me de vocês, chorei subindo a escada, não pude mais conter-me, e estava ansiosa por chegar à nossa cela; meu coração transbordava de amor e de gratidão."},
    {"type": "paragraph", "text": "Hoje faz 10 anos que papai me deu essa pequena flor branca, quando pela primeira vez lhe falei da minha vocação."},
    {"type": "paragraph", "text": "Ela me mostrou a pequena flor"},
    {"type": "paragraph", "text": "Se vocês não me tivessem bem educado, teriam visto coisas tristes... Eu não teria chorado hoje ao ver a galinha branca…"},
    {"type": "heading", "text": "8 de junho"},
    {"type": "paragraph", "text": "Vocês virão logo todas comigo, não será demorado, vamos!"},
    {"type": "paragraph", "text": "À Ir. Marie da Trindade que lhe pedia que pensasse nela no Céu:"},
    {"type": "paragraph", "text": "Vocês ainda viram só a casca; logo verão o pintinho."},
    {"type": "paragraph", "text": "Eu dizia a ela que não tinha apoio na terra."},
    {"type": "paragraph", "text": "Mas sim, você tem um apoio, sou eu!"},
    {"type": "paragraph", "text": "Tínhamos falado das longas doenças que muitas vezes cansam as enfermeiras, o que é grande sofrimento para os doentes que o notam."},
    {"type": "paragraph", "text": "Quero bem ficar assim até o fim de uma vida muito longa; se isso agradar ao bom Deus, quero mesmo ser “pegada de antipatia.”"},
    {"type": "heading", "text": "9 de junho"},
    {"type": "paragraph", "text": "Diz-se no Evangelho que o bom Deus virá como um ladrão. Ele virá me roubar bem gentilmente. Oh! como eu gostaria muito de ajudar o Ladrão!"},
    {"type": "paragraph", "text": "Como estou feliz hoje!"},
    {"type": "paragraph", "text": "Sua provação, então, passou?"},
    {"type": "paragraph", "text": "Não, mas é como algo suspenso. As cobras feias não assobiam mais em meus ouvidos..."},
    {"type": "paragraph", "text": "Com que paz eu deixo dizer ao meu redor que estou melhor! Na semana passada, eu estava de pé e me encontravam bem doente. Esta semana, não me sustento mais, estou exausta e já me julgam salva! Mas o que é que isso faz!"},
    {"type": "paragraph", "text": "Você espera, então, morrer em breve?"},
    {"type": "paragraph", "text": "Sim, espero em breve ir embora; certamente não estou melhor; tenho muita dor no lado. Mas, direi sempre, se o bom Deus me curar, não terei decepção alguma."},
    {"type": "paragraph", "text": "À Ir. Marie do Sagrado Coração que lhe dizia: “Que pena teremos quando você nos deixar!”"},
    {"type": "paragraph", "text": "Oh! não, vocês verão, será como uma chuva de rosas."},
    {"type": "paragraph", "text": "Não temo o Ladrão... Vejo-o de longe, e me contenho bem de gritar: Ao ladrão! Pelo contrário, eu o chamo dizendo: Por aqui! por aqui!"},
    {"type": "paragraph", "text": "Sou como uma criancinha, na via do caminho de ferro, que espera seu papai e sua mamãe para o colocar no trem. Ai de mim! eles não vêm, e o trem parte! Mas há outros, não perder-lhes-ei todos..."},
    {"type": "heading", "text": "10 de junho"},
    {"type": "paragraph", "text": "Ela estava melhor e isso a espantava; era obrigada a reagir para não se entristecer."},
    {"type": "paragraph", "text": "... A Santíssima Virgem faz bem minhas comissões, darei outra a ela outra vez!"},
    {"type": "heading", "text": "Repito-lhe muitas vezes:"},
    {"type": "paragraph", "text": "“Diga-lhe para nunca se encomodar comigo.”"},
    {"type": "paragraph", "text": "Ele ouviu, e foi o que fez. Não compreendo mais nada da minha doença. Eis que estou melhor! Mas me abandono e sou feliz mesmo assim. O que eu seria se alimentasse a esperança de morrer logo! Que de decepções! Mas não tenho nenhuma, porque estou contente de tudo o que o bom Deus faz, não desejo senão sua vontade."},
    {"type": "heading", "text": "11 de junho"},
    {"type": "paragraph", "text": "Ela havia lançado flores a São José do jardim, (no fundo do caminho dos castanheiros) dizendo com um tom infantil e gracioso:"},
    {"type": "paragraph", "text": "“Take!” [“Toma!”]"},
    {"type": "paragraph", "text": "Por que lança flores a São José? É para obter alguma graça?"},
    {"type": "paragraph", "text": "Ah! mas não! É para lhe fazer prazer. Não quero dar para receber."},
    {"type": "paragraph", "text": "Para escrever minha “pequena” vida, não me corro a cabeça; é como se pescasse à linha; escrevo o que vem na ponta."},
    {"type": "heading", "text": "12 de junho"},
    {"type": "paragraph", "text": "Não me creem tão doente quanto sou. É mais penoso então ser privada da comunhão, do Ofício. Mas, tanto melhor que ninguém se perturbe mais. Sofria muito e havia pedido à Santíssima Virgem que arranjasse as coisas para que não se tivessem mais pena. Ela me atendeu."},
    {"type": "paragraph", "text": "Para mim, que me importa que pensem e digam qualquer coisa. Não vejo porque me afligiria com isso."},
    {"type": "paragraph", "text": "Amanhã, não farei a Comunhão! E tantas menininhas receberão o bom Deus!"},
    {"type": "paragraph", "text": "Era a primeira Comunhão em Saint Jacques."},
    {"type": "heading", "text": "13 de junho"},
    {"type": "paragraph", "text": "No jardim"},
    {"type": "paragraph", "text": "Sinto-me como um tecido esticado no tear para ser bordado; e ninguém vem para bordá-lo! Espero, espero! É inútil!... Enfim, não é de espantar, as crianças pequenas não sabem o que querem!"},
    {"type": "paragraph", "text": "Digo isso porque penso no Menino Jesus, é ele quem me esticou no tear do sofrimento para ter o prazer de me bordar e depois de me soltar para ir mostrar lá em cima sua bela obra."},
    {"type": "paragraph", "text": "Quando falo do Ladrão, não penso no Menino Jesus, penso no “grande” bom Deus."},
    {"type": "heading", "text": "14 de junho"},
    {"type": "paragraph", "text": "Último dia da novena. Estava muito melhor, novo motivo de desapontamento para ela que me disse, porém, com um sorriso:"},
    {"type": "paragraph", "text": "Sou uma menininha curada!"},
    {"type": "paragraph", "text": "Você está triste por isso?"},
    {"type": "paragraph", "text": "Oh! não... de momento a momento, pode-se suportar muito."},
    {"type": "heading", "text": "15 de junho"},
    {"type": "paragraph", "text": "No dia 9, via claramente de longe o farol que me anunciava o porto do Céu; mas agora, já não vejo nada, tenho como os olhos vendados. Naquele dia, via o Ladrão, agora já não o vejo de maneira nenhuma. O que me dizem sobre a morte já não pode penetrar, escorrega como sobre uma laje. Está acabado! a esperança da morte está gasta. O bom Deus não quer sem dúvida que eu pense nisso como antes de adoecer. Naquele momento, esse pensamento me era necessário e muito proveitoso, eu o sentia bem. Mas hoje é o contrário. O bom Deus quer que eu me abandone como uma criancinha que não se inquiète do que se fará dela."},
    {"type": "paragraph", "text": "Você está cansada do seu estado que se prolonga? Deve bem sofrer!"},
    {"type": "paragraph", "text": "Sim, mas isso me “agrada”."},
    {"type": "paragraph", "text": "Por quê?"},
    {"type": "paragraph", "text": "Porque isso “agrada” ao bom Deus."},
    {"type": "paragraph", "text": "Ela empregava essa palavra e várias outras que não combinavam com sua maneira simples de exprimir-se habitualmente, quando queria cobrir seu pensamento com uma forma distraente para nós."},
    {"type": "paragraph", "text": "Tinha ainda adotado certas expressões ingênuas que usava na intimidade e que, em sua boca, tinham muito encanto."},
    {"type": "paragraph", "text": "Não sei quando morrerei; já não tenho nenhuma confiança na doença. Mesmo que me administrassem, ainda creria que posso voltar. Só terei realmente certeza do meu caso quando tiver passado o passo e me vir nos braços do bom Deus."},
    {"type": "paragraph", "text": "À noite"},
    {"type": "paragraph", "text": "Como eu gostaria de lhes dizer algo de gentil!"},
    {"type": "paragraph", "text": "Diz-me só se vocês me esquecerão quando estiverem no Céu."},
    {"type": "paragraph", "text": "Ah! se eu as esquecesse, parece-me que todos os santos me expulsariam do Paraíso como um feio mocho. Minha pequena Mãe, quando eu estiver lá em cima, “virei buscá-la comigo, para que, onde eu estiver, você esteja também”."},
    {"type": "paragraph", "text": "Estou feliz, não ofendo nada o bom Deus durante minha doença. Há pouco eu escrevia sobre a caridade (no caderno da sua Vida) e, muitas vezes, vieram interromper-me; então procurei não me impacientar, pôr em prática o que eu escrevia."},
    {"type": "heading", "text": "19 de junho"},
    {"type": "paragraph", "text": "Nossa prima, a Madre Marguerite (Superiora Geral em Paris das religiosas Auxiliadoras da I...C. enfermeiras) me havia enviado uma linda cesta cheia de lírios artificiais, para o dia 21, festa da Madre Marie de Gonzague. Levei-lhe essa cesta dizendo toda contente:"},
    {"type": "paragraph", "text": "“É a Superiora Geral das Auxiliadoras que me envia isso!”"},
    {"type": "heading", "text": "Ela me respondeu de repente com ardor e afeto:"},
    {"type": "paragraph", "text": "Pois bem, você é a Superiora Geral do meu coração."},
    {"type": "heading", "text": "20 de junho"},
    {"type": "paragraph", "text": "Mostrava-lhe as pequenas fotografias da Virgem-Mãe que pintara para a festa de Nossa Mãe. Ela pôs as mãos sobre as miniaturas espalhadas diante de seus olhos e, afastando os dedos, fez de modo a tocar todas as pequenas cabeças do Menino Jesus. Então disse-me: Eu as tenho todas sob meu domínio."},
    {"type": "heading", "text": "22 de junho"},
    {"type": "paragraph", "text": "Estava no jardim, na cadeira de rodas. Quando vim ter com ela à tarde disse-me:"},
    {"type": "paragraph", "text": "Como entendo bem a palavra de Nosso Senhor a N. M. Sainte Thérèse: “Sabes, minha filha, aqueles que me amam verdadeiramente? São os que reconhecem que tudo o que não se refere a mim não é senão mentira.”"},
    {"type": "paragraph", "text": "Ó minha pequena Mãe, como sinto que isso é verdade! Sim, tudo fora do bom Deus, tudo é vaidade."},
    {"type": "heading", "text": "23 de junho"},
    {"type": "paragraph", "text": "Eu lhe dizia: Ai de mim! não terei nada a dar ao bom Deus, na minha morte, tenho as mãos vazias! Isso me entristece muito."},
    {"type": "paragraph", "text": "Pois bem! você é como “bebê” (ela às vezes se dava esse nome) que, no entanto, se encontra nas mesmas condições... Mesmo que eu tivesse realizado todas as obras de S. Paulo, ainda me consideraria “servo inútil” mas é justamente isso que faz minha alegria, pois não tendo nada, receberei tudo do bom Deus."},
    {"type": "heading", "text": "25 de junho"},
    {"type": "paragraph", "text": "Festa do Sagrado Coração."},
    {"type": "paragraph", "text": "Tinham instalado ela na biblioteca, por causa do sol que entrava em sua cela. Durante o sermão, pegou um livro da Propagação da Fé. Mostrou-me em seguida uma passagem onde se fala da aparição de uma bela Senhora, vestida de branco, junto a uma criança batizada, e disse-me:"},
    {"type": "paragraph", "text": "Mais tarde, irei assim em volta das crianças batizadas..."},
    {"type": "paragraph", "text": "Durante o sermão, fugi à escola, senti que era festa. Todos os dias, não me permitiria isso. Considero meu caderno (sua vida) como meu pequeno dever."},
    {"type": "heading", "text": "26 de junho"},
    {"type": "paragraph", "text": "Ontem, grande dor no lado! depois... acabou esta manhã! Ah! quando irei embora com o bom Deus! Como eu gostaria de ir ao Céu!"},
    {"type": "heading", "text": "27 de junho"},
    {"type": "paragraph", "text": "Quando eu estiver no Céu, direi tantas coisas belas da minha pequena Mãe a todos os santos, que eles ficarão com grande vontade de a levar. Estarei sempre com minha pequena Mãe; pedirei aos santos que venham comigo às caves horríveis para a proteger, e, se não quiserem, pois bem, irei sozinha."},
    {"type": "paragraph", "text": "Isso refere-se a uma pequena aventura que me aconteceu naquele dia na cave da sacristia."},
    {"type": "heading", "text": "29 de junho"},
    {"type": "paragraph", "text": "... Isso é o que aconteceu: Como eu estava para morrer, os anjinhos fizeram toda espécie de belos preparativos para me receber; mas se cansaram e adormeceram. Ai! as criancinhas, dormem muito tempo! não se sabe quando acordarão..."},
    {"type": "paragraph", "text": "Ela nos contava muitas vezes pequenas histórias desse tipo para nos distrair de seus sofrimentos de alma e de corpo."},
    {"type": "paragraph", "text": "Como serei infeliz no Céu, se não puder fazer pequenos prazeres na terra àqueles que amo!"},
    {"type": "paragraph", "text": "À noite sentia mais sua provação de alma e certas reflexões a tinham magoado. Ela me disse:"},
    {"type": "paragraph", "text": "Minha alma está exilada, o Céu está fechado para mim e do lado da terra, é também a provação."},
    {"type": "paragraph", "text": "... Vejo bem que não creem que estou doente, mas é o bom Deus quem permite isso."},
    {"type": "paragraph", "text": "Ficarei contente no Céu se vocês compuserem para mim belos versos; parece-me que isso deve agradar aos santos."},
    {"type": "heading", "text": "30 de junho"},
    {"type": "paragraph", "text": "Falava-lhe de certos santos que levaram uma vida extraordinária, como São Simeão estilita. Ela me disse:"},
    {"type": "paragraph", "text": "Eu prefiro os santos que não têm medo de nada, como Santa Cecília que se deixa casar e que não teme..."},
    {"type": "paragraph", "text": "Meu tio havia pedido vê-la no parlatório conosco e, como de hábito, ela quase nada disse."},
    {"type": "paragraph", "text": "Como eu estava intimidada no parlatório com meu tio! Ao voltar, repreendi muito uma noviça, não me reconhecia. Que contrastes há em meu caráter! Minha timidez vem de uma extrema vergonha que sinto quando se ocupam de mim."},
  ]),
  makeChapter(5, "julho-de-1897", "Julho de 1897", "O amor no cotidiano", [
    {"type": "heading", "text": "2 de julho de 1897"},
    {"type": "paragraph", "text": "Ela foi pela última vez diante do Santíssimo no Oratório à tarde; mas estava exausta. Vi-a olhar a Hóstia por muito tempo e adivinhei que era sem nenhuma consolação, mas com muita paz no fundo do coração."},
    {"type": "paragraph", "text": "Lembro-me que, de manhã, depois da Missa, quando a Comunidade se dirigia ao Oratório para a ação de graças, ninguém pensou em a sustentar. Ela caminhava junto ao muro bem devagar. Eu não ousei lhe oferecer o braço."},
    {"type": "heading", "text": "3 de julho de 1897"},
    {"type": "paragraph", "text": "Uma de nossas amigas havia morrido e o doutor de Cornière havia falado diante dela sobre sua doença, espécie de tumor que ele não pôde definir exatamente. Esse caso lhe interessava vivamente do ponto de vista médico. « Que pena, disse ele, que eu não pude fazer a autópsia! »"},
    {"type": "heading", "text": "Ela me disse depois:"},
    {"type": "paragraph", "text": "Ah! É assim que se é indiferente uns para os outros na terra! Dir-se-ia o mesmo se fosse uma mãe ou uma irmã? Oh! como eu gostaria de ir embora deste triste mundo!"},
    {"type": "paragraph", "text": "Eu lhe confiava meus pensamentos de tristeza e desânimo depois de uma falta."},
    {"type": "paragraph", "text": "... Vocês não fazem como eu. Quando cometi uma falta que me deixa triste, eu sei bem que essa tristeza é consequência da minha infidelidade. Mas vocês acreditam que eu fico por aí?! Oh! não, nem tão tola! Eu me apresso em dizer ao bom Deus: Meu Deus, eu sei que este sentimento de tristeza eu o mereci, mas deixai-me oferecê-lo a Vós, como uma prova que Vós me enviais por amor. Eu lamento meu pecado, mas fico contente de ter esse sofrimento para Vos oferecer."},
    {"type": "paragraph", "text": "Como se faz para que vocês desejem morrer com a vossa prova contra a fé que não cessa?"},
    {"type": "paragraph", "text": "Ah! mas eu acredito mesmo no Ladrão! É para o céu que tudo tende. Como é estranho e incoerente!"},
    {"type": "paragraph", "text": "Como o leite lhe fazia mal e ela não podia tomar outra coisa naquele momento, o Sr. de C. havia indicado uma espécie de leite condensado que se devia encontrar na farmácia sob o nome de «lait maternisé». Por várias razões essa prescrição lhe causou pesar e, quando viu chegar as garrafas, pôs-se a chorar copiosamente."},
    {"type": "paragraph", "text": "À tarde, sentiu necessidade de sair de si mesma e nos disse com ar triste e doce:"},
    {"type": "paragraph", "text": "Preciso de um alimento para minha alma; leiam-me uma vida de santo."},
    {"type": "paragraph", "text": "Querem a vida de S. Francisco de Assis? Isso a distrairá quando ele fala dos passarinhos."},
    {"type": "paragraph", "text": "Não, não para me distrair, mas para ter exemplos de humildade."},
    {"type": "paragraph", "text": "Quando vocês estiverem morta, lhes porão uma palma na mão."},
    {"type": "paragraph", "text": "Sim, mas terei que soltá-la quando eu quiser, para dar de mãos cheias graças à minha pequena Mãe. Terei que fazer tudo quanto me agradar."},
    {"type": "paragraph", "text": "À noite"},
    {"type": "paragraph", "text": "Até os santos que me abandonam! Pedi a Santo Antônio, durante as Matinas, que me fizesse encontrar o nosso lenço que eu havia perdido. Acreditam que ele me atendeu? Pois ele bem que não o fez! Mas não faz mal, eu lhe disse que o amava assim mesmo."},
    {"type": "paragraph", "text": "Durante as Matinas eu via as estrelas brilhar, depois ouvia o ofício, isso me agradava."},
    {"type": "paragraph", "text": "A janela de sua cela estava aberta"},
    {"type": "heading", "text": "4 de julho"},
    {"type": "paragraph", "text": "O bom Deus me ajudou, e eu superei minha tristeza a respeito do leite maternisado..."},
    {"type": "paragraph", "text": "À noite"},
    {"type": "paragraph", "text": "Nosso Senhor morreu na Cruz, em angústias, e, no entanto, foi a mais bela morte de amor. É a única que se viu; não se viu a da Santíssima Virgem. Morrer de amor não é morrer em arroubos. Eu vos confesso francamente, parece-me que é o que eu experimentoo."},
    {"type": "paragraph", "text": "Oh! como pressinto que vocês hão de sofrer!"},
    {"type": "paragraph", "text": "Que importa! o sofrimento pode atingir limites extremos, mas tenho certeza de que o bom Deus nunca me abandonará."},
    {"type": "paragraph", "text": "Tenho grande gratidão para com o Pe. Alexis, ele me fez muito bem. O Pe. Pichon me tratava demais como criança; no entanto também me fez bem ao dizer que eu não havia cometido pecado mortal."},
    {"type": "heading", "text": "5 de julho"},
    {"type": "heading", "text": "Eu lhe falava de minhas fraquezas, ela me disse:"},
    {"type": "paragraph", "text": "Também me acontecem fraquezas, mas eu me regozijo com elas. Nem sempre me coloco acima dos nadas da terra; por exemplo, serei provocada por uma tolice que terei dito ou feito. Então eu me recolho em mim mesma e digo: Ah! ainda estou no mesmo ponto que antes! Mas eu digo isso com grande doçura e sem tristeza. É tão doce sentir-se fraca e pequena!"},
    {"type": "paragraph", "text": "Não fiquem tristes ao me ver doente, minha pequena Mãe, porque veis como o bom Deus me torna feliz. Estou sempre alegre e contente."},
    {"type": "paragraph", "text": "Depois de ter olhado uma imagem que representa Nosso Senhor com duas criancinhas, da qual a menor está sobre seus joelhos e a outra aos seus pés, beijando-lhe a mão:"},
    {"type": "paragraph", "text": "Eu sou esse bem pequenininho que subiu no colo de Jesus, que puxa tão mansamente sua pernazinha, que levanta sua cabecinha e o afaga sem temer nada. O outro pequeno não me agrada tanto. Ele se mantém como uma pessoa grande; lhe disseram alguma coisa... ele sabe que se deve respeito a Jesus..."},
    {"type": "heading", "text": "6 de julho"},
    {"type": "paragraph", "text": "Ela acabara de cuspir sangue. Eu lhe disse: Vai nos deixar então?!"},
    {"type": "paragraph", "text": "Mas não! O Pe. Vigário me disse: «Tereis um grande sacrifício a fazer ao deixardes vossas irmãs.» Respondi: «Mas, meu Padre, acho que não as deixarei; ao contrário, estarei ainda mais perto delas depois da minha morte.»"},
    {"type": "paragraph", "text": "Creio que para minha morte será preciso ter a mesma paciência que para os outros grandes acontecimentos da minha vida. Vede: entrei jovem no Carmelo, e no entanto, depois que tudo foi decidido, foi preciso esperar 3 meses; para minha roupa, o mesmo; para minha profissão, o mesmo ainda. Pois bem, para minha morte será igual, ela chegará em breve, mas será preciso esperar."},
    {"type": "paragraph", "text": "Quando eu estiver no Céu, avançarei para junto do bom Deus, como a pequena sobrinha da Ir. Elisabeth diante da grade do locutório — Sabeis, quando ela recitava seu cumprimento e terminava com uma reverência levantando os braços e dizendo: «A felicidade para todos os que amo.» —"},
    {"type": "paragraph", "text": "O bom Deus me dirá: «O que queres, minha filhinha?» E eu responderei: «A felicidade para todos os que amo.» Farei o mesmo diante de todos os santos."},
    {"type": "paragraph", "text": "Estais bem alegre hoje, sente-se que vedes o Ladrão."},
    {"type": "paragraph", "text": "Sim, toda vez que estou mais doente, eu o revejo. Mas mesmo que eu não o visse, eu o amo tanto que fico sempre contente com o que ele faz. Não o amaria menos se ele não viesse me roubar, ao contrário... Quando ele me engana, faço-lhe todo tipo de elogios, ele não sabe mais como agir comigo."},
    {"type": "paragraph", "text": "Li um belo trecho nas Reflexões da Imitation. É um pensamento do Sr. de Lamennais — azar! — é belo, no entanto."},
    {"type": "paragraph", "text": "(Ela acreditava e nós também que esse abade de Lamennais havia morrido na impenitência.)"},
    {"type": "paragraph", "text": "Nosso Senhor no Horto dos Oliveiras gozava de todas as delícias da Trindade, e contudo sua agonia não deixou de ser cruel. É um mistério, mas eu vos asseguro que entendo alguma coisa por causa do que eu mesma experimento."},
    {"type": "paragraph", "text": "Coloquei uma lâmpada diante da Virgem do Sorriso para obter que ela não continuasse a cuspir sangue."},
    {"type": "paragraph", "text": "Vós não vos regozijais, pois, que eu morra! Ah! para me regozijar, eu teria que continuar a cuspir sangue. Mas acabou por hoje!"},
    {"type": "paragraph", "text": "8h15. — Eu lhe trazia a lamparina que tinham esquecido de subir para ela. Eu lhe havia prestado outros pequenos serviços. Ela se mostrou muito comovida e me disse:"},
    {"type": "paragraph", "text": "Sempre agistes assim comigo... Não posso dizer-vos minha gratidão."},
    {"type": "heading", "text": "Enxugando as lágrimas:"},
    {"type": "paragraph", "text": "Choro porque estou muito tocada pelo que fizestes por mim desde minha infância."},
    {"type": "paragraph", "text": "Oh! tudo o que eu vos devo! Mas quando eu estiver no Céu, direi a verdade, direi aos Santos: Foi minha pequena Mãe que me deu tudo o que vos agrada em mim."},
    {"type": "paragraph", "text": "Quando então virá o Juízo Final? Oh! como eu gostaria de estar presente nesse momento! E o que haverá depois?!"},
    {"type": "paragraph", "text": "Faço muitos pequenos sacrifícios..."},
    {"type": "heading", "text": "7 de julho"},
    {"type": "heading", "text": "Depois de ter novamente cuspido sangue:"},
    {"type": "paragraph", "text": "Bebê logo irá ver o bom Deus..."},
    {"type": "paragraph", "text": "Tendes medo da morte agora que a vedes de tão perto?"},
    {"type": "paragraph", "text": "Ah! cada vez menos!"},
    {"type": "paragraph", "text": "Tendes medo do Ladrão? Desta vez ele está à porta!"},
    {"type": "paragraph", "text": "Não, ele não está à porta, já entrou. Mas que dizeis, minha pequena Mãe! Se eu tivesse medo do Ladrão! Como quereis que eu tenha medo de alguém que eu amo tanto?!"},
    {"type": "paragraph", "text": "Pedi-lhe que me contasse ainda o que lhe acontecera depois de sua oferta ao Amor. Ela me disse primeiro:"},
    {"type": "paragraph", "text": "Minha pequena mãe, confiei-o a vós no dia mesmo; mas não lhe prestastes atenção."},
    {"type": "paragraph", "text": "De fato, eu parecera não ligar importância."},
    {"type": "paragraph", "text": "Pois bem, eu começava meu Caminho da Cruz, e eis que de repente fui tomada de um amor tão violento pelo bom Deus que só posso explicar dizendo que foi como se me tivessem mergulhado inteira no fogo. Oh! que fogo e que doçura ao mesmo tempo! Eu ardia de amor e sentia que um minuto, um segundo mais, não teria podido suportar essa ardência sem morrer. Compreendi então o que dizem os santos sobre esses estados que eles tantas vezes experimentaram. Para mim, eu o experimentei apenas uma vez e um único instante, depois caí de novo na minha secura habitual."},
    {"type": "heading", "text": "Um pouco mais tarde:"},
    {"type": "paragraph", "text": "Desde os 14 anos, eu também tinha assaltos de amor; ah! como eu amava o bom Deus! Mas não era de jeito nenhum como depois da minha oferta ao Amor, não era uma verdadeira chama que me queimasse."},
    {"type": "paragraph", "text": "Esta palavra de Jó: «Mesmo que Deus me matasse, ainda assim esperaria nele», encantou-me desde a infância. Mas demorei muito antes de me estabelecer nesse grau de abandono. Agora estou nele; o bom Deus me pôs aí, tomou-me em seus braços e me pousou lá..."},
    {"type": "paragraph", "text": "Pedi-lhe que dissesse algumas palavras de edificação e amabilidade ao Sr. de Cornière."},
    {"type": "paragraph", "text": "Ah! minha pequena Mãe, isso não é do meu feitio... Que o Sr. de Cornière pense o que quiser. Não gosto senão da simplicidade, tenho horror da «falsidade». Afirmo-vos que agir como desejais seria mal da minha parte."},
    {"type": "paragraph", "text": "Enfim, faço-me efeito de estar totalmente doente. Nunca esquecerei a cena desta manhã quando eu cuspia sangue; o Sr. de Cornière tinha ar consternado."},
    {"type": "paragraph", "text": "Vede, é por vossa causa que o bom Deus me trata tão docemente. Nada de vesicatório, só remédios suaves. Sofro, mas não a ponto de gritar."},
    {"type": "heading", "text": "Depois de um momento, com ar malicioso:"},
    {"type": "paragraph", "text": "Contudo, Ele nos mandou provas «para gritar»... e nós não «gritamos» no entanto..."},
    {"type": "paragraph", "text": "Ela fazia alusão à nossa grande prova de família."},
    {"type": "paragraph", "text": "Quanto aos ‘remédios suaves’, eles nem sempre o foram e seus sofrimentos se tornaram terríveis."},
    {"type": "paragraph", "text": "Sou como um pobre «pequeno lobo cinzento» que tem muita vontade de voltar para sua floresta e que se força a viver nas casas."},
    {"type": "paragraph", "text": "Nosso bom pai, nos Buissonnets, às vezes a chamava «meu pequeno lobo cinzento»."},
    {"type": "paragraph", "text": "Acabo de ver na parede um pequeno pardal que esperava pacientemente, soltando de vez em quando um pequeno gritinho de chamada, para que seus pais viessem buscá-lo e lhe dessem de comer; pensei que me assemelhava a ele."},
    {"type": "heading", "text": "Eu lhe dizia que gostava de elogios:"},
    {"type": "paragraph", "text": "Vou-me lembrar disso no Céu…"},
    {"type": "heading", "text": "8 de julho"},
    {"type": "paragraph", "text": "Ela estava tão doente que se falava da Extrema-Unção. Nesse dia a desceram de sua cela para a enfermaria. Não podia mais sustentar-se, foi preciso carregá-la. Ainda estando em sua cela e vendo que pensavam em administrá-la, disse com tom de surpresa alegre:"},
    {"type": "paragraph", "text": "Parece-me que estou sonhando!... Enfim, não estão loucos..."},
    {"type": "paragraph", "text": "Pe. Youf e Sr. de Cornière"},
    {"type": "paragraph", "text": "Eu só temo uma coisa, que isso mude."},
    {"type": "paragraph", "text": "Quis procurar comigo os pecados que poderia ter cometido pelos sentidos, a fim de se acusar antes da Extrema-Unção. Estávamos no olfato, ela me disse:"},
    {"type": "paragraph", "text": "Lembro-me que na minha última viagem de Alençon a Lisieux, usei uma garrafa de água de colônia que a Sra. Tifenne me dera e foi com prazer."},
    {"type": "paragraph", "text": "Todas nós queríamos falar com ela."},
    {"type": "paragraph", "text": "Muito gente que tem algo a dizer!"},
    {"type": "paragraph", "text": "Ela estava transbordante de alegria e esforçava-se por comunicá-la."},
    {"type": "paragraph", "text": "Se, quando eu estiver no Céu, não puder vir fazer-vos pequenas «brincadeirinhas» na terra, irei chorar num pequeno «cantinho»."},
    {"type": "heading", "text": "A mim:"},
    {"type": "paragraph", "text": "Tendes o nariz comprido, ele cheirará bem em vós mais tarde..."},
    {"type": "heading", "text": "Olhando suas mãos emagrecidas:"},
    {"type": "paragraph", "text": "Está ficando já esqueleto, é o que me «agrada»."},
    {"type": "paragraph", "text": "Não sabeis: vou logo ser uma «morbida»."},
    {"type": "paragraph", "text": "... Dá-me a impressão de um mastro da Cocagne; escorreguei mais de uma vez, depois, de repente, estou em cima!"},
    {"type": "paragraph", "text": "Prefiro ser reduzida a pó do que ser conservada como Sta. Catarina de Bolonha. Conheço só Sta. Crispina que tenha saído do túmulo com honra."},
    {"type": "paragraph", "text": "O corpo desse santo está admiravelmente conservado em seu Convento dos Franciscanos de Roma."},
    {"type": "paragraph", "text": "[S. Crispiniano de Viterbo Casa I Cappuccini Via Veneto 21, 00187 Roma]"},
    {"type": "heading", "text": "Falando consigo mesma:"},
    {"type": "paragraph", "text": "É alguma coisa estar ali a agonizar!... Que importa afinal! já fui por vezes agonizada por tolices..."},
    {"type": "paragraph", "text": "Com ar sério e doce, não me lembro de qual ocasião, mas sei que ela fora incompreendida:"},
    {"type": "paragraph", "text": "A Santíssima Virgem fez bem em guardar tudo em seu «pequeno» coração... Não se pode censurar-me por agir como ela..."},
    {"type": "paragraph", "text": "Os pequeninos anjos se divertiram muito pregando-me pequenas travessuras... Todos se exercitaram a esconder-me a luz que me mostrava minha próxima hora."},
    {"type": "paragraph", "text": "Eles esconderam também a Santíssima Virgem?"},
    {"type": "paragraph", "text": "Não, a Santíssima Virgem jamais será oculta para mim, porque eu a amo demais."},
    {"type": "paragraph", "text": "Desejo muito a Extrema-Unção, azar se zombarem de mim depois."},
    {"type": "paragraph", "text": "Se ela voltasse à saúde, pois sabia que certas irmãs não a julgavam em perigo de morte."},
    {"type": "paragraph", "text": "Oh! certamente chorarei ao ver o bom Deus!... Não, contudo, não se pode chorar no Céu... Mas sim, pois Ele disse: «Enxugarei todas as lágrimas dos vossos olhos.»"},
    {"type": "paragraph", "text": "Ofereço-vos meus pequenos frutos de alegria tais como o bom Deus me os dá."},
    {"type": "paragraph", "text": "No Céu obterei muitas graças para aqueles que me fizeram bem. Para a pequena Mãe, tudo. Nem tudo poderá mesmo vos servir, haverá muito para vos «alegrar»."},
    {"type": "paragraph", "text": "Se soubésseis como o bom Deus será doce para mim! Mas se Ele for um tantinho não doce, ainda assim o acharei doce... Se eu for ao Purgatório, ficarei muito contente; andarei como os três hebreus na fornalha, passearei nas chamas cantando o cântico do Amor. Oh! como seria feliz, se indo ao purgatório pudesse libertar outras almas, sofrer em seu lugar, pois então faria bem, libertaria os cativos."},
    {"type": "paragraph", "text": "Avisou-me que, mais tarde, muitos jovens padres, sabendo que ela fora dada como irmã espiritual a dois missionários, pedirão aqui a mesma graça. Advertiu-me que isso poderia tornar-se um grande perigo."},
    {"type": "paragraph", "text": "Qualquer uma escreveria o que eu escrevo e receberia os mesmos elogios, a mesma confiança. É pela oração e pelo sacrifício que podemos apenas ser úteis à Igreja. A correspondência deve ser muito rara e não se deve permitir de modo algum a certas religiosas que dela estariam preocupadas, creriam fazer maravilhas, e não fariam na realidade senão ferir sua alma e talvez cair nos sutis laços do demônio."},
    {"type": "heading", "text": "Insistindo mais:"},
    {"type": "paragraph", "text": "Minha Mãe, o que acabo de vos dizer é bem importante, rogo-vos que não o esqueçais mais tarde. No Carmelo não se deve falsificar moeda para comprar almas... E muitas vezes as belas palavras que se escrevem e as belas palavras que se recebem são uma troca de falsa moeda."},
    {"type": "heading", "text": "Para nos fazer rir:"},
    {"type": "paragraph", "text": "Gostaria de ser posta numa pequena caixa da Gennin, não no caixão."},
    {"type": "paragraph", "text": "Ela brincava com a palavra «bière» (caixão/cerveja). Havia-se enviado ao Carmelo belíssimas flores artificiais em caixas compridas e muito bem acondicionadas, da Casa Gennin de Paris."},
    {"type": "paragraph", "text": "... É tão bom ter sofrimento, isso leva a ser regrada e caritativa."},
    {"type": "heading", "text": "9 de julho"},
    {"type": "paragraph", "text": "Não queria tristeza à sua volta, nem em meu tio."},
    {"type": "paragraph", "text": "Quero que todos façam «a farra» na Musse. Eu faço a farra espiritual o dia inteiro."},
    {"type": "paragraph", "text": "Essa farra não é alegre."},
    {"type": "paragraph", "text": "Eu a acho muito alegre."},
    {"type": "paragraph", "text": "Minha Irmã Geneviève precisará de mim... Mas de resto, voltarei."},
    {"type": "paragraph", "text": "Depois da visita de Nosso Padre, fiz-lhe a observação de que não se havia tomado bem para obter ser administrada, que não parecia nada doente quando recebia visitas."},
    {"type": "paragraph", "text": "Não conheço a profissão!"},
    {"type": "paragraph", "text": "... Queria ir-me embora!..."},
    {"type": "paragraph", "text": "Provavelmente morrereis no dia 16 de julho, festa de N. Sra. do Monte Carmelo, ou no dia 6 de agosto, festa da Sagrada Face."},
    {"type": "paragraph", "text": "Comais tâmaras à vontade, eu não quero mais comê-las... Fui muito enganada pelas datas."},
    {"type": "paragraph", "text": "... Por que seria eu mais à prova que outra de ter medo da morte? Não digo como São Pedro: «Não vos renunciarei jamais.»"},
    {"type": "heading", "text": "Falava-se da santa pobreza:"},
    {"type": "paragraph", "text": "Santa Pobreza! Que engraçado, uma santa que não irá para o Céu!"},
    {"type": "heading", "text": "Eu havia sofrido:"},
    {"type": "paragraph", "text": "Meu amor deveria vos consolar."},
    {"type": "heading", "text": "Às presentes:"},
    {"type": "paragraph", "text": "Vou-me ajeitar com minha pequena Mãe."},
    {"type": "heading", "text": "À noite, só para mim:"},
    {"type": "paragraph", "text": "... Oh! vá, não me engano, sei bem que tudo o que fazeis por mim é por amor..."},
    {"type": "paragraph", "text": "Tiveram capturado um rato na enfermaria; ela nos fez toda uma história, pedindo-nos que lhe trouxéssemos o rato ferido, que o pousaria ao lado dela e o faria examinar pelo doutor. Ríamos de bom grado e ela ficava contente por ter nos distraído."},
    {"type": "heading", "text": "10 de julho"},
    {"type": "paragraph", "text": "... As criancinhas, isso não se condena."},
    {"type": "paragraph", "text": "O que escrevestes poderia um dia ir até ao Santo Padre."},
    {"type": "heading", "text": "Rindo:"},
    {"type": "paragraph", "text": "Et nunc et semper!"},
    {"type": "paragraph", "text": "Mostrando-me com gesto infantil a imagem da Santíssima Virgem amamentando o Menino Jesus:"},
    {"type": "paragraph", "text": "Só isso é bom leitinho, há que dizer a Sr. de Cornière."},
    {"type": "paragraph", "text": "Era sábado e ela havia cuspido sangue à meia-noite."},
    {"type": "paragraph", "text": "O Ladrão, ele tornou sua mamãe ladra... Então ela veio à meia-noite obrigar o Ladrão a desabotoar-se; ou então veio sozinha, se o Ladrão não quis vir."},
    {"type": "paragraph", "text": "Não me prolongarão um minuto a mais que o Ladrão quiser."},
    {"type": "paragraph", "text": "só para mim"},
    {"type": "paragraph", "text": "Fazem-se demasiados esforços por assuntos que não valem a pena."},
    {"type": "paragraph", "text": "sorrindo"},
    {"type": "paragraph", "text": "... Quando fazeis algo assim, o que é ainda muito feio, é que temeis demais as consequências..."},
    {"type": "paragraph", "text": "Sois como um passarinho medroso que nunca viveu entre homens, tendes sempre medo de ser apanhada. Eu, nunca tive medo de ninguém; sempre fui onde quis... Teria antes passado entre as pernas deles..."},
    {"type": "paragraph", "text": "Segurando seu Crucifixo depois de o beijar às 3 horas, fazia-se de que ia tirar a coroa e os pregos."},
    {"type": "paragraph", "text": "Voltando ao incidente da noite, disse de maneira encantadora: olhando a imagem da Virgem-Mãe presa ao fundo de sua cama no cortinado:"},
    {"type": "paragraph", "text": "A Santíssima Virgem não é ladra por natureza... mas desde que teve seu Filho, Ele a ensinou a profissão..."},
    {"type": "heading", "text": "Depois de uma pausa:"},
    {"type": "paragraph", "text": "Todavia o Menino Jesus é ainda muito pequeno para ter essas ideias... Ele não pensa muito em roubar no seio de sua Mãe... Sim! já pensa nisso, sabe bem que virá me roubar."},
    {"type": "paragraph", "text": "A que idade?"},
    {"type": "paragraph", "text": "Aos 24 anos."},
    {"type": "paragraph", "text": "Falava-se da morte e das contrações que muitas vezes se produzem então no rosto. Ela retomou:"},
    {"type": "paragraph", "text": "Se isso me acontecer, não vos entristeçais, pois logo depois só farei sorrisos."},
    {"type": "paragraph", "text": "Minha Irmã Geneviève olhava a tampa de uma caixinha de batismo dizendo que a linda cabeça que via ali lhe serviria de modelo para uma cabeça de anjo. Nossa pequena Teresa quis vê-la, mas ninguém pensou em mostrá-la e ela nada pediu. Soube disso mais tarde."},
    {"type": "paragraph", "text": "O que terei que pensar olhando a janela da tua cela quando tiveres deixado a terra? Terei o coração muito pesado."},
    {"type": "paragraph", "text": "Ah! pensareis que eu sou muito feliz, que aí lutei e sofri muito... Teria gostado de aí morrer."},
    {"type": "paragraph", "text": "Durante as Matinas"},
    {"type": "paragraph", "text": "Vem-lhe ao pensamento que não está seriamente doente, que o médico se engana quanto ao seu estado. Confia-me suas provas e acrescenta:"},
    {"type": "paragraph", "text": "Se minha alma não estivesse toda preenchida de antemão pelo abandono à vontade do bom Deus, se tivesse que se deixar submergir pelos sentimentos de alegria ou de tristeza que se sucedem tão depressa na terra, seria um fluxo de dor bem amargo e eu não poderia suportá-lo. Mas essas alternâncias só tocam a superfície da minha alma... Ah! no entanto são grandes provas!"},
    {"type": "paragraph", "text": "Acho que não é a Santíssima Virgem que me faz essas peças!... Ela é forçada pelo bom Deus! então... Ele lhe diz para me provar a fim de que eu lhe dê mais testemunhos de abandono e de amor."},
    {"type": "paragraph", "text": "só para mim"},
    {"type": "paragraph", "text": "... Sempre estais aí para me consolar... Encheis de doçura meus últimos dias."},
    {"type": "heading", "text": "11 de julho"},
    {"type": "heading", "text": "Ela recita toda a estrofe:"},
    {"type": "paragraph", "text": "«Visto que o Filho de Deus quis que sua Mãe"},
    {"type": "paragraph", "text": "Fosse sujeita à noite, à angústia do coração,"},
    {"type": "paragraph", "text": "Então, é portanto bem sofrer na terra?"},
    {"type": "paragraph", "text": "etc..."},
    {"type": "paragraph", "text": "Já não vedes a «Ladra»?"},
    {"type": "paragraph", "text": "Mas sim, eu a vejo! Não compreendes! Ela é bem livre de não me roubar... Ah! «olhei para a minha direita... e ninguém me conhece»... só o bom Deus pode me compreender."},
    {"type": "paragraph", "text": "Durante as Matinas"},
    {"type": "paragraph", "text": "Falou-me de suas orações de antigamente, à noite durante o silêncio de verão, e disse-me haver então compreendido por experiência o que é um «assalto de espírito». Falou-me de outra graça desse gênero recebida na gruta de Santa Madalena, no mês de julho de 1889, graça que foi seguida de vários dias de 'quitação'."},
    {"type": "paragraph", "text": "... Havia como um véu posto para mim sobre todas as coisas da terra... Eu estava inteiramente escondida sob o véu da Santíssima Virgem. Naquele tempo, tinham-me encarregado do refeitório e lembro-me que fazia as coisas como não as fazendo, era como se me tivessem emprestado um corpo. Fiquei assim durante uma semana inteira."},
    {"type": "paragraph", "text": "Eu lhe falava do manuscrito de sua Vida, do bem que faria às almas."},
    {"type": "paragraph", "text": "... Mas como se verá bem que tudo vem do bom Deus; e a glória que eu tiver disso será um dom gratuito que não me pertencerá; todo mundo verá bem..."},
    {"type": "paragraph", "text": "Falou-me da Comunhão dos Santos e explicou como os bens uns dos outros serão bens comuns."},
    {"type": "paragraph", "text": "... Como uma mãe se orgulha de seus filhos, assim o seremos uns dos outros sem a menor inveja."},
    {"type": "paragraph", "text": "Ai! como vivi pouco! A vida sempre me pareceu muito curta. Meus dias de infância, parece-me que foi ontem."},
    {"type": "paragraph", "text": "Poder-se-ia crer que é porque não pequei que tenho tão grande confiança no bom Deus. Dizei bem, minha Mãe, que se eu tivesse cometido todos os crimes possíveis, teria sempre a mesma confiança, sinto que toda essa multidão de ofensas seria como uma gota d'água lançada num braseiro ardente. Contareis depois a história da pecadora convertida que morreu de amor; as almas compreenderão imediatamente, pois é um exemplo tão marcante do que eu gostaria de dizer, mas essas coisas não se podem exprimir."},
    {"type": "paragraph", "text": "À noite, repetiu versos de «A jovem tuberculosa», creio. Fez-o com um ar tão doce..."},
    {"type": "paragraph", "text": "... Meus dias estão condenados, vou deixar a terra"},
    {"type": "paragraph", "text": "Vou dizer-vos adeus sem esperança de retorno;"},
    {"type": "paragraph", "text": "Vós que me amastes, belo Anjo tutelar,"},
    {"type": "paragraph", "text": "Lançai sobre mim vossos doces olhares de amor."},
    {"type": "paragraph", "text": "Quando virdes cair, cair as folhas mortas"},
    {"type": "paragraph", "text": "Se me amastes, rogar-lhe-eis a Deus por mim."},
    {"type": "paragraph", "text": "... Grande paz em minha alma... Meu pequeno barco foi posto a flutuar. Sei que não voltarei, mas estou resignada a ficar doente vários meses, enquanto o bom Deus quiser."},
    {"type": "paragraph", "text": "Como o bom Deus a favoreceu! Que pensais dessa predileção?"},
    {"type": "paragraph", "text": "Penso que «o Espírito de Deus sopra onde quer»."},
    {"type": "heading", "text": "12 de julho"},
    {"type": "paragraph", "text": "Contou-me que antigamente teve de sofrer uma dura luta a propósito de uma velinha a preparar para a família de Madre Maria de Gonzaga que chegara inesperadamente para passar a noite entre as irmãs tourières. A luta foi tão violenta e lhe vinham tais pensamentos contra a autoridade, que, para não sucumbir, teve de implorar com insistência o socorro do bom Deus. Ao mesmo tempo aplicou-se o melhor possível ao que lhe fora pedido. Era durante o silêncio da noite. Era porteira e Ir. Sta. Raphaël era sua primeira de emprego."},
    {"type": "paragraph", "text": "Para me vencer, pensei que preparava a velinha para a Sta. Virgem e o Menino Jesus; então fazia-o com um cuidado incrível, sem deixar sequer um grão de pó, e pouco a pouco senti grande apaziguamento e grande doçura. As Matinas tocaram e não pude ir imediatamente, mas sentia-me numa disposição tal, recebera tal graça que se minha Ir. Sta. Raphaël viesse e me dissesse, por exemplo, que me enganara de lâmpada, que era preciso preparar outra, eu com felicidade lhe teria obedecido. A partir desse dia, tomei a resolução de nunca mais considerar se as coisas mandadas me pareciam úteis ou não."},
    {"type": "paragraph", "text": "Ir. Maria da Eucaristia dizia que eu era admirável..."},
    {"type": "paragraph", "text": "... Mãe admirável! Oh! não, antes Mãe amável, porque o amor vale mais que a admiração."},
    {"type": "heading", "text": "A Madre Maria de Gonzaga:"},
    {"type": "paragraph", "text": "Nada fica nas mãos. Tudo o que tenho, tudo o que ganho, é para a Igreja e as almas. Que eu viva até os 80 anos, serei sempre tão pobre."},
    {"type": "heading", "text": "13 de julho"},
    {"type": "paragraph", "text": "Vejo bem que terei que velar pelos frutos quando estiver no Céu, mas não se deve matar os passarinhos, ou então, não vos enviarão esmolas."},
    {"type": "paragraph", "text": "Ebrandando o braço gentilmente para a imagem do Menino Jesus:"},
    {"type": "paragraph", "text": "Sim, sim!..."},
    {"type": "paragraph", "text": "Será preciso que o bom Deus faça todas as minhas vontades no Céu, porque nunca fiz minha vontade na terra."},
    {"type": "paragraph", "text": "Vós nos olhareis do alto do Céu, não é?"},
    {"type": "paragraph", "text": "Não, eu desceria!"},
    {"type": "paragraph", "text": "Durante a noite compusera o verso para a Comunhão:"},
    {"type": "paragraph", "text": "Tu que conheces, etc."},
    {"type": "heading", "text": "A esse respeito, disse-me:"},
    {"type": "paragraph", "text": "Componho-o muito facilmente, é extraordinário; acreditava que não podia mais fazer versos."},
    {"type": "paragraph", "text": "Não digo: «Se é duro viver no Carmelo, é doce aí morrer» mas: «Se é doce viver no Carmelo, é ainda mais doce aí morrer.»"},
    {"type": "paragraph", "text": "O médico a havia encontrado melhor do que de costume."},
    {"type": "heading", "text": "Segurando depois o lado de que sofria muito:"},
    {"type": "paragraph", "text": "Sim, sim, vai melhor que o habitual!..."},
    {"type": "paragraph", "text": "Parecia-me que estava com o coração pesado, apesar de seu ar alegre e contente, e eu lhe disse:"},
    {"type": "paragraph", "text": "É para não nos entristecer que tomais esse ar e dizeis palavras alegres, não é?"},
    {"type": "paragraph", "text": "... Ajo sempre sem «falsidade»..."},
    {"type": "paragraph", "text": "Ofereceram-lhe vinho de Baudon."},
    {"type": "paragraph", "text": "Não quero mais do vinho da terra... quero beber do vinho novo no reino de meu Pai."},
    {"type": "paragraph", "text": "... Quando minha Ir. Geneviève vinha ao locutório, não podia dizer-lhe em meia hora tudo o que desejaria. Então, na semana, quando tinha uma luz ou se eu me arrependia de ter esquecido de lhe dizer algo, pedia ao bom Deus que lhe fizesse saber e compreender o que pensava, e, no próximo locutório, ela me dizia justamente o que eu pedira ao bom Deus que lhe fizesse saber."},
    {"type": "paragraph", "text": "... No começo, quando ela estava triste e eu não conseguia consolá-la, ia-me embora com o coração angustiado, mas logo compreendi que não era eu que podia consolar uma alma; e então não tinha mais desgosto quando ela partia toda triste. Pedia ao bom Deus que suplementasse minha impotência e sentia que Ele me atendia; eu percebia isso no locutório depois... Desde então, quando fiz involuntariamente alguém sofrer, peço ao bom Deus que repare isso e não me atormento mais."},
    {"type": "paragraph", "text": "Peço-vos que façais um ato de amor ao bom Deus e uma invocação a todos os santos; são todos meus «pequenos» parentes lá em cima."},
    {"type": "paragraph", "text": "... Desejo que me comprem três pequenos selvagens: um pequeno Marie-Louis-Martin, um pequeno Marie-Théophane; uma menina entre os dois que se chama Marie-Cécile."},
    {"type": "heading", "text": "Depois de um momento:"},
    {"type": "paragraph", "text": "Mais uma pequena Marie-Thérèse."},
    {"type": "paragraph", "text": "Em vez de deixar gastar dinheiro para comprar coroas depois de minha morte."},
    {"type": "paragraph", "text": "Falou-me ainda da Comunhão dos Santos."},
    {"type": "paragraph", "text": "... Com as virgens seremos como as virgens; com os doutores como os doutores; com os mártires como os mártires, porque todos os Santos são nossos parentes; mas aqueles que seguiram a via da infância espiritual guardarão sempre os encantos da infância."},
    {"type": "paragraph", "text": "Desenvolveu-me esses pensamentos"},
    {"type": "paragraph", "text": "... Desde a infância, o bom Deus me deu o sentimento profundo de que morreria jovem."},
    {"type": "heading", "text": "… Olhando-me com ternura:"},
    {"type": "paragraph", "text": "Tens um rosto!... «pois»... o terás sempre... Vou reconhecer-te bem, vamos!"},
    {"type": "paragraph", "text": "O bom Deus sempre me fez desejar o que Ele queria me dar."},
    {"type": "heading", "text": "A nós três:"},
    {"type": "paragraph", "text": "Não penseis que, quando eu estiver no Céu, vos farei cair no bico alvéolas de cotovia assadas... Não é o que tive nem o que desejei ter. Talvez tereis grandes provações, mas vos enviarei luzes que vos as farão apreciar e amar. Sois obrigadas a dizer como eu: «Senhor, nos encheis de alegria por tudo o que fazeis.»"},
    {"type": "paragraph", "text": "Não imagineis que sinto pela morte uma alegria viva, como por exemplo sentia outrora ao ir passar um mês a Trouville ou a Alençon; já não sei o que são alegrias vivas. Além disso, não faço festa de gozar, não é isso que me atrai. Não posso pensar muito na felicidade que me espera no Céu; uma única expectativa faz bater meu coração, é o amor que receberei e o que poderei dar. E depois penso em todo o bem que gostaria de fazer depois da minha morte: batizar as criancinhas, ajudar os padres, os missionários, toda a Igreja..."},
    {"type": "paragraph", "text": "... mas primeiro consolar minhas pequenas irmãs..."},
    {"type": "paragraph", "text": "... Esta noite ouvia uma música ao longe e pensei que em breve ouviria melodias incomparáveis, mas esse sentimento de alegria foi apenas passageiro."},
    {"type": "paragraph", "text": "Pedi-lhe que me precisasse seus ofícios no Carmelo."},
    {"type": "paragraph", "text": "Desde minha entrada no Carmelo, fui posta na lingerie com a Madre Sub-priotessa (Ir. Maria dos Anjos), tinha além disso a escada e o dormitório para varrer."},
    {"type": "paragraph", "text": "... Lembro-me que me custava muito pedir à Nossa Mestra que fizesse mortificações no refeitório, mas nunca cedi às minhas repugnâncias, parecia-me que o crucifixo do pátio que via pela janela da lingerie se voltava para mim para me pedir esse sacrifício."},
    {"type": "paragraph", "text": "Foi nessa época que eu ia arrancar erva às 4h30, o que desagradava Nossa Mãe."},
    {"type": "paragraph", "text": "Depois da minha veste, fui posta no refeitório até os 18 anos, eu o varria e punha a água e a cerveja. Nas Quarenta Horas de 1891, fui posta na sacristia com minha Ir. Sta. Stanislas. A partir de junho do ano seguinte, fiquei dois meses sem ofício, isto é, durante esse tempo, pintei os anjos do oratório e fui terceira da depositária. Após esses dois meses fui posta no turno com minha Ir. Sta. Raphaël, guardando a pintura. Esses dois empregos até as eleições de 1896 onde pedi ajudar minha Ir. M. de Sta. Joseph na lingerie, nas circunstâncias que sabeis..."},
    {"type": "paragraph", "text": "Contou-me depois como a achavam lenta, pouco devotada nos ofícios, eu mesma acreditei nisso; e de fato lembramos juntas quanto a repreendi severamente por um guardanapo do refeitório que ela guardara muito tempo em sua cesta sem remendar. Eu a acusava de negligência e estava enganada, porque foi o tempo que lhe faltou. Dessa vez, sem se desculpar de modo algum, chorou muito, vendo-me entristecida e muito descontente... É possível!!"},
    {"type": "paragraph", "text": "Contou-me ainda o que havia sofrido no refeitório comigo (eu era sua primeira de serviço então) não podendo contar-me suas pequenas coisas como antes, porque não tinha permissão, e por outras razões..."},
    {"type": "paragraph", "text": "De modo que vistes que chegastes a não me conhecer mais, acrescentou ela."},
    {"type": "paragraph", "text": "Falou-me da violência que se fazia para tirar as teias de aranha do buraco escuro de Sta. Alexis debaixo da escada (ela tinha horror de aranhas) e mil outros detalhes que me provavam quanto fora fiel em tudo e o que sofreu sem que ninguém suspeitasse."},
    {"type": "heading", "text": "14 de julho"},
    {"type": "paragraph", "text": "Li antigamente que os israelitas construíram os muros de Jerusalém, trabalhando com uma mão e segurando uma espada com a outra. É isso que devemos fazer: não nos entregar inteiramente à obra... etc."},
    {"type": "paragraph", "text": "Se eu tivesse sido rica, teria-me sido impossível ver um pobre com fome sem lhe dar imediatamente dos meus bens. Assim, à medida que ganho algum tesouro espiritual, sentindo que ao mesmo instante almas estão em perigo de se perder e de cair no inferno, dou-lhes tudo o que possuo, e ainda não encontrei um momento para me dizer: Agora vou trabalhar para mim."},
    {"type": "paragraph", "text": "Pôs-se a repetir com ar e acento celestes a estrofe de «Recorda-te» que começa com estas palavras:"},
    {"type": "paragraph", "text": "Recorda-te que tua vontade santa"},
    {"type": "paragraph", "text": "É meu repouso, meu único bem."},
    {"type": "paragraph", "text": "Não é necessário que isso apareça (morrer de amor) contanto que seja!"},
    {"type": "paragraph", "text": "Sempre o que o bom Deus me deu me agradou, a ponto de, se me tivesse dado a escolher, teria escolhido isso, até as coisas que me pareceram menos boas e menos belas que as que os outros tinham."},
    {"type": "paragraph", "text": "Oh! que veneno de louvores vi servir à Madre Priorissa! Como é preciso que uma alma seja desapegada e elevada acima de si mesma para não sentir mal!"},
    {"type": "paragraph", "text": "Na sua visita, o doutor havia redado um pouco de esperança, mas ela não sentiu mais aflição e nos disse:"},
    {"type": "paragraph", "text": "Já estou habituada! Mas que me importa ficar doente muito tempo! É para vos poupar angústias que desejaria que fosse depressa."},
    {"type": "paragraph", "text": "Oh! eu a amo muito, minha pequena Mãe!"},
    {"type": "paragraph", "text": "Meu coração está cheio da vontade do bom Deus, assim, quando se derrama alguma coisa por cima, isso não penetra no interior; é nada que desliza facilmente, como óleo que não pode se misturar com água. Fico sempre no fundo numa paz profunda que nada pode perturbar."},
    {"type": "heading", "text": "Olhando suas mãos emagrecidas:"},
    {"type": "paragraph", "text": "Oh! que alegria sinto ao me ver me destruir!"},
    {"type": "heading", "text": "15 de julho"},
    {"type": "paragraph", "text": "Pode ser que morrereis amanhã,"},
    {"type": "paragraph", "text": "(festa de N. Sra. do Monte Carmelo)"},
    {"type": "paragraph", "text": "depois da comunhão."},
    {"type": "paragraph", "text": "Oh! isso não se pareceria com minha pequena via. Eu sairia dela portanto para morrer? Morrer de amor depois da Comunhão é demasiado para mim; as pequenas almas não poderiam imitar isso."},
    {"type": "paragraph", "text": "Desde que não me aconteça amanhã um acidente de manhã! São negócios desse tipo que podem acontecer a mim: impossível de me dar a Comunhão, o bom Deus obrigado a voltar-se; vedes isso!"},
    {"type": "paragraph", "text": "Falou-me do Beato Théophane Vénard que não pôde receber a Sagrada Comunhão no momento de sua morte, e suspirou profundamente..."},
    {"type": "paragraph", "text": "Tínhamos feito preparativos para sua Comunhão do dia seguinte. O sobrinho da Ir. M. Philomène devia entrar depois de sua primeira Missa no Carmelo para lhe dar a Comunhão; mas vendo-a mais doente, temíamos um cuspo de sangue depois da meia-noite e pedíamos-lhe que rezasse para que nada de desagradável viesse impedir nossos planos. Ela respondeu:"},
    {"type": "paragraph", "text": "Sabeis bem que eu não posso pedir... mas vós pedi por mim... Enfim, esta noite, pedi ao bom Deus mesmo assim para fazer prazer às minhas pequenas irmãs, para que a Comunidade não tivesse decepção, mas no fundo disse-lhe todo o contrário, roguei-lhe que fizesse tudo o que quisesse..."},
    {"type": "heading", "text": "Ao ver-nos enfeitar a enfermaria:"},
    {"type": "paragraph", "text": "Ah! como nos damos ao trabalho de arrumar tudo o que é preciso! Como são boas as festas da terra! Às pequenas primeiras comunicandas, traz-se sua bela roupa branca de manhã, elas só têm de a vestir; todo o trabalho que se tomou por elas lhes é oculto, só têm alegria. Já não é a mesma coisa quando se cresce..."},
    {"type": "paragraph", "text": "Contou-me o seguinte traço cujo recolher lhe ficou como uma graça:"},
    {"type": "paragraph", "text": "Ir. Maria da Eucaristia quis acender os círios para uma procissão; ela não tinha fósforo, mas vendo a pequena lâmpada que arde diante das relíquias, aproximou-se. Ai! encontrou-a a meio apagada, restava só uma débil luz sobre o pavio carbonizado. Conseguiu porém acender seu círio e, por esse círio, todos da Comunidade se acharam acesos. É portanto essa pequena lâmpada a meio apagada que produziu essas belas chamas que, por sua vez, podem acender uma infinidade de outras e mesmo incender o universo. Contudo seria sempre à pequena lâmpada que se devia atribuir a primeira causa desse incêndio. Como as belas chamas poderiam se glorificar, sabendo isso, de ter feito um incêndio tão grande, uma vez que elas não foram acesas senão por correspondência com a pequenina faísca?..."},
    {"type": "paragraph", "text": "É o mesmo para a Comunhão dos Santos. Muitas vezes, sem saber, as graças e as luzes que recebemos são devidas a uma alma oculta, porque o bom Deus quer que os Santos se comuniquem mutuamente a graça pela oração, para que no Céu se amem com grande amor, amor ainda maior que o da família, mesmo a família mais ideal da terra. Quantas vezes pensei que talvez devesse todas as graças que recebi às orações de uma alma que me teria pedido ao bom Deus e que só conheceria no Céu."},
    {"type": "paragraph", "text": "Sim, uma pequeníssima faísca poderá fazer nascer grandes luzes em toda a Igreja, como doutores e mártires que talvez estejam bem acima dela no Céu; mas como se poderia pensar que a glória deles não se tornará também a sua?"},
    {"type": "paragraph", "text": ". . . . . . . . . ."},
    {"type": "paragraph", "text": "No Céu não se encontrará olhares indiferentes, porque todos os eleitos reconhecerão que devem uns aos outros as graças que lhes fizeram merecer a coroa."},
    {"type": "paragraph", "text": "A conversa foi demasiado longa, não pude tomar tudo, nem palavra por palavra."},
    {"type": "heading", "text": "16 de julho"},
    {"type": "paragraph", "text": "Eu temo que para morrer sofras muito…"},
    {"type": "paragraph", "text": "Por que tendes medo de antemão? esperai pelo menos que isso aconteça para ter pena. Vede que me ponho a me atormentar pensando que se surgirem perseguições e massacres, como está predito, talvez vos arranquem os olhos!"},
    {"type": "paragraph", "text": "Eu tinha feito o sacrifício completo de Ir. Geneviève, mas não posso dizer que não a desejasse mais. Muitas vezes no verão, durante a hora do silêncio antes das Matinas, estando sentada na terraza, dizia-me: Ah! se minha Céline estivesse ali perto de mim! Mas não! seria uma felicidade demasiado grande para a terra!"},
    {"type": "paragraph", "text": "... E isso me parecia um sonho irrealizável. Contudo não era por natureza que desejava essa felicidade, era pela sua alma, para que caminhassse por nossa via... E quando a vi entrar aqui, e não só entrar, mas dada a mim completamente para instruí-la de todas as coisas; quando vi que o bom Deus fazia isso, superando assim meus desejos, compreendi quanta imensidade de amor Ele tem por mim..."},
    {"type": "paragraph", "text": "... Pois bem, minha pequena Mãe, se um desejo mal articulado é assim satisfeito, é impossível que todos meus grandes desejos dos quais tanto falo ao bom Deus não sejam completamente atendidos."},
    {"type": "paragraph", "text": "Repete-me com ar convicto esta palavra que tinha lido nas ‘Pequenas Flores’, livro do Abade Bourb."},
    {"type": "paragraph", "text": "Os santos dos últimos tempos superarão tanto os dos primeiros quanto os cedros superam as outras árvores."},
    {"type": "paragraph", "text": "Conheceis todos os recessos de minha pequena alma, só vós..."},
    {"type": "paragraph", "text": "Com ar de criança que tem uma gentil malícia na cabeça:"},
    {"type": "paragraph", "text": "Quisera dar-vos um testemunho de amor que ninguém jamais vos deu..."},
    {"type": "paragraph", "text": "Perguntei-me o que faria... E eis que"},
    {"type": "paragraph", "text": "[Mãe Agnès riscou o resto!]"},
    {"type": "paragraph", "text": "Se o bom Deus me dissesse: Se morreres agora, terás uma grande glória; se morreres aos 80 anos, a glória será bem menos grande, mas isso me dará muito mais prazer. Oh! então não hesitaria em responder: «Meu Deus, quero morrer aos 80 anos, porque não procuro minha glória, mas somente o vosso prazer.»"},
    {"type": "paragraph", "text": "Os grandes santos trabalharam para a glória do bom Deus, mas eu que não sou senão uma pequeníssima alma, trabalho para seu único prazer, e ficaria feliz em suportar os maiores sofrimentos, mesmo que fosse apenas para fazê-lo sorrir ainda que uma só vez."},
    {"type": "heading", "text": "17 de julho"},
    {"type": "paragraph", "text": "Sábado — Às 2 horas da manhã cuspira sangue."},
    {"type": "paragraph", "text": "Sinto que vou entrar no descanso... Mas sinto sobretudo que minha missão vai começar, minha missão de fazer amar o bom Deus como eu O amo, de dar minha pequena via às almas. Se o bom Deus exaucetar meus desejos, meu Céu decorrerá sobre a terra até ao fim do mundo. Sim, quero passar meu Céu fazendo bem na terra. Não é impossível, uma vez que no próprio seio da visão beatífica os Anjos velam por nós."},
    {"type": "paragraph", "text": "Não posso fazer festa de gozar, não posso descansar enquanto houver almas a salvar... Mas quando o Anjo disser: «O tempo não é mais!» então descansarei, poderei gozar, porque o número dos eleitos estará completo e todos terão entrado na alegria e no descanso. Meu coração estremece a esse pensamento…"},
    {"type": "heading", "text": "18 de julho"},
    {"type": "paragraph", "text": "... O bom Deus não me daria esse desejo de fazer bem na terra depois da minha morte, se não quisesse realizá-lo; daria-me antes o desejo de me repousar nele."},
    {"type": "paragraph", "text": "Só tenho incômodos a suportar, não sofrimentos."},
    {"type": "heading", "text": "19 de julho"},
    {"type": "paragraph", "text": "«Vou regar esta noite.» — Era no começo da recreação —"},
    {"type": "paragraph", "text": "... Mas... também teríeis que me regar!"},
    {"type": "paragraph", "text": "Que sois?"},
    {"type": "paragraph", "text": "Sou uma pequena semente, ainda não se sabe o que dela sairá..."},
    {"type": "paragraph", "text": "Tive vontade agora pouco de perguntar a Ir. Maria do S. C. que vinha do locutório ao Pe. Youf, o que ele havia dito de meu estado depois de sua visita. Pensei comigo: Isso talvez me fará bem, me consolará saber; mas, refletindo, disse: Não, é curiosidade, não quero nada para saber; visto que o bom Deus não permite que ela me diga isso por si mesma, é sinal de que não quer que eu saiba. E evitei voltar a conversa sobre esse assunto, com medo de que Ir. Maria do Sacro Coração me o dissesse como um fato; não teria sido feliz..."},
    {"type": "paragraph", "text": "Disse-me que se procurara, ao enxugar o rosto uma vez mais do que necessário, para que Ir. Maria do S. C. notasse que suava muito."},
    {"type": "heading", "text": "20 de julho"},
    {"type": "paragraph", "text": "De manhã, às 3 horas, ela cuspira sangue."},
    {"type": "paragraph", "text": "O que farias se uma de nós estivesse doente em teu lugar? Virias à enfermaria durante as recreações?"},
    {"type": "paragraph", "text": "Eu teria ido diretamente à recreação sem pedir nenhuma notícia, mas teria feito isso bem simplesmente para que ninguém percebesse meu sacrifício. Se eu tivesse ido à enfermaria, teria feito para agradar, nunca para me satisfazer."},
    {"type": "paragraph", "text": "... tudo isso para cumprir meu pequeno dever e para vos atrair graças que a procura de mim mesma não vos teria certamente atraído. E eu mesma teria retirado desses sacrifícios grande força. Se alguma vez, por fraqueza, tivesse feito o contrário do que queria, não me teria desencorajado, teria tentado reparar minhas faltas privando-me ainda mais sem que isso parecesse."},
    {"type": "paragraph", "text": "O bom Deus se faz representar por quem quer, mas isso não tem importância... Convosco haveria um lado humano; prefiro que haja só o divino. Sim, digo-o do fundo do coração, sou feliz de morrer entre os braços de Nossa Mãe, porque ela representa o bom Deus."},
    {"type": "paragraph", "text": "... O pecado mortal não me tiraria a confiança."},
    {"type": "paragraph", "text": "... Não esquecer de contar a história da pecadora sobretudo! Isso é o que provará que eu não me engano."},
    {"type": "paragraph", "text": "Eu lhe dizia que temia para ela as angústias da morte."},
    {"type": "paragraph", "text": "Se entendeis por angústias da morte sofrimentos terríveis que se manifestam no último momento por sinais assustadores para os outros, eu nunca os vi aqui, nas que morreram ante meus olhos. Madre Geneviève os teve para a alma, mas não para o corpo."},
    {"type": "paragraph", "text": "Não sabeis quanto vos amo e vou provar-vos..."},
    {"type": "paragraph", "text": "Perguntam-me mil coisas, isso me faz pensar em Joana d’Arc diante de seu tribunal! Parece-me que respondo com a mesma sinceridade."},
    {"type": "heading", "text": "21 de julho"},
    {"type": "paragraph", "text": "Quando vos vejo, minha pequena Mãe, isso me dá grande felicidade; jamais me cansais ao contrário. Eu dizia há pouco: enquanto tantas vezes sou obrigada a dar, sois vós que me dais..."},
    {"type": "paragraph", "text": "Se o bom Deus me repreender, mesmo um pouquinho, não chorarei de ternura... mas se Ele não me repreender nada, se me receber com um sorriso, chorarei..."},
    {"type": "paragraph", "text": "Oh! gostaria de conhecer no Céu a história de todos os santos; mas não se deverá contá-la para mim, porque seria demasiado longo. Será preciso que, ao encontrar um santo, eu conheça seu nome e toda sua vida num só olhar."},
    {"type": "paragraph", "text": "Nunca agi como Pilatos que recusou ouvir a verdade. Sempre disse ao bom Deus: Ó meu Deus, quero bem ouvir-Vos, imploro-Vos, respondei-me quando humildemente Vos digo: Que é a verdade? Fazei que eu veja as coisas como elas são, que nada me lance pó nos olhos."},
    {"type": "paragraph", "text": "Dizíamos que ela era muito feliz por ser escolhida pelo bom Deus para mostrar às almas a via da confiança. Respondeu:"},
    {"type": "paragraph", "text": "Que importa que seja eu ou outra que dê essa via às almas; contanto que ela seja mostrada, que importe o instrumento!"},
    {"type": "heading", "text": "22 de julho"},
    {"type": "paragraph", "text": "Ir. Maria do Sacro Coração lhe dizia: «Vá! sois cuidada com muito amor...»"},
    {"type": "paragraph", "text": "Sim, vejo bem... É uma imagem do amor que o bom Deus tem por mim. Nunca Lhe dei senão amor, então Ele me dá amor, e isso não acabou, Ele me dará mais ainda em breve..."},
    {"type": "paragraph", "text": "Estou bem tocada, é como um raio ou antes um relâmpago no meio de minhas trevas... mas só como um relâmpago!"},
    {"type": "paragraph", "text": "Repete-me sorrindo esta palavra que o Sr. Youf lhe dissera depois de sua confissão:"},
    {"type": "paragraph", "text": "Se os anjos varressem o Céu, o pó seria feito de diamantes."},
    {"type": "heading", "text": "23 de julho"},
    {"type": "heading", "text": "Falava-se-lhe de associações:"},
    {"type": "paragraph", "text": "Estou tão perto do Céu que tudo aquilo me parece triste."},
    {"type": "paragraph", "text": "Uma de nós lhe tivera dito e lido algo e pensava tê-la muito consolado e alegrado em sua grande prova."},
    {"type": "paragraph", "text": "Não é que tua prova cessou por um momento?"},
    {"type": "paragraph", "text": "Não! É como se cantásseis!"},
    {"type": "paragraph", "text": "Eu dizia sempre essa apreensão que não me deixava de a ver sofrer ainda mais."},
    {"type": "paragraph", "text": "Nós que corremos na via do Amor, acho que não devemos pensar no que poderá nos acontecer de doloroso no futuro, pois então é faltar à confiança e é como nos meter a criar."},
    {"type": "paragraph", "text": "... No momento das provas de papai, tinha um desejo violento de sofrimento... Uma noite que o sabia mais doente, Ir. Maria dos Anjos vendo-me muito triste, consolava-me o melhor que podia; mas eu lhe disse: «Ó minha Ir. Maria dos Anjos, sinto que posso ainda sofrer mais!» Ela olhou-me estupefata e me lembrou isso muitas vezes depois."},
    {"type": "paragraph", "text": "Ir. Maria dos Anjos, de fato, nunca esqueceu essa noite. Nossa pequenina santa ainda postulante estava quase deitar-se, sentada em sua palha com a camisola de noite e seus belos cabelos sobre os ombros. «Seu olhar, disse ela, e toda sua pessoa tinham algo de tão nobre, de tão belo, que me pareceu ver uma virgem do Céu.»"},
    {"type": "paragraph", "text": "Lembro-me que um dia, no auge de nossas provações, encontrei Ir. Maria do S. C. depois de varrer a escada do dormitório (do lado da lingerie). Tínhamos permissão de falar e ela me parou. Então disse-lhe que tinha muita força e que nesse momento pensava naquela palavra da Sra. Swetchine que me penetrava tanto que eu ficava como inflamada: «A resignação é ainda distinta da vontade do bom Deus; há a mesma diferença que entre a união e a unidade. Na união, ainda se é dois, na unidade, já não se é mais que um.»"},
    {"type": "paragraph", "text": "Não sei se é todo textual"},
    {"type": "paragraph", "text": "Obrigram-me a pedir a cura do papai no dia da minha profissão; mas foi-me impossível dizer outra coisa que: Meu Deus, suplico-Vos, que seja tua vontade que papai se cure!"},
    {"type": "paragraph", "text": "... «In te Domine speravi!» No momento de nossas grandes dores, como era feliz dizer esse versículo no Coro!"},
    {"type": "heading", "text": "24 de julho"},
    {"type": "paragraph", "text": "Tinham-lhe enviado belos frutos, mas ela não podia comer. Pegou-os um a um como para oferecê-los a alguém e disse:"},
    {"type": "paragraph", "text": "A Sagrada Família foi bem servida. São José e o Menino Jesus tiveram cada um um pêssego e duas ameixas."},
    {"type": "heading", "text": "Em voz baixa, interrogando-me:"},
    {"type": "paragraph", "text": "Talvez não seja bem, mas os toquei com satisfação? Dá-me grande prazer tocar os frutos, sobretudo os pêssegos, e vê-los de perto."},
    {"type": "heading", "text": "Eu a tranquilizei e ela continuou:"},
    {"type": "paragraph", "text": "A Santíssima Virgem teve sua parte também. Quando me dão leite com rum, eu o ofereço a São José; digo-me: Oh! quanto isso fará bem ao pobre São José!"},
    {"type": "paragraph", "text": "No refeitório, via sempre a quem era preciso dar. O doce era para o Menino Jesus, o forte para São José, a Santíssima Virgem também não era esquecida. Mas quando me faltava alguma coisa, por exemplo quando esqueciam de me passar molho, salada, ficava muito mais contente porque me parecia dar de verdade à Sagrada Família, estando realmente privada do que oferecia."},
    {"type": "paragraph", "text": "... Quando o bom Deus quer que se seja privado de algo, não há remédio, há que passar por isso. Às vezes, Ir. Maria do Sacro Coração punha meu prato de salada tão perto de Ir. Maria da Encarnação que eu já não podia considerá-lo meu, e eu não tocava."},
    {"type": "paragraph", "text": "Ah! minha pequena Mãe, e que «sapatão» de omelete me serviram na vida! Achavam que eu a gostava assim toda ressecada. Haverá que tomar muito cuidado depois de minha morte para não dar essa porcaria às pobres irmãs."},
    {"type": "heading", "text": "25 de julho"},
    {"type": "paragraph", "text": "Eu lhe dizia que acabava por desejar sua morte para não a ver tanto sofrer."},
    {"type": "paragraph", "text": "... Sim, mas não se deve dizer isso, minha pequena Mãe, porque sofrer é justamente o que me agrada na vida."},
    {"type": "paragraph", "text": "Será totalmente a estação dos pêssegos? Gritam-se as ameixas na rua? Não sei mais o que passa."},
    {"type": "paragraph", "text": "«Quando se chega ao declínio,"},
    {"type": "paragraph", "text": "«Perde-se a memória e a cabeça.»"},
    {"type": "paragraph", "text": "Meu Tio lhe tinha enviado uvas. Ela comeu um pouco e disse:"},
    {"type": "paragraph", "text": "Que boas são essas uvas! Mas não gosto do que vem da minha família... Antigamente, quando me traziam de sua parte buquês para meu menino Jesus, nunca queria aceitá-los sem estar bem certa de que Nossa Mãe o havia dito."},
    {"type": "paragraph", "text": "A seu pedido, fazia-lhe beijar seu Crucifixo e o apresentava como se faz de costume."},
    {"type": "paragraph", "text": "... Ah! mas eu beijo o rosto!"},
    {"type": "paragraph", "text": "Olhando depois a imagem do Menino Jesus (que Ir. M. da Trindade trouxe do Carmelo de Messina)."},
    {"type": "paragraph", "text": "Esse Menino Jesus parece dizer-me: «Virás ao Céu, sou eu quem te o digo!»"},
    {"type": "paragraph", "text": "Onde está o Ladrão agora? Não se fala mais nele. Ela respondeu pousando a mão sobre o coração:"},
    {"type": "paragraph", "text": "Ele está aqui! Está no meu coração."},
    {"type": "paragraph", "text": "Eu lhe dizia que a morte era bem triste em aparência e que eu teria tanta pena de vê-la morta. Respondeu-me com voz comovida:"},
    {"type": "paragraph", "text": "A Santíssima Virgem sustentou tão bem seu Jesus morto em seu colo, desfigurado, sangrento! Era outra coisa que aquilo que vereis! Ah! não sei como ela fez!... Suponho que me tragam a vós nesse estado, que faríeis? Responde mihi?..."},
    {"type": "paragraph", "text": "Depois de me ter confiado várias pequenas coisas de que se repreendia, pediu-me se havia ofendido ao bom Deus. Respondi simplesmente que todos esses pequenos pecados não eram tal e que me havia feito bem em contá-los; então ela pareceu muito tocada e disse-me pouco depois:"},
    {"type": "paragraph", "text": "Ao ouvir-vos lembrei-me do Padre Alexis: vossas palavras penetraram já antes no meu coração."},
    {"type": "paragraph", "text": "E pôs-se a chorar; recolhi suas lágrimas enxugando-as com um pano fino. (Ir. Geneviève guarda essa relíquia)"},
    {"type": "paragraph", "text": "Ir. Geneviève lhe apresentou uma pequena flor de gerânio que estava há muito tempo sobre a mesa, para que a atirasse às suas imagens pregadas no cortinado da cama:"},
    {"type": "paragraph", "text": "... Jamais atirar pequenas flores murchas... só pequenas flores «frescas e desabrochadas»."},
    {"type": "paragraph", "text": "Propuseram-lhe uma distração mas demasiado barulhenta. Respondeu sorrindo:"},
    {"type": "paragraph", "text": "... Nada de jogos de meninos!... Nem jogos de meninas; só jogos de pequenos anjos."},
    {"type": "paragraph", "text": "... Olho as uvas e digo: Isso é bonito, parece bom. Depois como um bago; esse não dou ao Menino Jesus, é ele quem me o dá."},
    {"type": "paragraph", "text": "Sou como uma verdadeira criancinha durante minha doença; não penso nada; contento-me de ir ao Céu, só isso!"},
    {"type": "paragraph", "text": "... A primeira vez que me deram uvas na enfermaria disse ao Menino Jesus: Que bom é o cacho! Não entendo que espereis tanto para me tomar, visto que sou um pequeno cacho de uvas e dizem que estou tão madura!"},
    {"type": "heading", "text": "A propósito das direções espirituais:"},
    {"type": "paragraph", "text": "... Acho que se deve tomar muito cuidado para não se procurar, pois se teria o coração ferido depois e se poderia dizer com verdade: «Os guardas tiraram-me o manto, feriram-me... foi só depois de os ter ultrapassado um pouco que achei meu Bem-Amado.»"},
    {"type": "paragraph", "text": "Creio que, se a alma humildemente perguntasse aos guardas onde estava seu Bem-Amado, eles ter-lhe-iam indicado onde se encontrava, mas por querer ser admirada, caiu na inquietude, perdeu a simplicidade do coração."},
    {"type": "paragraph", "text": "... Vós, sois minha luz."},
    {"type": "paragraph", "text": "Escutai uma pequena história bem risível: Um dia, depois da minha veste, Ir. Sta. Vincent de Paul viu-me na Nossa Mãe e exclamou: «Oh! que figura de prosperidade! Está forte essa grande rapariga! está gorda!» Eu ia embora toda humilhada pelo elogio quando Ir. Madeleine me pára diante da cozinha e diz: «Mas que vos sucede, minha pobre pequena Ir. Teresa do Menino Jesus! Estais emagrecendo a olhos vistos! Se continuardes assim, com esse ar que assusta, não seguireis a regra muito tempo!» Não me cansava de ouvir, uma depois da outra, apreciações tão opostas. Desde esse momento não liguei mais à opinião das criaturas e essa impressão desenvolveu-se tanto em mim que agora as censuras, os elogios, tudo desliza sobre mim sem deixar o menor vestígio."},
    {"type": "heading", "text": "26 de julho"},
    {"type": "paragraph", "text": "Sonhei esta noite que estava num bazar com papai, e lá via bonitos novelos brancos que me tentavam para pôr minhas agulhas; mas ao fim disse que faziam as mesmas no Carmelo e pedi uma pequena música."},
    {"type": "paragraph", "text": "Ela disse-me que por volta de 8 de dez. 1892 cuidara de Ir. Marthe; que em 1893 ajudara Madre Maria de Gonzaga no noviciado e que na última eleição em 1896 se vira, por assim dizer, completamente encarregada das novícias."},
    {"type": "paragraph", "text": "... A virtude brilha naturalmente, logo que não está, vejo-o."},
    {"type": "heading", "text": "27 de julho"},
    {"type": "paragraph", "text": "Não queria que eu esquecesse as gotas de um medicamento que me fora prescrito."},
    {"type": "paragraph", "text": "... Oh! devem-vos fortificar; 30 gotas esta noite, não esqueçais!"},
    {"type": "paragraph", "text": "Cansamo-vos?"},
    {"type": "paragraph", "text": "Não, porque sois do mundo muito gentil."},
    {"type": "paragraph", "text": "Contou-nos rindo que sonhara que a levavam ao aquecimento entre dois candelabros para a festa de Nosso Padre."},
    {"type": "paragraph", "text": "A comunidade estava na lavagem."},
    {"type": "paragraph", "text": "... Por volta da uma disse-me: estão bem cansadas com a lavagem! E roguei o bom Deus que aliviasse todas vós, para que o trabalho se fizesse na paz, na caridade. Quando me vi tão doente, senti alegria de ter de sofrer como vós."},
    {"type": "paragraph", "text": "À noite lembrou-me a palavra de São João da Cruz:"},
    {"type": "paragraph", "text": "«Rompereis a tela desse doce encontro.» Sempre apliquei essa palavra à morte de amor que desejo. O amor não gastará a tela de minha vida, rompe-a de repente."},
    {"type": "paragraph", "text": "Com que desejo e consolação me repeti desde o início da minha vida religiosa estas outras palavras de Nosso Pai São João da Cruz: «É da mais alta importância que a alma se exercite muito no Amor para que, consumindo-se rapidamente, quase não pare aqui abaixo mas chegue prontamente a ver seu Deus face a face.»"},
    {"type": "paragraph", "text": "Ao repetir estas últimas palavras levantou o dedo e tomou ar celeste."},
    {"type": "paragraph", "text": "A propósito das dificuldades que previa para a publicação de sua vida."},
    {"type": "paragraph", "text": "... Pois bem, digo como Joana d'Arc: «...E a vontade de Deus se realizará apesar da inveja dos homens.»"},
    {"type": "paragraph", "text": "Não verei mais vossa pequena figura amada! Não verei mais senão vossa pequena alma."},
    {"type": "paragraph", "text": "Ela é bem mais bela!"},
    {"type": "paragraph", "text": "Quando se pensa que vamos vos perder!"},
    {"type": "paragraph", "text": "— Mas não me perdereis... ponto finos!..."},
    {"type": "heading", "text": "A Ir. Geneviève que chorava:"},
    {"type": "paragraph", "text": "Vê-se bem que é isso que lhe pende ao fim do nariz (a morte) a ela agora pega de medo!"},
    {"type": "paragraph", "text": "Depois de oferecer um cacho de uvas ao Menino Jesus:"},
    {"type": "paragraph", "text": "Ofereci-lhe esse cacho para lhe dar vontade de me tomar, pois creio ser dessa espécie..."},
    {"type": "paragraph", "text": "A pele não estava dura e estava muito dourada — Provando um bago:"},
    {"type": "paragraph", "text": "Sim, sou dessa espécie..."},
    {"type": "paragraph", "text": "A pequena Mãe é meu telefone; só tenho que pôr minha orelhinha quando vem, e sei tudo!"},
    {"type": "paragraph", "text": "... Não sou egoísta, é o bom Deus que amo, não sou eu."},
    {"type": "paragraph", "text": "... Para a natureza, prefiro morrer, mas não me alegro da morte senão porque é a vontade do bom Deus para mim."},
    {"type": "paragraph", "text": "Nunca pedi ao bom Deus morrer jovem, estou portanto certa de que agora Ele não realiza senão sua vontade."},
    {"type": "paragraph", "text": "Ela sufocava e eu lhe manifestei minha compaixão e minha tristeza."},
    {"type": "paragraph", "text": "Não tenhais pena, vá! Se sufoco, o bom Deus me dará forças. Amo-O! Ele não me abandonará jamais."},
    {"type": "paragraph", "text": "Contou-me como tivera muito tempo sua pequena cruz de ferro e que adoecera por isso. Disse-me que não era vontade do bom Deus sobre ela nem sobre nós que nos lançássemos a grandes mortificações, que isso lhe dera prova."},
    {"type": "heading", "text": "A propósito das fricções que o médico ordenara:"},
    {"type": "paragraph", "text": "Ah! ser «esfregada» como fui, é muito pior que qualquer coisa!"},
    {"type": "paragraph", "text": "... A partir de 9 de junho, estive certa de morrer em breve."},
    {"type": "heading", "text": "29 de julho"},
    {"type": "paragraph", "text": "... Gostaria de ir-me embora!"},
    {"type": "paragraph", "text": "— Para onde?"},
    {"type": "paragraph", "text": "«Lá em cima, no Céu azul!»"},
    {"type": "paragraph", "text": "Uma irmã lhe havia trazido esta reflexão feita em recreação: «Por que se fala de minha Ir. Teresa do Menino Jesus como de uma santa?! Praticou a virtude, é verdade, mas não foi uma virtude adquirida por humilhações e sobretudo por sofrimentos.» Depois disse-me:"},
    {"type": "paragraph", "text": "... E eu que tanto sofri desde a mais tenra infância! Ah! quanto me alegra ver a opinião das criaturas no momento da morte!"},
    {"type": "paragraph", "text": "Tinham acreditado agradá-la ao lhe trazer um objeto e sucedeu o contrário. Manifestou desagrado, adivinhando que tinham privado alguém do objeto em questão, mas arrependeu-se logo e pediu perdão com lágrimas."},
    {"type": "paragraph", "text": "Oh! peço-vos perdão, agi por natureza, rogai por mim!"},
    {"type": "heading", "text": "E um pouco mais tarde:"},
    {"type": "paragraph", "text": "Oh! quão feliz me vejo imperfeita e de tanto precisar da misericórdia do bom Deus no momento da morte!"},
    {"type": "paragraph", "text": "Ela havia cuspido sangue de manhã e às 3 horas da tarde."},
    {"type": "paragraph", "text": "Expressávamos o receio de que morresse na noite."},
    {"type": "paragraph", "text": "Não morrerei à noite, crede; tive o desejo de não morrer à noite."},
    {"type": "paragraph", "text": "... Dois dias depois da entrada da Ir. M. da Trindade trataram-me a garganta... O bom Deus permitiu que as novícias me esgotassem. Ir. M. da Eucaristia disse-me que isso me acontecia como aos pregadores."},
    {"type": "paragraph", "text": "... Para ser minha historiadora, há que vos poupar."},
    {"type": "paragraph", "text": "Bem! «bebê» vai pois morrer! Há 3 dias, é certo que sofro muito; esta noite estou como no purgatório."},
    {"type": "paragraph", "text": "Muitas vezes, quando posso, repito minha oferta ao Amor."},
    {"type": "paragraph", "text": "Contei-lhe um transtorno."},
    {"type": "paragraph", "text": "... fostes vós que semeastes em minha pequena alma a semente da confiança, não vos lembrais disso?"},
    {"type": "paragraph", "text": "Sustentava-a enquanto ajeitavam seus travesseiros."},
    {"type": "paragraph", "text": "Apoio minha cabeça no coração de minha pequena Mãe."},
    {"type": "paragraph", "text": "Não pedira um alívio, pensava-se que era por virtude, mas não tivera à ideia mortificar-se nisso. Como admirávamos seu ato:"},
    {"type": "paragraph", "text": "Estou cansada da terra! Fazem elogios quando não se merece e reprovações quando não se merecem também. Tudo isso!... tudo isso!..."},
    {"type": "paragraph", "text": "O que faz nossa humilhação no momento faz depois nossa glória mesmo já nesta vida."},
    {"type": "paragraph", "text": "Não tenho capacidade para gozar, sempre fui assim; mas tenho grande capacidade para sofrer. Antigamente, quando tinha muito desgosto, sentia apetite no refeitório, mas quando tinha alegria, era o contrário; impossível de comer."},
    {"type": "heading", "text": "30 de julho"},
    {"type": "paragraph", "text": "... Sempre meu corpo me incomodou, não me encontrei à vontade nele... muito pequena mesmo, envergonhava-me."},
    {"type": "paragraph", "text": "Por ter-vos retribuído um pequeno serviço"},
    {"type": "paragraph", "text": "Obrigada, mamãe!"},
    {"type": "paragraph", "text": "Não teria querido apanhar um alfinete para evitar o purgatório. Tudo o que fiz foi para agradar ao bom Deus, para Lhe salvar almas."},
    {"type": "paragraph", "text": "Olhando a fotografia dos Pe. Bellière e Roulland:"},
    {"type": "paragraph", "text": "Sou mais gentil do que eles!"},
    {"type": "paragraph", "text": "Prometeram-lhe comprar-lhe pequenos chineses."},
    {"type": "paragraph", "text": "Não são chineses que quero, são negros!"},
    {"type": "paragraph", "text": "A amargura me invade quando não me olhais."},
    {"type": "paragraph", "text": "As moscas a atormentaram muito, mas ela não quis matá-las."},
    {"type": "paragraph", "text": "Perdoo-as sempre. Elas, contudo, foram as únicas que me fizeram miséria durante minha doença. Só as tenho por inimigas e como o bom Deus recomendou perdoar aos inimigos, fico contente de encontrar essa pequena ocasião de o fazer."},
    {"type": "paragraph", "text": "É bem duro tanto padecer, isso deve vos impedir todo pensamento?"},
    {"type": "paragraph", "text": "Não, isso ainda me deixa dizer ao bom Deus que O amo, acho que isso é suficiente."},
    {"type": "paragraph", "text": "Mostrando um copo que continha um remédio muito amargo sob o aspecto de uma deliciosa licores de groselhas."},
    {"type": "paragraph", "text": "Esse pequeno copo é a imagem de minha vida. Ontem Ir. Teresa de Santo Agostinho me disse: «Espero que bebas boa licores!» Eu lhe respondi: «Ó minha Ir. Teresa de Sto. Ag., é justamente isso que bebo de pior!»"},
    {"type": "paragraph", "text": "Bem pois minha pequena Mãe, eis o que apareceu aos olhos das criaturas. Sempre lhes pareceu que eu bebia licores exquisitos e era amargura. Digo amargura, mas não! porque minha vida não foi amarga, porque soube fazer minha alegria e minha doçura de toda amargura."},
    {"type": "paragraph", "text": "Se quiserdes dar um lembrança minha ao Sr. de Cornière, fazei-lhe uma imagem com estas palavras: «O que fizestes ao menor dos meus, é a mim que o fizestes.»"},
    {"type": "paragraph", "text": "Deram-lhe um biombo vindo do Carmelo de Saigon; servia-se dele para espantar as moscas. Como fazia muito calor, virou-se para as imagens pregadas no cortinado da cama e pôs-se a abaná-las, e nós depois, com o biombo."},
    {"type": "paragraph", "text": "Abano os santos no lugar de mim; abanovos para vos fazer bem e porque sois também santas."},
    {"type": "paragraph", "text": "O Sr. de Cornière dissera para lhe darem 5 ou 6 colheres de água de Tisserand. Pediu a Ir. Geneviève que não lhe dessem senão 5, depois voltando-se para mim:"},
    {"type": "paragraph", "text": "Sempre o menos, não é, mamãe?"},
    {"type": "paragraph", "text": "Não digais ao Sr. Ducellier que não me resta senão alguns dias; ainda não estou fraca a ponto de morrer, e depois disso quando se vive fica-se bem «capot»."},
    {"type": "paragraph", "text": "— 4 horas — Ela sorria-me depois da partida de uma irmã. Eu lhe disse: Descanse agora, feche os olhos..."},
    {"type": "paragraph", "text": "... Não, gosto tanto de olhar-vos!"},
    {"type": "paragraph", "text": "Queria apanhar uma mosca que a importunava."},
    {"type": "paragraph", "text": "O que vais fazer com ela?"},
    {"type": "paragraph", "text": "Vou matá-la."},
    {"type": "paragraph", "text": "Oh! não, peço-vos."},
    {"type": "paragraph", "text": "Quereis preparar-me para a Extrema-Unção."},
    {"type": "heading", "text": "Com um sorriso, olhando-me:"},
    {"type": "paragraph", "text": "Não penso em nada!"},
    {"type": "paragraph", "text": "Rogai o bom Deus para que eu a receba o melhor que se pode receber."},
    {"type": "paragraph", "text": "Contou-me o que Nosso Padre lhe dissera antes da cerimônia:"},
    {"type": "paragraph", "text": "... «Ireis ser como uma pequena criança que acaba de receber o batismo.» Depois, não me falou senão de amor. Oh! como fiquei tocada!"},
    {"type": "paragraph", "text": "Mostrava-nos suas mãos com respeito depois da Extrema-Unção."},
    {"type": "paragraph", "text": "Eu costumava recolher as pequenas pelezinhas de seus lábios resecos; mas nesse dia ela me disse:"},
    {"type": "paragraph", "text": "Engulo hoje minhas pequenas pelezinhas porque recebi a Extrema-Unção e o santo Viático."},
    {"type": "paragraph", "text": "Era à tarde. Mal fizera uma curta ação de graças várias irmãs vieram falar com ela. Disse-me à noite:"},
    {"type": "paragraph", "text": "Como vieram me perturbar depois da Comunhão! Olharam-me de baixo a cima... mas para não me irritar pensei em Nosso Senhor que se retirava na solidão sem poder impedir o povo de o seguir. E Ele não os mandava embora. Quis imitá-lO recebendo bem as irmãs."},
    {"type": "heading", "text": "31 de julho"},
    {"type": "paragraph", "text": "Supunha-se ainda um dia de festa para sua morte, como 6 de agosto, a Transfiguração, ou 15 a Assunção."},
    {"type": "paragraph", "text": "Não falai de uma data, será sempre uma festa!"},
    {"type": "paragraph", "text": "Depois de nos contar a fábula de La Fontaine"},
    {"type": "paragraph", "text": "(1)"},
    {"type": "heading", "text": ":"},
    {"type": "paragraph", "text": "«O moleiro e seus três filhos.»"},
    {"type": "paragraph", "text": "... Tenho duas botas, mas não tenho saco de pão! Isso quer dizer que não estou perto de morrer."},
    {"type": "paragraph", "text": "(1)"},
    {"type": "paragraph", "text": "É a história do «Gato de Botas» não uma fábula de La Fontaine."},
    {"type": "paragraph", "text": "Tinham descido sua palhinha para a expor depois de sua morte. Ela a avistou quando abriram a porta que dá na cela junto da enfermaria e exclamou com alegria:"},
    {"type": "paragraph", "text": "Ah! Lá está nossa palha! Ela estará toda pronta para colocar meu cadáver."},
    {"type": "paragraph", "text": "... Meu pequenino nariz teve sempre sorte!"},
    {"type": "paragraph", "text": "Como fará bebê para morrer? Mas, de que morrerei?"},
    {"type": "paragraph", "text": "... Sim, vou voar... Haverá muitas coisas do Céu que vos trarei... Serei uma pequena ladra, tomarei tudo o que me agradar..."},
    {"type": "paragraph", "text": "Olhando a estátua da Santíssima Virgem e indicando com o dedo seu pratinho:"},
    {"type": "paragraph", "text": "Quando aconteceu esta noite (um grande cuspo de sangue) eu pensei que ireis levar-me!"},
    {"type": "heading", "text": "Adormecemos vigiando-a:"},
    {"type": "paragraph", "text": "... Pedro, Tiago e João!"},
    {"type": "paragraph", "text": "... Digo-vos que ainda tenho para muito tempo se a Santíssima Virgem não lhes meter a mão!"},
    {"type": "heading", "text": "Amavelmente:"},
    {"type": "paragraph", "text": "... Não nos entre-guinhemos, basta-nos entrepiar-nos!"},
    {"type": "paragraph", "text": "O Ladrão virá"},
    {"type": "paragraph", "text": "E me levará"},
    {"type": "paragraph", "text": "Aleluia!"},
    {"type": "paragraph", "text": "Discutia-se sobre os poucos dias que lhe restavam de vida."},
    {"type": "paragraph", "text": "Ainda é a doente que melhor sabe! e sinto que ainda me resta muito tempo."},
    {"type": "paragraph", "text": "Pensei que devia ficar bem formosa e esperar o Ladrão bem gentilmente."},
    {"type": "paragraph", "text": "Encontrei a felicidade e a alegria na terra, mas unicamente no sofrimento, pois sofri muito aqui em baixo; será preciso fazê-lo saber às almas..."},
    {"type": "paragraph", "text": "Desde minha primeira Comunhão, desde que pedi a Jesus trocar por mim em amargura todas as consolações da terra, tive desejo perpétuo de sofrer. Não pensava porém em fazer disso minha alegria; é uma graça que só me foi concedida mais tarde. Até então era como uma faísca oculta sob a cinza, e como as flores de uma árvore que devem tornar-se frutos no seu tempo. Mas vendo sempre cair minhas flores, quer dizer me deixando levar às lágrimas quando sofria, dizia-me com espanto e tristeza: mas não será portanto senão desejos!"},
    {"type": "paragraph", "text": "Esta noite, quando me dissestes que o Sr. de Cornière achava que eu tinha ainda um mês e mais, não sabia como reagir; era uma diferença tão grande com ontem onde dizia que devia adminsitrar-me no mesmo dia! Mas isso deixou-me numa calma profunda. Que me importa ficar ainda muito tempo na terra! Se sofrer muito e sempre mais, não tenho medo, o bom Deus me dará forças, não me abandonará."},
    {"type": "paragraph", "text": "Se viverdes ainda muito tempo, ninguém compreenderá nada."},
    {"type": "paragraph", "text": "Que importa! Todo mundo pode bem desprezar-me, é sempre o que desejei; terei isso no fim de minha vida!"},
    {"type": "paragraph", "text": "... Agora que o bom Deus fez o que quis fazer, que enganou a todos... Virá como um ladrão à hora em que não se pensará mais; essa é minha pequena ideia."},
  ]),
  makeChapter(6, "agosto-de-1897", "Agosto de 1897", "A noite da fé e a oferta", [
    {"type": "paragraph", "text": "chapter-6."},
    {"type": "paragraph", "text": "1"},
    {"type": "paragraph", "text": "er"},
    {"type": "paragraph", "text": "août 1897"},
    {"type": "paragraph", "text": "A propósito da grande graça que ela havia recebido outrora quando seu livro de missa se fechara sobre a imagem de Nosso Senhor na Cruz, deixando sobressair apenas uma mão. Ela repetiu-me o que se dissera então:"},
    {"type": "paragraph", "text": "Oh! não quero deixar perder esse sangue precioso. Passarei a vida a recolhê-lo para as almas."},
    {"type": "paragraph", "text": "Durante Matinas, a propósito do manuscrito de sua vida:"},
    {"type": "paragraph", "text": "Depois da minha morte, não se deve falar a ninguém do meu manuscrito antes que seja publicado; não se deve falar dele senão à Nossa Madre. Se fizerem de outro modo, o demônio lhes armará mais de uma cilada para estragar a obra do bom Deus... uma obra bem importante!"},
    {"type": "paragraph", "text": "Agora não escrevo mais!"},
    {"type": "paragraph", "text": "Oh! como estou doente!... Porque sabe... convosco!"},
    {"type": "paragraph", "text": "Porque ela já não podia mais falar comigo."},
    {"type": "paragraph", "text": "... Estou bem abandonada, esperarei enquanto Ele quiser."},
    {"type": "paragraph", "text": "... Como o bom Deus fez bem ao dizer: «Il y a plusieurs demeures dans la Maison de mon Père.»"},
    {"type": "paragraph", "text": "A propósito de um padre muito mortificado que se privava até de aliviar coceiras insuportáveis"},
    {"type": "paragraph", "text": ")"},
    {"type": "paragraph", "text": "... Eu prefiro praticar a mortificação de outro modo e não em coisas tão irritantes; eu não teria podido me conter assim."},
    {"type": "paragraph", "text": "Havia havido um aborrecimento a propósito do gelo e eu tinha chorado. Eu lhe perguntei se eu tivera torto, ela me respondeu para me consolAR:"},
    {"type": "paragraph", "text": "Você é sempre graciosa!"},
    {"type": "paragraph", "text": "Pensa em seus irmãos missionários?"},
    {"type": "paragraph", "text": "Pensava neles muitas vezes; mas desde que estou doente não penso em muita coisa."},
    {"type": "paragraph", "text": "Um desses missionários lhe prometera uma missa por ela no dia de Natal de 1896. Ela me contou sua decepção ao saber que ele não pudera dizê-la nesse dia."},
    {"type": "paragraph", "text": "... Eu, que me unira tanto feliz naquele instante! Ah! tudo é incerto sobre a terra!"},
    {"type": "paragraph", "text": "2 août"},
    {"type": "paragraph", "text": "Tenho muita vontade de mandar guardar seu coração como o da Madre Geneviève."},
    {"type": "paragraph", "text": "Faça como quiser!"},
    {"type": "paragraph", "text": "Eu tinha mudado de opinião porque a coisa me repugnava demais e eu lhe disse. Ela pareceu antes triste. Eu adivinhei seu pensamento: Privar-nos-íamos de uma consolação que ela não nos daria por milagre, sabendo bem que ela não seria conservada. Enfim ela me disse:"},
    {"type": "paragraph", "text": "Você tergiversa demais, minha pequena madre, notei isso muitas vezes na minha vida..."},
    {"type": "paragraph", "text": "Tinha-se falado entre nós intimamente do pouco caso que muitas vezes se faz da virtude oculta."},
    {"type": "paragraph", "text": "... Isso me atingiu na Vida de N. P. S"},
    {"type": "paragraph", "text": "t"},
    {"type": "paragraph", "text": "João da Cruz, de quem se dizia: «O irmão João da Cruz! mas é um religioso menos que ordinário!»"},
    {"type": "paragraph", "text": "Não tenho grandes desejos do Céu; ficarei bem contente de ir, só isso!"},
    {"type": "paragraph", "text": "Não se poderá dizer de mim: «Ela morre por não morrer.» Já vos disse: para a minha natureza, sim, o Céu! mas a graça na minha alma tomou grande domínio sobre a natureza, e agora não posso senão repetir ao bom Deus:"},
    {"type": "paragraph", "text": "Ainda muito tempo quero viver,"},
    {"type": "paragraph", "text": "Senhor, se for teu desejo."},
    {"type": "paragraph", "text": "No Céu, gostaria de te seguir,"},
    {"type": "paragraph", "text": "Se isso te desse prazer."},
    {"type": "paragraph", "text": "O Amor, esse fogo da Pátria,"},
    {"type": "paragraph", "text": "Não cessa de me consumir"},
    {"type": "paragraph", "text": "Que me faça a morte ou a vida?"},
    {"type": "paragraph", "text": "Minha única felicidade é amar-te."},
    {"type": "heading", "text": "À Irmã Geneviève:"},
    {"type": "paragraph", "text": "Tudo passa neste mundo mortal, até “bebê” mas ele voltará..."},
    {"type": "paragraph", "text": "Irmã Geneviève beijava os pés do Crucifixo."},
    {"type": "paragraph", "text": "Vocês não seguem a doutrina de “bebê”! Beije-o bem depressa nas duas faces e deixem-se beijar."},
    {"type": "paragraph", "text": "Sinto uma alegria muito viva não somente quando me acham imperfeita, mas sobretudo ao me sentir assim. Isso supera todos os elogios que me enfadam."},
    {"type": "paragraph", "text": "3 août"},
    {"type": "paragraph", "text": "Como fez para chegar a essa paz inalterável que é a sua parte?"},
    {"type": "paragraph", "text": "Esqueci-me de mim mesma e procurei não procurar-me em nada."},
    {"type": "paragraph", "text": "Eu lhe dizia que ela devia ter muito lutado para chegar a ser perfeita"},
    {"type": "paragraph", "text": "Oh! isso não é isso!..."},
    {"type": "paragraph", "text": "Ela tivera dificuldade com uma irmã e me disse com ar grave e terno:"},
    {"type": "paragraph", "text": "Digo-lho francamente: preciso vê-la perto de mim nos últimos dias da minha vida."},
    {"type": "paragraph", "text": "Minhas pequeninas irmãs, rezem pelos pobres doentes na morte. Se soubessem o que sucede! Como bastaria pouco para perder a paciência! É preciso ser caridoso com qualquer um... Eu não teria acreditado nisso outrora."},
    {"type": "paragraph", "text": "Falava-lhe da mortificação sob a forma de instrumentos de penitência."},
    {"type": "paragraph", "text": "... É preciso ser muito moderado sobre esse ponto, porque mistura-se ali frequentemente mais a natureza que outra coisa."},
    {"type": "heading", "text": "A nós três:"},
    {"type": "paragraph", "text": "É preciso ter muita atenção à regularidade. Depois de um parlatório, não vos detendeis para falar entre vós, porque então é como em casa, não se priva de nada."},
    {"type": "heading", "text": "Voltando-se para mim:"},
    {"type": "paragraph", "text": "Isso, minha Madre, é o mais útil de tudo."},
    {"type": "paragraph", "text": "Oh! como meu ombrozinho está magoado, se soubesse!"},
    {"type": "paragraph", "text": "Vamos pôr aí algodão."},
    {"type": "paragraph", "text": "Não, não me tirem minha cruzinha."},
    {"type": "paragraph", "text": "Há muito tempo que sofro, mas de sofrimentos pequenos. Desde 28 de julho, são grandes sofrimentos."},
    {"type": "paragraph", "text": "Não se entendia mais nada no andamento de sua doença e uma de nós lhe disse:"},
    {"type": "paragraph", "text": "De que vai morrer?"},
    {"type": "paragraph", "text": "Mas, eu morrerei de morte! O bom Deus não disse a Adão de que ele morreria, por estas palavras: «Vocês morrerão de morte.» É isso simplesmente."},
    {"type": "paragraph", "text": "4 août"},
    {"type": "paragraph", "text": "Tive muitos pesadelos esta noite, e pesadelos bem assustadores, mas no momento pior, você vinha a mim e eu já não tinha medo."},
    {"type": "paragraph", "text": "... Não, não me acho uma grande santa! Acho-me uma santinha; mas penso que o bom Deus se agradou em pôr em mim coisas que fazem bem a mim e aos outros."},
    {"type": "paragraph", "text": "Tinha-se-lhe trazido uma gavinha de espigas, ela destacou a mais bonita e me disse:"},
    {"type": "paragraph", "text": "Minha Madre, esta espiga é a imagem da minha alma: o bom Deus me carregou de graças para mim e para muita gente..."},
    {"type": "paragraph", "text": "Depois, temendo ter tido um pensamento de orgulho:"},
    {"type": "paragraph", "text": "Oh! quanto eu gostaria de ser humilhada e maltratada para ver se tenho verdadeiramente a humildade do coração!... Contudo, quando eu era humilhada outrora, era muito feliz... Sim, parece-me que sou humilde... O bom Deus me mostra a verdade; sinto tão bem que tudo vem dele."},
    {"type": "paragraph", "text": "Como é fácil desanimar quando se está muito doente!..."},
    {"type": "paragraph", "text": "Oh! como sinto que me desanimaria se eu não tivesse fé! ou antes se não amasse o bom Deus."},
    {"type": "paragraph", "text": "Só no Céu veremos a verdade sobre todas as coisas. Na terra, é impossível. Assim, mesmo para a Sagrada Escritura, não é triste ver todas as diferenças de tradução. Se eu tivesse sido padre, teria aprendido o hebraico e o grego, não me teria contentado com o latim, assim teria conhecido o texto verdadeiro ditado pelo Espírito Santo."},
    {"type": "paragraph", "text": "Adormeci um segundo durante a oração. Sonhei que faltavam soldados para uma guerra."},
    {"type": "paragraph", "text": "Você disse: É preciso enviar Irmã Teresa do Menino Jesus. Eu respondi que teria preferido que fosse para uma guerra santa. Enfim, parti assim mesmo."},
    {"type": "paragraph", "text": "Oh! não, eu não teria medo de ir à guerra. Com que felicidade, por exemplo, na época das cruzadas, eu teria partido para combater os hereges. Ora! eu não teria medo de apanhar um tiro!"},
    {"type": "paragraph", "text": "E eu que desejava o martírio, é possível que eu morra numa cama!"},
    {"type": "paragraph", "text": "Como organiza sua vidinha agora?"},
    {"type": "paragraph", "text": "Minha vidinha é sofrer e pronto! Eu não poderia dizer: Meu Deus, é pela Igreja, meu Deus é pela França... etc... O bom Deus sabe bem o que tem de fazer; dei-lhe tudo para lhe agradar. E depois me cansaria muito de lhe dizer: Dá isto a Pedro, dá isto a Paulo. Eu faço-o depressa só quando uma irmã me pede, e depois não penso mais nisso. Quando rezo pelos meus irmãos missionários, não ofereço minhas dores, digo simplesmente: Meu Deus, dai-lhes tudo o que desejo para mim."},
    {"type": "paragraph", "text": "5 août"},
    {"type": "paragraph", "text": "Estava muito quente, e o sacristão nos tinha piedado de usar roupas grossas."},
    {"type": "paragraph", "text": "Ah! no Céu, o bom Deus nos retribuirá por termos usado por amor dele roupas grossas na terra."},
    {"type": "paragraph", "text": "Constatando que ela quase não podia mais mover-se:"},
    {"type": "paragraph", "text": "Davi dizia nos salmos: «Sou como o gafanhoto que muda continuamente de lugar.» Pois bem, eu não posso dizer o mesmo! Gostaria de passear, mas tenho um cordel preso à pata!"},
    {"type": "paragraph", "text": "... Quando os santos tiverem fechado sobre mim a porta do Céu, cantarão:"},
    {"type": "paragraph", "text": "Finalmente te temos,"},
    {"type": "paragraph", "text": "Ratinhozinha cinzenta,"},
    {"type": "paragraph", "text": "Finalmente te temos"},
    {"type": "paragraph", "text": "E te guardaremos!"},
    {"type": "paragraph", "text": "Uma pequena canção que lhe vinha à memória"},
    {"type": "paragraph", "text": ")"},
    {"type": "paragraph", "text": "Irmã Marie do Sagrado Coração disse-lhe que os Anjos viriam à sua morte, para acompanhar Nosso Senhor, que ela os veria resplandecentes de luz e de beleza."},
    {"type": "paragraph", "text": "... Todas essas imagens não me fazem nenhum bem, não posso nutrir-me senão da verdade. É por isso que nunca desejei visões. Não se pode ver na terra o Céu, os anjos como são. Prefiro esperar depois da minha morte."},
    {"type": "paragraph", "text": "Durante Vésperas, minha pequena Madre, eu pensei que você é o meu sol."},
    {"type": "paragraph", "text": "Adormeci, e sonhei que você se inclinava para me beijar; quis retribuir, mas logo acordei, toda surpreendida que meu beijo caíra no vazio!"},
    {"type": "paragraph", "text": "Seu leito ainda não estava colocado no meio da enfermaria, mas ao fundo, no canto. Para festejar o dia seguinte, 6 de Agosto, a Transfiguração de N.S., havíamos tomado a Santa Face do Coro que ela gostava muito e pendurado o quadro rodeado de flores e luzes à sua direita, na parede. Ela me disse olhando a imagem:"},
    {"type": "paragraph", "text": "Que Nosso Senhor fez bem em baixar os olhos para nos dar seu retrato! Pois os olhos são o espelho da alma, se tivéssemos adivinhado sua alma, morreríamos de alegria."},
    {"type": "paragraph", "text": "Oh! que essa Santa Face me fez bem na minha vida! Enquanto compunha meu cântico: «Viver de Amor» ela me ajudou a fazê-lo com grande facilidade. Escrevi de memória, durante meu silêncio da noite os 15 quartetos que tinha composto, sem rascunho, no dia. Nesse dia, ao ir ao refeitório depois do exame, acabara de compor a estrofe:"},
    {"type": "paragraph", "text": "Viver de amor é enxugar tua Face"},
    {"type": "paragraph", "text": "É obter dos pecadores o perdão."},
    {"type": "paragraph", "text": "Repito-a a ela, ao passar, com muito amor. Olhando-a, chorei de amor."},
    {"type": "paragraph", "text": "Repito como Jó: «Pela manhã espero não chegar à noite, e à tarde espero não ver mais a manhã.»"},
    {"type": "paragraph", "text": "... Essas palavras de Isaías: «Quem creu na vossa palavra... Ele é sem formosura, sem beleza... etc.» fizeram todo o fundo da minha devoção à Santa Face, ou, para melhor dizer, o fundo de toda a minha piedade. Eu também desejava ser sem beleza, apenas a que pisa o vinho no lagar, desconhecida de toda criatura..."},
    {"type": "paragraph", "text": "A propósito de uma confidência que eu lhe fazia, ela me disse:"},
    {"type": "paragraph", "text": "Uma madre prioresa deveria sempre deixar crer que não tem nenhum trabalho. Isso faz tanto bem e dá tanta força não dizer suas penas! Por exemplo, é preciso evitar expressar-se assim: Você tem aborrecimentos e dificuldades, eu tenho as mesmas e bem outras, etc."},
    {"type": "paragraph", "text": "6 août"},
    {"type": "paragraph", "text": "Ela tinha esperado morrer durante a noite e me disse desde de manhã:"},
    {"type": "paragraph", "text": "Vigiei a noite toda, como a menininha na canção do sapatinho de Natal..."},
    {"type": "paragraph", "text": "Não cessei de olhar a Santa Face... Afastei muitas tentações... Ah! fiz muitos atos de fé..."},
    {"type": "paragraph", "text": "Posso dizer também: «Olhei à minha direita, e considerei, e não há ninguém que me conheça...» Quero dizer ninguém que conheça o momento da minha morte... A direita me figura o lado onde você está para mim."},
    {"type": "paragraph", "text": "Ela olhou depois a estátua da Santíssima Virgem e cantou docemente:"},
    {"type": "paragraph", "text": "Quando virá, minha terníssima Mãe,"},
    {"type": "paragraph", "text": "Quando virá esse belo dia,"},
    {"type": "paragraph", "text": "Em que, do exílio da terra,"},
    {"type": "paragraph", "text": "Voarei ao eterno Pouso?"},
    {"type": "paragraph", "text": "Sua violenta dor de lado cessara na noite. Sr. de Cornières à auscultaçãola achou tão doente, mas ela duvidava de sua morte próxima."},
    {"type": "paragraph", "text": "Sou como um pobre pequeno Robinson em sua ilha. Enquanto nada me prometeram, eu era exilada, é verdade, mas não pensava em deixar minha ilha. Mas eis que me anunciam seguramente um navio que deve me reconduzir logo à minha Pátria. Então fico na praia, olho ao longe, olho sempre... e, não vendo nada aparecer no horizonte, digo para mim: Eles me enganaram! Não vou embora!"},
    {"type": "paragraph", "text": "Ela me mostrou no pequeno breviário do Sagrado Coração, a palavra de N.S. à B. Marguerite-Marie, que ela tirara, no dia da Ascensão:"},
    {"type": "paragraph", "text": "«A cruz é o leito das minhas esposas, é ali que te farei consumir delícias do meu amor.»"},
    {"type": "paragraph", "text": "E contou-me que um dia, uma irmã tendo tirado no mesmo livro e caindo num trecho severo, lhe pedira tirar também. Ela então tinha caído sobre esta palavra:"},
    {"type": "paragraph", "text": "«Confia em mim...»"},
    {"type": "paragraph", "text": "... Não posso apoiar-me em nada, em nenhuma das minhas obras para ter confiança. Assim teria gostado de poder dizer a mim mesma: Estou quitada de todos os meus ofícios dos mortos. Mas essa pobreza foi para mim uma verdadeira luz, uma verdadeira graça. Pensei que nunca pude na minha vida quitar uma só de minhas dívidas para com o bom Deus, mas que isso era para mim como uma verdadeira riqueza e uma força, se eu quisesse. Então fiz esta oração: Ó meu Deus, eu vos suplico, quite a dívida que contraí para com as almas do Purgatório, mas fazei-o em Deus, para que seja infinitamente melhor do que se eu tivesse rezado meus ofícios dos mortos. E lembrei-me com grande doçura dessas palavras do cântico de S"},
    {"type": "paragraph", "text": "t"},
    {"type": "paragraph", "text": "João da Cruz: «Quita todas as dívidas.» Sempre apliquei isso ao Amor... Sinto que essa graça não pode ser recompensada... Era demasiado doce! Experiencia-se uma paz tão grande de ser absolutamente pobre, de contar apenas com o bom Deus."},
    {"type": "paragraph", "text": "... Oh! que há poucas religiosas perfeitas, que nada fazem qualquer como e mais ou menos, dizendo: Não sou obrigada a isso, afinal... Não há grande mal em falar aqui, me contentar com isso... Quão raras são as que fazem tudo o melhor possível! E são, no entanto, as mais felizes. Assim para o silêncio, que bem faz à alma, que faltas à caridade impede e tantas penas de todo tipo. Falo sobretudo do silêncio, porque é nesse ponto que se falta mais."},
    {"type": "paragraph", "text": "Que eu era orgulhosa quando era semanária no Ofício, que dizia as orações em voz alta no meio do Coro! porque pensava que o padre dizia as mesmas orações na Missa e que eu tinha como ele o direito de rezar em voz alta diante do Santíssimo Sacramento, de dar bênçãos, absolvições, de dizer o Evangelho quando eu era primeira chantre."},
    {"type": "paragraph", "text": "... Mas posso dizer que o Ofício foi ao mesmo tempo minha felicidade e meu martírio, porque eu tinha um desejo tão grande de recitá-lo bem e de não nele cometer faltas; e vi-me algumas vezes, depois de ter previsto um minuto antes o que devia dizer, deixá-lo passar sem abrir a boca por uma distração inteiramente involuntária. Não creio, porém, que se possa desejar mais do que eu recitar perfeitamente o ofício e assistir ao Coro."},
    {"type": "paragraph", "text": "... Perdoo muito as irmãs que esquecem ou se enganam."},
    {"type": "paragraph", "text": "Irmã St Stanislas, sua primeira enfermeira, a havia deixado durante todo o tempo das Vésperas, deixando a porta e a janela da enfermaria abertas; a corrente de ar era muito forte. Nossa Madre, achando-a nessa situação manifestou seu descontentamento e pediu explicações. Ela me disse:"},
    {"type": "paragraph", "text": "Contei a Nossa Madre a verdade, mas ao falar veio-me à cabeça uma expressão mais caridosa daquela que ia empregar e que, contudo, não era má, certamente; segui minha inspiração e o bom Deus me recompensou por isso com uma grande paz interior."},
    {"type": "paragraph", "text": "Pedi-lhe à noite, durante Matinas, o que ela entendia por «ficar pequena criança diante do bom Deus.» Ela me respondeu:"},
    {"type": "paragraph", "text": "É reconhecer seu nada, esperar tudo do bom Deus, como uma criança pequena espera tudo de seu pai; é não se inquietar por nada, não ganhar fortuna. Mesmo entre os pobres, dá-se à criança o que lhe é necessário, mas logo que ela cresce seu pai não quer mais alimentá-la e diz-lhe: Trabalha agora, podes te bastar a ti mesma."},
    {"type": "paragraph", "text": "É para não ouvir isso que eu não quis crescer, sentindo-me incapaz de ganhar minha vida, a vida eterna do Céu. Assim fiquei sempre pequena, não tendo outra ocupação que colher flores, as flores do amor e do sacrifício, e oferecê-las ao bom Deus para seu prazer."},
    {"type": "paragraph", "text": "Ser pequeno é ainda não se atribuir a si próprias as virtudes que se pratica, crendo-se capaz de alguma coisa, mas reconhecer que o bom Deus põe esse tesouro na mão de seu pequeno filho para que ele o sirva quando necessitar; mas é sempre o tesouro do bom Deus. Enfim, é não desanimar de suas faltas, pois as crianças caem muitas vezes, mas são pequenas demais para se ferirem muito."},
    {"type": "paragraph", "text": "7 août"},
    {"type": "paragraph", "text": "Irmã X... que partiu, queria confiar-me seus segredos, embora eu não seja mais prioresa."},
    {"type": "paragraph", "text": "... Nunca a ouça, mesmo quando ela fosse como um anjo; seria muito infeliz porque não faria nisso seu dever; seria uma fraqueza que certamente faria pena ao bom Deus."},
    {"type": "paragraph", "text": "... Oh! como o bom Deus é pouco amado na terra!... até pelos padres e religiosos... Não, o bom Deus não é muito amado..."},
    {"type": "paragraph", "text": "Ela me mostrou a fotografia de N.D. das Vitórias onde colara a pequena florzinha que papai lhe dera nos Buissonnets no dia em que lhe confiara sua vocação; a raiz estava desprendida e o pequeno Jesus parece segurá-la na mão e sorrir-lhe assim como a Santíssima Virgem."},
    {"type": "paragraph", "text": "... Que a pequena flor tenha perdido a raiz, isso dirá que estou no Céu... É por isso que eles me fazem tão gentil... ("},
    {"type": "paragraph", "text": "a Santíssima Virgem e o Menino J."},
    {"type": "paragraph", "text": ")"},
    {"type": "paragraph", "text": "Oh! se eu fosse infiel, se eu cometesse sequer a menor infidelidade, sinto que a pagaria por meio de tormentos espantosos, e eu não poderia mais aceitar a morte. Assim não cesso de dizer ao bom Deus: «Ó meu Deus, eu vos suplico, preservai-me do infortúnio de ser infiel.»"},
    {"type": "paragraph", "text": "De que infidelidade queres falar?"},
    {"type": "paragraph", "text": "De um pensamento de orgulho alimentado voluntariamente. Se eu me dissesse, por exemplo: Adquiri tal virtude, estou certa de poder praticá-la. Pois então seria apoiar-se nas próprias forças, e quando se está aí, arrisca-se cair no abismo. Mas terei o direito sem ofender o bom Deus de fazer pequenas bobagens até minha morte, se eu for humilde, se eu permanecer bem pequena. Veja as criancinhas: não cessam de quebrar, de rasgar, de cair, tudo isto amando muito, muito seus pais. Quando caio assim, isso me faz ver ainda mais meu nada e digo-me: O que eu faria, o que eu me tornaria, se eu me apoiasse nas minhas próprias forças?!..."},
    {"type": "paragraph", "text": "Compreendo muito bem que S"},
    {"type": "paragraph", "text": "t"},
    {"type": "paragraph", "text": "Pedro tenha caído. Esse pobre São Pedro, apoiava-se em si mesmo em lugar de se apoiar unicamente na força do bom Deus. Concluo que, se eu dissesse: «Ó meu Deus, amo-vos tanto, bem sabeis, para me deter a um só pensamento contra a fé»; minhas tentações se tornariam mais violentas e eu sucumbiria certamente."},
    {"type": "paragraph", "text": "Tenho certeza de que se S"},
    {"type": "paragraph", "text": "t"},
    {"type": "paragraph", "text": "Pedro tivesse dito humildemente a Jesus: «Concede-me, peço-te, a força de te seguir até a morte», a teria recebido logo."},
    {"type": "paragraph", "text": "Tenho certeza ainda de que Nosso Senhor não dizia mais aos seus Apóstolos por suas instruções e sua presença sensível do que não nos diz a nós mesmas pelas boas inspirações de sua graça. Ele poderia bem ter dito a S"},
    {"type": "paragraph", "text": "t"},
    {"type": "paragraph", "text": "Pedro: Pede-me a força de cumprir o que queres. Mas não, porque quis mostrar-lhe sua fraqueza, e que, diante de governar toda a Igreja que está cheia de pecadores, lhe era necessário experimentar por si mesmo o que o homem pode sem a ajuda de Deus."},
    {"type": "paragraph", "text": "... Antes da sua queda, Nosso Senhor lhe disse: «Quando voltares a ti, confirma teus irmãos.» Isso queria dizer: Persuade-os por tua própria experiência da fraqueza das forças humanas."},
    {"type": "paragraph", "text": "Gostaria que vocês estivessem sempre comigo, vocês são meu sol."},
    {"type": "paragraph", "text": "8 août"},
    {"type": "paragraph", "text": "Eu lhe dizia que divulgaria suas virtudes mais tarde:"},
    {"type": "paragraph", "text": "É o bom Deus sozinho que se deve valorizar, pois não há nada a valorizar no meu pequeno nada."},
    {"type": "paragraph", "text": "Ela olhava o céu pela janela da enfermaria e Irmã Marie do Sagrado Coração disse-lhe: «Como você olha o céu com amor!» Nesse momento ela estava mais cansada e respondeu só com um sorriso. Mais tarde me confidenciou o que tinha pensado."},
    {"type": "paragraph", "text": "Ah! ela crê que eu olho o firmamento pensando no verdadeiro Céu! Mas não, é simplesmente porque admiro o céu material; o outro me está cada vez mais fechado. Depois logo me disse com grande doçura: Oh! mas sim, é realmente por amor que olho o céu, sim, é por amor ao bom Deus, visto que tudo o que faço, os movimentos, os olhares, tudo, desde minha oferta, é por amor."},
    {"type": "paragraph", "text": "Pensei hoje na minha vida passada, no ato de coragem que fizera outrora no Natal, e o louvor dirigido a Judite voltou-me à memória: «Agiste com coragem viril e teu coração se fortificou.» Muitas almas dizem: Mas eu não tenho força para cumprir tal sacrifício. Pois que façam o que eu fiz: um grande esforço. O bom Deus nunca recusa essa primeira graça que dá a coragem de agir; depois disso o coração se fortalece e vai-se de vitória em vitória."},
    {"type": "paragraph", "text": "Se Nosso Senhor e a Santíssima Virgem não tivessem ido eles mesmos a festas, jamais eu teria compreendido o uso de convidar os amigos para refeições. Parecia-me que para se nutrir se devia esconder ou ao menos ficar em família. Convidar-se, sim, mas apenas para conversar, contar viagens, lembranças, enfim para coisas do espírito."},
    {"type": "paragraph", "text": "Tive grande pena das pessoas que serviam em grandes jantares. Se, por azar, lhes acontecia derramar algumas gotas na toalha ou num dos convivas, via a dona de casa olhá-las severamente, então esses pobres enrubreciam de vergonha, e eu dizia, toda revoltada por dentro: Oh! como essa diferença que existe aqui abaixo entre senhores e servos prova bem que há um céu onde cada um será posto segundo seu merecimento interior, onde todos estarão sentados no banquete do Pai de família. Mas então que Servidor será o nosso, visto que Jesus disse «que viria para nos servir»! Será o momento para os pobres e os pequenos sobretudo, de serem amplamente recompensados de suas humilhações."},
    {"type": "paragraph", "text": "9 août"},
    {"type": "paragraph", "text": "Eu dizia dela: Nosso guerreiro está abatido!"},
    {"type": "paragraph", "text": "Não sou um guerreiro que combateu com armas terrestres, mas com «a espada do espírito que é a palavra de Deus». Assim a doença não pôde me abater, e nem mesmo ontem à noite servi-me da minha espada com uma noviça. Disse: morrerei com as armas na mão."},
    {"type": "heading", "text": "A propósito de seu manuscrito:"},
    {"type": "paragraph", "text": "Haverá para todos os gostos, exceto para os caminhos extraordinários."},
    {"type": "paragraph", "text": "Você voltou para mim a ser aquilo que era na minha infância... Não posso dizer o que você é para mim!"},
    {"type": "heading", "text": "Diziam-lhe que ela era uma santa:"},
    {"type": "paragraph", "text": "Não, não sou uma santa; nunca fiz as ações dos santos. Sou uma almasinha que o bom Deus encheu de graças, isso é o que sou. O que digo é a verdade, verão isso no Céu."},
    {"type": "paragraph", "text": "10 août"},
    {"type": "paragraph", "text": "Ela olhava a imagem de"},
    {"type": "paragraph", "text": "Théophane Vénard"},
    {"type": "paragraph", "text": "presa às cortinas de seu leito. Essa imagem representa o missionário apontando o Céu com o dedo."},
    {"type": "paragraph", "text": "Crê que ele te conhece? Olhe o que ele me mostra... Ele bem poderia não ter essa pose..."},
    {"type": "paragraph", "text": "Dizia-se que as almas chegadas como ela ao amor perfeito viam sua beleza, e que ela era do número."},
    {"type": "paragraph", "text": "Que beleza?... Não vejo minha beleza de modo algum, vejo apenas as graças que recebi do bom Deus. Vocês se enganam sempre, não sabem então que não sou senão um minúsculo núcleo... uma amêndoa pequena..."},
    {"type": "paragraph", "text": "Fui interrompida e não pude tomar a explicação que se seguiu"},
    {"type": "paragraph", "text": ".)"},
    {"type": "paragraph", "text": "Com ar alegre e tão gentil olhando o retrato de Th. Vénard:"},
    {"type": "paragraph", "text": "... Ah! mas!..."},
    {"type": "paragraph", "text": "Por que dizeis: Ah! mas, perguntou Irmã Geneviève."},
    {"type": "paragraph", "text": "É porque cada vez que o olho, ele também me olha, e além disso parece me vigiar de canto de olho com ar meio malicioso."},
    {"type": "paragraph", "text": "Mostraram-lhe uma fotografia de Joana d’Arc em sua prisão."},
    {"type": "paragraph", "text": "Os santos me encorajam também na minha prisão. Dizem-me: Enquanto estás nos ferros, não podes cumprir tua missão; mas mais tarde, depois da tua morte, será o tempo de teus trabalhos e de tuas conquistas."},
    {"type": "paragraph", "text": "Penso nas palavras de S"},
    {"type": "paragraph", "text": "t"},
    {"type": "paragraph", "text": "Inácio de Antioquia. «É preciso, eu também, que pela dor seja moído para tornar-me o trigo de Deus.»"},
    {"type": "heading", "text": "Durante Matinas:"},
    {"type": "paragraph", "text": "Se soubesses o que és para mim! Mas digo-te sempre a mesma coisa."},
    {"type": "paragraph", "text": "Falava-lhe do Céu, de Nosso Senhor, da Santíssima Virgem que lá estão em corpo e alma."},
    {"type": "paragraph", "text": "Ela soltou um suspiro profundo com esta exclamação:"},
    {"type": "paragraph", "text": "Ah!..."},
    {"type": "paragraph", "text": "Diz-me com isso que sofres muito com tua provação?"},
    {"type": "paragraph", "text": "Sim!... Há que amar tanto o bom Deus e a Santíssima Virgem e ter esses pensamentos!... Mas não me detenho neles."},
    {"type": "paragraph", "text": "11 août"},
    {"type": "paragraph", "text": "... Sempre achei, minha pequena Madre, que pões demais ardor no trabalho - (a propósito da lavagem)."},
    {"type": "paragraph", "text": "Eu lhe dizia que depois de sua morte seríamos bem boas e que a Comunidade seria renovada:"},
    {"type": "paragraph", "text": "... «Em verdade, em verdade vos digo: Se o grão de trigo caído na terra não morrer, fica só; mas se morrer, produz muito fruto.»"},
    {"type": "paragraph", "text": "Não esperava sofrer assim; sofro como uma criancinha."},
    {"type": "paragraph", "text": "... Nunca pediria ao bom Deus sofrimentos maiores. Se os aumentar, os suportarei com prazer e alegria, pois virão dele. Mas sou pequena demais para ter a força por mim mesma. Se pedisse sofrimentos, seriam meus sofrimentos, teria de suportá-los sozinha, e nunca pude fazer nada sozinha."},
    {"type": "paragraph", "text": "... A Santíssima Virgem, ela não tem uma Santíssima Virgem a amar, é menos feliz que nós."},
    {"type": "paragraph", "text": "Ela me dissera isso na recreação outrora."},
    {"type": "paragraph", "text": ")"},
    {"type": "paragraph", "text": "Rezo muitas vezes aos santos sem ser atendida, mas quanto mais eles parecem surdos às minhas orações, mais eu os amo."},
    {"type": "paragraph", "text": "Por quê?"},
    {"type": "paragraph", "text": "Porque desejei mais não ver o bom Deus e os santos e ficar na noite da fé do que outros desejam ver e compreender."},
    {"type": "paragraph", "text": "Ela nos contara todo tipo de coisas sobre a época da influenza. Eu lhe disse ao fim: Que fadiga te impuseste! E quão gentil e amável foste! Certamente, toda essa alegria não é sincera, sofres demais de alma e de corpo."},
    {"type": "heading", "text": "Rindo:"},
    {"type": "paragraph", "text": "Nunca «finjo», não sou como a mulher de Jeroboão."},
    {"type": "paragraph", "text": "12 août"},
    {"type": "paragraph", "text": "Fez a Comunhão"},
    {"type": "paragraph", "text": "... «Adeus minhas irmãs, parto para uma longa viagem.»"},
    {"type": "paragraph", "text": "Alusão ao meu “partir” para meu retiro de profissão"},
    {"type": "paragraph", "text": ")"},
    {"type": "heading", "text": "Olhando a fotografia do Pe. Bellière em soldado:"},
    {"type": "paragraph", "text": "... A esse soldado que parece tão asseado, dou conselhos como a uma menininha!"},
    {"type": "paragraph", "text": "Indico-lhe o caminho do amor e da confiança."},
    {"type": "paragraph", "text": "Desde a espiga, tenho sentimentos ainda mais humildes de mim mesma. Mas quão grande é a nova graça que recebi esta manhã, no momento em que o padre começou o Confiteor antes de me dar a comunhão e que todas as irmãs o continuaram. Via ali o bom Jesus bem perto de se dar a mim, e essa confissão me parecia uma humilhação tão necessária. «Confesso a Deus, à Bem-Aventurada Virgem Maria, a todos os Santos que tenho muito pecado...» Oh! sim, dizia para mim, faz bem pedir perdão por mim neste momento, a Deus, a todos os Santos... Sentia-me, como o publicano, uma grande pecadora. Achava o bom Deus tão misericordioso! Achava isso tão comovente de dirigir-se a toda a Corte Celeste, para obter por sua intercessão o perdão de Deus. Ah! quase chorei, e quando a Santa Hóstia esteve sobre meus lábios, estava muito emocionada."},
    {"type": "paragraph", "text": "... Que extraordinário ter sentido isso no Confiteor! Creio que é por causa da minha disposição presente; sinto-me tão miserável! Minha confiança não está diminuída, ao contrário, e a palavra «miserável» não é justa, pois sou rica de todos os tesouros divinos; mas é justamente por isso que me humilho mais. Quando penso em todas as graças que o bom Deus me fez, contenho-me para não derramar continuamente lágrimas de gratidão."},
    {"type": "paragraph", "text": "... Creio que as lágrimas que derramei esta manhã eram lágrimas de contrição perfeita. Ah! como é impossível dar a si mesmo tais sentimentos! É o Espírito Santo que os dá, ele «sopra onde quer.»"},
    {"type": "paragraph", "text": "Falávamos das resistências que fizera outrora quando a implorávamos que se poupasse, que não se levantasse à hora da Comunidade, que não fosse a Matinas. Ela nos disse:"},
    {"type": "paragraph", "text": "Não me compreendíeis quando insistia, mas era porque sentia bem que tentavam influenciar Nossa Madre. Queria dizer toda a verdade à Nossa Madre, para que ela decidisse por si mesma. Asseguro-vos que se de si mesma ela me tivesse pedido para não ir à Missa, à Comunhão, ao Ofício, teria obedecido com grande docilidade."},
    {"type": "paragraph", "text": "É inaudito, agora que não posso mais comer, dá-me vontades de todo tipo de coisas gostosas, como frango, costeletas, arroz com azeda de Domingo, atum!..."},
    {"type": "paragraph", "text": "... Poderão dizer de mim: «Não era neste mundo que ela vivia, mas no Céu, onde está seu tesouro.»"},
    {"type": "paragraph", "text": "13 août"},
    {"type": "paragraph", "text": "Eu lhe dizia um pensamento que tive durante completas sobre o Céu."},
    {"type": "paragraph", "text": "... Para mim, só tenho luzes para ver meu pequeno nada. Isso me faz mais bem que luzes sobre a fé."},
    {"type": "paragraph", "text": "14 août"},
    {"type": "paragraph", "text": "Comunhão"},
    {"type": "paragraph", "text": "... Muitos pequenos aborrecimentos no dia... Ah! quanto faço mal!"},
    {"type": "paragraph", "text": "Durante Matinas, disse-lhe: Tiveste muitas penas hoje:"},
    {"type": "paragraph", "text": "Sim, mas já que as amo... Amo tudo que o bom Deus me dá."},
    {"type": "paragraph", "text": "15 août"},
    {"type": "paragraph", "text": "Comunhão"},
    {"type": "paragraph", "text": "Lembrei-lhe o que diz São João da Cruz sobre a morte das almas consumadas na Caridade. Ela suspirou e me disse:"},
    {"type": "paragraph", "text": "Haverá que dizer que no fundo da minha alma é «alegria e arroubos»... Mas isso não encorajaria tanto as almas se se acreditasse que não sofri muito."},
    {"type": "paragraph", "text": "Como sinto que você está angustiada! E, no entanto, há um mês me dizias coisas tão belas sobre a morte de amor."},
    {"type": "paragraph", "text": "Mas o que vos dizia, diria-vos de novo."},
    {"type": "paragraph", "text": "Ela estava muito oprimida e como isso aumentava sempre, disse-me:"},
    {"type": "paragraph", "text": "Não sei o que me será!"},
    {"type": "paragraph", "text": "Isso te inquieta o que te sucederá? Com um tom inefável e um sorriso:"},
    {"type": "paragraph", "text": "Oh! não..."},
    {"type": "paragraph", "text": "Sonhei durante o silêncio que você me dizia: Vai estar muito cansada, quando a Comunidade vier, de ser olhada por todas as irmãs e obrigada a lhes falar um pouco. Respondi-te: Sim, mas, quando eu estiver lá em cima descansarei de tudo."},
    {"type": "paragraph", "text": "Pedi ontem à Santíssima Virgem de não tosseR mais, para que Irmã Geneviève pudesse dormir, mas acrescentei: Se não o fizeres, amarei-te ainda mais."},
    {"type": "paragraph", "text": "Minhas novas badalas tocavam para Vésperas; abri a porta para que as ouvisse bem e disse-lhe: Ouça bem os belos sinos que tocam. Depois de ouvir:"},
    {"type": "paragraph", "text": "... Não tão belas!"},
    {"type": "paragraph", "text": "O bom Deus me dá coragem na proporção de meus sofrimentos. Sinto que, por agora, não poderia suportar mais, mas não tenho medo, visto que se aumentarem, Ele aumentará meu ânimo no mesmo tempo."},
    {"type": "paragraph", "text": "Pergunto-me como o bom Deus pode deter-se tanto tempo em me tomar..."},
    {"type": "paragraph", "text": "... E então, dir-se-ia que Ele quer fazer-me «crer» que não há Céu!..."},
    {"type": "paragraph", "text": "... E todos os santos que tanto amo, onde estão «aninhados?»..."},
    {"type": "paragraph", "text": "... Ah! não finjo, é bem verdade que eu não vejo nada. Mas enfim, é preciso cantar bem alto no meu coração:"},
    {"type": "paragraph", "text": "«Depois da morte a vida é imortal»"},
    {"type": "paragraph", "text": "ou senão, iria dar para o mau..."},
    {"type": "paragraph", "text": "Depois de matinas, ela estava exausta e nos disse no momento em que nos preparávamos para bater seus travesseiros:"},
    {"type": "paragraph", "text": "Agora, façam de mim o que quiserem."},
    {"type": "paragraph", "text": "16 août"},
    {"type": "paragraph", "text": "Ela já não podia falar tanto estava fraca e oprimida."},
    {"type": "paragraph", "text": "... Não... mais... nem sequer... poder falar... convosco!... Oh! se se pudesse saber!... Se eu não amasse o bom Deus!... Sim, mas..."},
    {"type": "paragraph", "text": "No parlatório, não se deve dizer qualquer coisa, por exemplo falar de vaidade."},
    {"type": "paragraph", "text": "«Vocês não terão, vocês, uma ‘pequena Teresinha’ para vir buscar-vos.»"},
    {"type": "paragraph", "text": "Ela sorriu, e olhando a estátua da Santíssima Virgem e a imagem de Théophane Vénard, apontou-as com o dedo alternadamente."},
    {"type": "paragraph", "text": "Os anjos não podem sofrer, eles não são tão felizes quanto eu. Mas como se admirariam ao sofrer e sentir o que eu sinto!... Sim, ficariam muito espantados, porque eu própria o estou."},
    {"type": "paragraph", "text": "Durante Matinas, acordando de repente, e olhando-me com um doce sorriso:"},
    {"type": "paragraph", "text": "Minha linda pequena madre!"},
    {"type": "paragraph", "text": "17 août"},
    {"type": "paragraph", "text": "Comunhão"},
    {"type": "paragraph", "text": "Sinto bem que o bom Deus quer que eu sofra. Os remédios que deveriam fazer-me bem e que aliviam outros doentes, me fazem mal."},
    {"type": "paragraph", "text": "Acabavam de levantá-la, e como ao fazer a cama a tinham batido, que a tinham feito sofrer também ao lhe dar certos cuidados, pediu um pequeno pano. Hesitavam em darlho não sabendo o que queria dele. Ela então disse com doçura:"},
    {"type": "paragraph", "text": "Deveriam crer-me quando peço algo, pois sou uma “menininha” bem bonitinha:"},
    {"type": "paragraph", "text": "ou seja que não pede senão o indispensável"},
    {"type": "paragraph", "text": ")"},
    {"type": "paragraph", "text": "Uma vez recostada, sentindo-se à beira das forças:"},
    {"type": "paragraph", "text": "Sou uma “menininha” muito doente, sim, muito doente!"},
    {"type": "paragraph", "text": "Pôs uma pervinca na imagem de Théophane Vénard; guardei essa pervinca."},
    {"type": "paragraph", "text": "Vou rezar para que a Santíssima Virgem diminua tua opressão."},
    {"type": "paragraph", "text": "Não, é preciso deixá-los fazer aí em cima!"},
    {"type": "paragraph", "text": "Durante Matinas, olhando a imagem de Théophane Vénard:"},
    {"type": "paragraph", "text": "Não sei o que tenho, não posso mais olhá-lo sem chorar."},
    {"type": "paragraph", "text": "Ela se achou menos oprimida depois de Matinas e disse a Irmã Geneviève indicando-me:"},
    {"type": "paragraph", "text": "Ela rezou a Maria, e então não mais engasguei."},
    {"type": "paragraph", "text": "Ela empregava esta palavra para rir e com um toninho tão gentil, quando queria dizer que tossia até sufocar"},
    {"type": "paragraph", "text": ".)"},
    {"type": "paragraph", "text": "18 août"},
    {"type": "paragraph", "text": "Sofro muito, mas será que sofro bem? Eis aí!"},
    {"type": "paragraph", "text": "“Bebê” está exausto!..."},
    {"type": "paragraph", "text": "Durante o silêncio do meio-dia, eu me tinha escondido um pouco atrás do leito para escrever."},
    {"type": "paragraph", "text": "Vire-se de lado, para que eu a veja."},
    {"type": "paragraph", "text": "Mamãe, é preciso ler-me a carta que recebeu para mim. Privara-me de pedi-la durante a oração, para me preparar à minha comunhão de amanhã e porque isso não é permitido."},
    {"type": "paragraph", "text": "Era durante a recreação."},
    {"type": "heading", "text": "Vendo-me pegar o lápis para escrever isso:"},
    {"type": "paragraph", "text": "Meu mérito vai talvez se perder, já que te disse isso e você o escreve?"},
    {"type": "paragraph", "text": "Você quer portanto adquirir méritos?"},
    {"type": "paragraph", "text": "Sim, mas não para mim; para os pobres pecadores, para as necessidades de toda a Igreja, enfim para jogar flores a todo o mundo, justos e pecadores."},
    {"type": "heading", "text": "Eu lhe dizia que ela era bem paciente:"},
    {"type": "paragraph", "text": "Ainda não tive um minuto de paciência. Não é minha paciência!... Equivocam-se sempre!"},
    {"type": "paragraph", "text": "Visto que se diz que todas as almas são tentadas pelo demônio no momento da morte, terei de passar por isso. Mas contudo não, sou pequena demais. Com os mui pequenos, ele não pode..."},
    {"type": "paragraph", "text": "Eu lhe dizia: Como te pareceria estranho voltar à saúde?"},
    {"type": "paragraph", "text": "Se fosse a vontade do bom Deus, eu seria bem feliz de lhe fazer esse sacrifício. Mas asseguro-vos que não seria pouca coisa, pois ir tão longe, e voltar! escute..."},
    {"type": "paragraph", "text": "No estado de fraqueza em que me encontro, pergunto-me o que me faria se visse uma grande aranha em nossa cama. Enfim, aceito ainda esse medo por amor do bom Deus."},
    {"type": "paragraph", "text": "... Mas se pedisse à Santíssima Virgem que isso não acontecesse?"},
    {"type": "paragraph", "text": "19 août"},
    {"type": "paragraph", "text": "Quase se sentiu mal antes da comunhão, ao ouvir psalmodiar, mesmo em voz baixa, o Miserere. Disse-me depois vertendo grossas lágrimas:"},
    {"type": "paragraph", "text": "Vou talvez perder as idéias. Oh! Se se soubesse o que é a fraqueza que experimento."},
    {"type": "paragraph", "text": "Essa noite, não pude mais; pedi à Santíssima Virgem que tomasse minha cabeça nas mãos para que eu pudesse suportá-la."},
    {"type": "paragraph", "text": "Fique comigo, minha pequena Madre, faz-me como um apoio tê-la."},
    {"type": "paragraph", "text": "Irmã Geneviève deu-lhe o crucifixo. Ela beijou-o no rosto com ternura. Estava bela nesse momento como um anjo. Esse crucifixo tinha a cabeça inclinada, disse-o contemplando-o:"},
    {"type": "paragraph", "text": "Ele está morto, Ele! Prefiro representá-lo morto, porque penso que ele já não sofre."},
    {"type": "paragraph", "text": "Pedia certos cuidados que lhe custavam muito, mas que o médico e Nossa Madre tinham recomendado. Irmã Geneviève lhe disse como a uma criancinha: «Quem foi que pediu isso à ‘mãezinha’?»"},
    {"type": "paragraph", "text": "Foi “bebê”, por fidelidade."},
    {"type": "paragraph", "text": "Acariciava Théophane Vénard nas duas faces."},
    {"type": "paragraph", "text": "A imagem estava presa na cortina, um pouco distante dela."},
    {"type": "paragraph", "text": ")"},
    {"type": "paragraph", "text": "Por que o acaricias assim?"},
    {"type": "paragraph", "text": "Porque não posso abraçá-lo."},
    {"type": "heading", "text": "À Irmã Marie da Eucaristia:"},
    {"type": "paragraph", "text": "Não se deve sentar assim torto nas cadeiras; está escrito."},
    {"type": "paragraph", "text": "A Irmã Geneviève que arrumava seus travesseiros sem reparar nas imagens da cortina:"},
    {"type": "paragraph", "text": "Cuidado com o pequeno Théophane!"},
    {"type": "paragraph", "text": "Falava-se demais quando nos achávamos reunidas as três perto dela; isso a fatigava, porque se lhe faziam muitas perguntas ao mesmo tempo."},
    {"type": "paragraph", "text": "“O que queres que digamos hoje?”"},
    {"type": "paragraph", "text": "... Seria para bem fazer que não se dissesse nada, porque a dizer a verdade, não há nada a dizer."},
    {"type": "paragraph", "text": "“Tudo está dito, não é?”"},
    {"type": "paragraph", "text": "Sim!"},
    {"type": "paragraph", "text": "Seja o que me digais, as coisas mais insignificantes; fazes-me o efeito de um gracioso trovador que canta suas lendas sempre com novos ares."},
    {"type": "paragraph", "text": "E ela fazia pequenos suplementos para me fazer ver que bebia minhas palavras."},
    {"type": "paragraph", "text": "... Não sofro senão um instante. É porque se pensa no passado e no futuro que se desanima e se desespera."},
    {"type": "paragraph", "text": "20 août"},
    {"type": "heading", "text": "À Irmã Geneviève, com tom de criança:"},
    {"type": "paragraph", "text": "Sabe bem que cuidais de um “bebê” na morte..."},
    {"type": "paragraph", "text": "E depois ("},
    {"type": "paragraph", "text": "mostrando seu copo"},
    {"type": "paragraph", "text": ") seria preciso pôr algo gostoso no copo grande, porque “bebê” tem muito gosto de podre na boca."},
    {"type": "paragraph", "text": "Tinha pedido que a beijassem pouco, porque o hálito a fatigava, estando tão fraca."},
    {"type": "paragraph", "text": "Posso fazer-lhe só um pequeno carinho?"},
    {"type": "paragraph", "text": "Sim, porque as mãos não respiram."},
    {"type": "paragraph", "text": "Falava-se dos aborrecimentos que dava às enfermeiras a pobre Madre Coração de Jesus."},
    {"type": "paragraph", "text": "Oh! que eu teria gostado de ser enfermeira, não por natureza mas “por um atraente da graça”. E como me parece que teria tornado a Madre C. de Jesus feliz! Sim, teria gosto para tudo isso... E teria posto tanto amor, pensando na palavra do bom Deus: “Estive doente e me achegastes”. É ainda raro encontrar essa bela ocasião no Carmelo."},
    {"type": "heading", "text": "Com ar alegre e malicioso:"},
    {"type": "paragraph", "text": "Logo estarei nas horrores do túmulo! E vocês também estarão um dia, minha pequena Madre!... E, vendo chegar perto de mim, “meus ossos humilhados estremecerão de alegria.”"},
    {"type": "paragraph", "text": "... Assim que eu beber (a beber) isso me faz assim. (Ela tosse e diz ao seu copo de água de Bottot: Não é para beber! A parte: - Ele não entende - mais alto: Não é para beber te digo!)"},
    {"type": "paragraph", "text": "Já não podia ver o leite que aliás nunca tomara com prazer e que, então, lhe causava repugnância extrema. Eu lhe disse: “Beberias bem esta xícara para me salvar a vida?”"},
    {"type": "paragraph", "text": "Oh! sim!... Pois bem, olhe, e eu não a tomaria por amor do bom Deus?"},
    {"type": "paragraph", "text": "E ela bebeu a xícara duma vez."},
    {"type": "paragraph", "text": "Fizemos nossas reflexões a propósito do símbolo do manto de enfermaria. +.F."},
    {"type": "paragraph", "text": "Não, isso não significa o que dizeis. Quer dizer que é preciso que se leve a cruz (+), para ir após, mais alto que o firmamento (F.)"},
    {"type": "paragraph", "text": "Quando sofro muito, fico contente que seja eu; fico contente que não seja uma de vós."},
    {"type": "paragraph", "text": "“É contigo que me agrado mais, minha boa Clarice.”"},
    {"type": "paragraph", "text": "Palavra dirigida à Madre Geneviève por seu irmãozinho"},
    {"type": "paragraph", "text": ".)"},
    {"type": "paragraph", "text": "A propósito da Comunhão que sentia bem não mais poder fazer doravante, e por consequência de muitas reflexões que ouviu a esse respeito, esse dia foi um dia de angústias e de tentações que eu adivinhava terríveis. Pediu-me à tarde que guardasse silêncio por algum tempo e até que não a olhasse. Disse-me baixinho:"},
    {"type": "paragraph", "text": "Choraria demais se te contasse logo minhas penas, e estou tão oprimida que certamente sufocaria."},
    {"type": "paragraph", "text": "Depois de um silêncio de ao menos uma hora, falou-me, mas pondo diante dos olhos a tela que lhe deram para as moscas, porque ainda estava muito emocionada."},
    {"type": "paragraph", "text": "Falou-me da carta dum padre que dizia que a Santíssima Virgem não conhecia por experiência os sofrimentos físicos."},
    {"type": "paragraph", "text": "Olhando a Santíssima Virgem esta noite, compreendi que isso não era verdade; compreendi que ela sofrera não somente da alma, mas também do corpo. Sofreu muito nas viagens, do frio, do calor, do cansaço. Jejuou muitas vezes."},
    {"type": "paragraph", "text": "... Sim, ela sabe o que é sofrer."},
    {"type": "paragraph", "text": "... Mas talvez seja mal desejar que a Santíssima Virgem tenha sofrido? Eu que a amo tanto!"},
    {"type": "paragraph", "text": "Ela estava muito oprimida."},
    {"type": "paragraph", "text": "Há algum tempo, achava nessas opressões tão penosas uma espécie de alívio em soltando como um pequeno grito regular, seja: “Oh! lá lá!” ou “Agne! Agne!”"},
    {"type": "paragraph", "text": "É quando a opressão vem de baixo que digo “Agne! Agne!” mas não é bonito, isso me desagrada; agora direi: Anne! Anne!"},
    {"type": "paragraph", "text": "Pôr-se-á isso em sua circular."},
    {"type": "paragraph", "text": "Isso faria o efeito de uma receita de cozinha!"},
    {"type": "paragraph", "text": "És tu quem me deste a consolação de ter o retrato de Théophane Vénard; ela é extremamente grande. Mas é que ele bem podia não me agradar! ... Mas ele é “muito agradavel”, ele é “muito amável”."},
    {"type": "paragraph", "text": "(1)"},
    {"type": "paragraph", "text": "1)"},
    {"type": "paragraph", "text": "Expressões que ouvira e que a divertiram."},
    {"type": "paragraph", "text": "Que será gentil conhecer no Céu tudo quanto se passou na Sagrada Família! Quando o pequeno Jesus começou a crescer, talvez vendo a Santíssima Virgem jejuar, dizia-lhe: “Eu gostaria de jejuar também.” E a Santíssima Virgem respondia:"},
    {"type": "paragraph", "text": "“Não, meu pequeno Jesus, és demasiado pequeno ainda, não tens força.” Ou então talvez não ousasse impedir-lhe."},
    {"type": "paragraph", "text": "E o bom S"},
    {"type": "paragraph", "text": "t"},
    {"type": "paragraph", "text": "José! Oh! quanto o amo! Ele não podia jejuar por causa de seus trabalhos."},
    {"type": "paragraph", "text": "Vejo-o lixar, depois enxugar a testa de tempo em tempo. Oh! como me dá pena! Como me parece que sua vida era simples!"},
    {"type": "paragraph", "text": "As mulheres do povo vinham falar à Santíssima Virgem familiarmente. Às vezes pediam-lhe confiar seu pequeno Jesus para irem brincar com seus filhos. E o pequeno Jesus olhava a Santíssima Virgem para saber se devia ir. Algumas vezes mesmo as boas mulheres iam diretamente ao Menino Jesus e lhe diziam sem cerimônia: “Vem brincar com meu menino” etc."},
    {"type": "paragraph", "text": "... O que me faz bem quando penso na Sagrada Família, é imaginar uma vida toda ordinária. Não tudo quanto nos contam, tudo quanto se supõe. Por exemplo que o Menino Jesus depois de amassar pássaros de barro soprava sobre eles e lhes dava a vida. Ah! mas não, o pequeno Jesus não fazia milagres inúteis assim, mesmo para agradar sua Mãe. Ou então por que não foram transportados ao Egito por um milagre que teria sido mais necessário e tão fácil ao bom Deus. Num piscar de olhos teriam sido levados lá. Mas não, tudo em sua vida se fez como na nossa."},
    {"type": "paragraph", "text": "E quantas penas, quantas decepções! Quantas vezes fizeram reproches ao bom S"},
    {"type": "paragraph", "text": "t"},
    {"type": "paragraph", "text": "José! Quantas vezes se recusou pagar seu trabalho! Oh! como se ficaria espantado se se soubesse tudo quanto sofreram! etc. etc."},
    {"type": "paragraph", "text": "Falou-me longamente sobre esse assunto e não pude escrever tudo."},
    {"type": "paragraph", "text": "... Gostaria de ter certeza de que ela me ama, a Santíssima Virgem."},
    {"type": "paragraph", "text": "... Quando se pensa que tanto me custou a vida inteira dizer meu terço!"},
    {"type": "paragraph", "text": "Quando recebi a absolvição, em lugar de me perder em orações para agradecer ao bom Deus, penso simplesmente com gratidão que me pôs um hábitozinho bem branco e me trocou de vestido. Nem um nem outro estavam bem sujos, mas tanto faz, minhas roupas pequenas estão mais brilhantes e sou melhor vista por todo o Céu."},
    {"type": "paragraph", "text": "Não se imagina que Irmã Marie do Sagrado Coração sendo provisória me fez fazer muitas mortificações. Ela me ama tanto que eu parecia bem mimada; mas a mortificação é maior nesse caso."},
    {"type": "paragraph", "text": "... Ela cuidava de mim segundo seus gostos absolutamente opostos aos meus."},
    {"type": "paragraph", "text": "21 août"},
    {"type": "paragraph", "text": "Sofria muito e eu a olhava de joelhos o coração bem triste."},
    {"type": "paragraph", "text": "Olhinhos tristes, por quê?"},
    {"type": "paragraph", "text": "Porque sofre tanto!"},
    {"type": "paragraph", "text": "Sim, mas paz também, paz!"},
    {"type": "paragraph", "text": "... Não há mais nada senão dodo para “bebê”... tudo, tudo faz sofrer!"},
    {"type": "paragraph", "text": "Nem mais dodo para bebê! Acabou! Vou sufocar uma noite, sinto bem!"},
    {"type": "paragraph", "text": "Como teria gostado de ser padre para pregar sobre a Santíssima Virgem! Uma só vez teria-me bastado para dizer tudo o que penso a esse respeito."},
    {"type": "paragraph", "text": "Faria primeiro compreender quanto pouco se conhece sua vida."},
    {"type": "paragraph", "text": "Não se deveria dizer coisas inverossímeis ou que não se sabe; por exemplo que, toda pequena, aos três anos, a Santíssima Virgem foi ao Templo oferecer-se a Deus com sentimentos ardentes de amor e tudo extraordinários; enquanto ela talvez tenha ido simplesmente para obedecer seus pais."},
    {"type": "paragraph", "text": "Por que dizer ainda, a propósito das palavras proféticas do velho Simeão, que a Santíssima Virgem, a partir daquele momento teve constantemente diante dos olhos a paixão de Jesus? «Uma espada de dor traspassará tua alma» havia dito o velho. Não era pois para o presente, vede bem, minha pequena Madre; era uma predição geral para o futuro."},
    {"type": "paragraph", "text": "Para que um sermão sobre a Santíssima Virgem me agrade e me faça bem, é preciso que veja sua vida real, não sua vida suposta; e estou certa que sua vida real devia ser toda simples. Mostrá-la inatingível, deveria mostrá-la imitável, realçar suas virtudes, dizer que vivia de fé como nós, dar provas pelo Evangelho onde lemos: «Não entenderam o que lhes dizia.» E essa outra, não menos misteriosa: Essa admiração supõe certo espanto, não achas, minha pequena Madre?"},
    {"type": "paragraph", "text": "Sabe-se bem que a Santíssima Virgem é Rainha do Céu e da terra, mas ela é mais Mãe que rainha, e não se deve dizer por causa de suas prerrogativas que eclipsa a glória de todos os santos, como o sol ao nascer faz desaparecer as estrelas. Meu Deus! que é estranho! Uma Mãe que faz desaparecer a glória de seus filhos! Eu penso todo o contrário, creio que aumentará muito a esplendôr dos eleitos."},
    {"type": "paragraph", "text": "É bom falar de suas prerrogativas, mas não se deve dizer só isso, e se num sermão é preciso do começo ao fim exclamar e fazer Ah! Ah! já se tem o suficiente! Quem sabe se alguma alma não sentiria então certo distanciamento por uma criatura tão superior e não diria: «Se isso é tudo, tanto brilhar o quanto se puder num cantinho!»"},
    {"type": "paragraph", "text": "O que a Santíssima Virgem tem a mais que nós, é que não podia pecar, que estava isenta da mancha original, mas por outro lado, teve bem menos sorte que nós, visto que não teve uma Santíssima Virgem a amar; e isso é tal doçura a mais para nós, e uma tal doçura a menos para ela!"},
    {"type": "paragraph", "text": "Enfim disse no meu Cântico: «Por que te amo, ó Maria!» tudo quanto pregaria sobre ela."},
    {"type": "paragraph", "text": "22 août"},
    {"type": "paragraph", "text": "É a festa do bom papai hoje."},
    {"type": "paragraph", "text": "Santo Joaquim"},
    {"type": "paragraph", "text": ")"},
    {"type": "paragraph", "text": "Oh minha pequena Madre, o que me sucederia se o bom Deus não me desse força? Já não há senão mãos!... Não se sabe o que é sofrer assim! Não, é preciso sentir."},
    {"type": "paragraph", "text": "... Encontraram-lhe imperfeita em tal ocasião..."},
    {"type": "heading", "text": "Com satisfação:"},
    {"type": "paragraph", "text": "Oh! bem, tanto melhor!"},
    {"type": "paragraph", "text": "Do lado dos intestinos e... aliás, sofria violentamente, temeu-se a gangrena."},
    {"type": "paragraph", "text": "... Pois bem, vale mais, já que há que sofrer muito e por toda parte, ter várias moléstias juntas. É como em viagem, onde se suporta todo tipo de incómodo, sabendo bem que isso vai terminar depressa e que uma vez o objetivo alcançado, se goza tudo mais."},
    {"type": "paragraph", "text": "Sobre uma reflexão que lhe fizeram"},
    {"type": "paragraph", "text": "não me lembro mais por quê"},
    {"type": "paragraph", "text": ")"},
    {"type": "paragraph", "text": "Acreditas que a Santíssima Virgem fez contorções como Santa Madalena! Ah mas não, não teria sido gentil. Dá-se bem para eu soluçar!"},
    {"type": "paragraph", "text": "Ela tinha derrubado tília sobre o leito; disseram-lhe para consolá-la que não fazia nada."},
    {"type": "paragraph", "text": "Com ar que dizia que havia que sofrer de todo modo:"},
    {"type": "paragraph", "text": "Ah! não faz nada, não!"},
    {"type": "paragraph", "text": "Olhou-me durante a oração, depois seu retrato de Théophane Vénard com seu olhar tão doce e tão profundo."},
    {"type": "paragraph", "text": "Algum tempo depois quis falar para me fazer prazer pois mal podia respirar. Eu disse-lhe para guardar silêncio."},
    {"type": "paragraph", "text": "Não, não devo falar? ... Mas... pensei... Eu amo tanto você! ... Vou ser meiguinha... Oh minha pequena Madre!"},
    {"type": "paragraph", "text": "Queriam impedi-la de fazer despesas para nos consolar:"},
    {"type": "paragraph", "text": "Deixe-me fazer minhas pequenas “palhaçadas”."},
    {"type": "paragraph", "text": "Tive prazer em pensar que se rezava por mim, então disse ao bom Deus que queria que fosse aplicado aos pecadores."},
    {"type": "paragraph", "text": "Não queres então que seja para teu alívio?"},
    {"type": "paragraph", "text": "Não!"},
    {"type": "paragraph", "text": "Sofria muito e gemia."},
    {"type": "paragraph", "text": "Minha pequena Madre!... Sim!... Eu quero!..."},
    {"type": "paragraph", "text": "... Não devo mais queixar-me, não serve de nada. Rezem por mim, minhas pequenas irmãs, mas não de joelhos, sentadas."},
    {"type": "paragraph", "text": "Estávamos de joelhos."},
    {"type": "paragraph", "text": "23 août"},
    {"type": "paragraph", "text": "Ainda não tinha passado uma noite tão má. Oh! como é preciso que o bom Deus seja bom para que eu possa suportar tudo quanto sofro! Jamais teria crido poder sofrer tanto. E contudo creio que não estou no fim de meus padecimentos; mas Ele não me abandonará."},
    {"type": "heading", "text": "Cantastes à Santíssima Virgem:"},
    {"type": "paragraph", "text": "«Tudo quanto me deu, Jesus pode tomar de volta,"},
    {"type": "paragraph", "text": "Dize-lhe que nunca se prive comigo.»"},
    {"type": "paragraph", "text": "Ela o disse e Ele te toma pela palavra."},
    {"type": "paragraph", "text": "Fico contente e não me arrependo."},
    {"type": "paragraph", "text": "... Não, o bom Deus não me pressente uma morte próxima, mas sofrimentos muito maiores... Mas não me perturbo, não quero pensar senão no momento presente."},
    {"type": "paragraph", "text": "Dizia-lhe que me tinham dado uma grande coberta para o inverno, que era mesmo demasiado grande."},
    {"type": "paragraph", "text": "Oh! mas não, no inverno nunca se tem calor demais."},
    {"type": "paragraph", "text": "... Terás frio, quando eu não tiver frio! Dá-me pena."},
    {"type": "paragraph", "text": "Beije-me na testa."},
    {"type": "heading", "text": "À Irmã Geneviève:"},
    {"type": "paragraph", "text": "Roga bem à Santíssima Virgem por mim, tu que és minha pequena enfermeira, porque se estivesses doente, rezaria tanto por ti! Mas quando é por si, não se ousa."},
    {"type": "paragraph", "text": "Ela tinha oferecido seus sofrimentos por M. l’Abbé de Cornières, então seminarista, e muito tentado. Ele o soube e escreveu uma carta das mais humildes e comoventes."},
    {"type": "paragraph", "text": "Oh! que essa carta me trouxe consolação! Vi que meus pequenos sofrimentos davam fruto. Notastes os sentimentos de humildade que expressa? É justamente isso que desejava."},
    {"type": "paragraph", "text": "... E que bem me faz ver como em tão pouco tempo se pode ter tanto amor e reconhecimento por uma alma que te fez bem e que até então não conhecias. O que será no Céu quando as almas conhecerem aquelas que as terão salvo?!"},
    {"type": "heading", "text": "No meio de seus sofrimentos tão grandes:"},
    {"type": "paragraph", "text": "Minha pequena Madre!... Minha pequena Madre!... Oh!... Oh!... Sim!... Mamã! mamã! mamã!..."},
    {"type": "paragraph", "text": "... Quando se rezou à Santíssima Virgem e ela não nos atende, é sinal que ela não quer. Então há que deixá-la fazer segundo sua ideia e não se perturbar."},
    {"type": "paragraph", "text": "Dizia-me que tudo quanto ouvira pregar sobre a Santíssima Virgem não a tocara."},
    {"type": "paragraph", "text": "Que os padres nos mostrem virtudes praticáveis! É bom falar de suas prerrogativas, mas é preciso sobretudo que se possa imitar. Ela prefere a imitação à admiração, e sua vida foi tão simples! Por mais bonito que seja um sermão sobre a Santíssima Virgem, se é preciso o tempo todo dizer: Ah!... Ah!... já se tem demais."},
    {"type": "heading", "text": "Como gosto de-lhe cantar:"},
    {"type": "paragraph", "text": "O estreito caminho do Céu tu o tornaste visível (Ela dizia: fácil)"},
    {"type": "paragraph", "text": "Praticando sempre as mais humildes virtudes."},
    {"type": "paragraph", "text": "... Mamã!... Ah! estou sempre a queixar-me!... Vamos, mas!... Quero bem, contudo, ficar doente... mas é quando eu tosso todo o tempo e não posso..."},
    {"type": "paragraph", "text": "Hoje se cessou o regime do leite"},
    {"type": "paragraph", "text": ")"},
    {"type": "heading", "text": "Acariciei sua testa depois de matinas:"},
    {"type": "paragraph", "text": "Oh! que é doce!"},
    {"type": "paragraph", "text": "24 août"},
    {"type": "paragraph", "text": "Estás desencorajada?"},
    {"type": "paragraph", "text": "Não!... contudo tudo tende ao pior! a cada respiração sofro violentamente. Enfim ainda não é de gritar."},
    {"type": "paragraph", "text": "Naquela manhã tinha um ar particularmente doce e sereno"},
    {"type": "paragraph", "text": ")."},
    {"type": "paragraph", "text": "... Gostaria tanto de falar contigo!... Que mortificação!... Vão! custa-me."},
    {"type": "paragraph", "text": "... Minha pequena Madre, queres que te fale ainda?"},
    {"type": "paragraph", "text": "Mantinha-a há muito tempo em silêncio"},
    {"type": "paragraph", "text": ".)"},
    {"type": "heading", "text": "Meia hora depois, durante a recreação:"},
    {"type": "paragraph", "text": "Minha pequena Madre!... ah! eu que a amo tanto!"},
    {"type": "heading", "text": "Ao despertar durante Matinas:"},
    {"type": "paragraph", "text": "... Infelizmente! desde o tempo em que te falo! E vejo que não sabes a primeira palavra!"},
    {"type": "paragraph", "text": "Ela tinha-me explicado seu mal num pesadelo"},
    {"type": "paragraph", "text": ")"},
    {"type": "paragraph", "text": "... E agora, sinto a tosse ameaçadora! Enfim!..."},
    {"type": "paragraph", "text": "Tudo tende ao pior, não é?"},
    {"type": "paragraph", "text": "Não, para o melhor."},
    {"type": "paragraph", "text": "Tinha-a compadecido, e na reflexão de Irmã Geneviève de que isso não adiantava muito:"},
    {"type": "paragraph", "text": "Mas sim! é justamente isso que alivia os doentes."},
    {"type": "paragraph", "text": "25 août"},
    {"type": "paragraph", "text": "Eu lhe dizia meu desejo de conhecer a data de sua morte."},
    {"type": "paragraph", "text": "Ah! eu não a desejo! Em que paz estou! Não me inquieta muito."},
    {"type": "paragraph", "text": "A porta da enfermaria estava aberta durante o silêncio e Irmã St Jean de la Croix entrava todas as noites, e pondo-se ao pé do leito, olhava-a rindo durante bastante tempo."},
    {"type": "paragraph", "text": "Que visita indiscreta e como ela deve te cansar!"},
    {"type": "paragraph", "text": "Mas sim, é muito penoso ser olhada rindo quando se sofre. Mas penso que Nosso Senhor na cruz foi bem olhado assim no meio de seus sofrimentos. Era ainda bem pior, pois zombavam realmente dele; não está dito no Evangelho que o olhavam balançando a cabeça? Esse pensamento me ajuda a oferecer com bom coração esse sacrifício."},
    {"type": "paragraph", "text": "Como sofre! Oh! que duro! Estás triste?"},
    {"type": "paragraph", "text": "Oh! não, não estou nada infeliz. O bom Deus dá-me justamente o que posso suportar."},
    {"type": "paragraph", "text": "Tinham-lhe trazido de parte da minha tia ramos de miosótis artificiais muito bonitos. Puseram-nos a enfeitar suas imagens."},
    {"type": "paragraph", "text": "Durante o silêncio, com ar infantil e tão gracioso:"},
    {"type": "paragraph", "text": "Tive vontade que me dessem algo, não me analisava muito o que nem por quê; mas tive vontade, e deram isto."},
    {"type": "paragraph", "text": "Ai minha pobre menininha, podes bem dizer: “Que longo é meu exílio!”"},
    {"type": "paragraph", "text": "Mas eu não o acho longo; não é porque sofro que é mais longo."},
    {"type": "heading", "text": "Gemia docemente:"},
    {"type": "paragraph", "text": "... Oh! como me queixo! contudo não gostaria de sofrer menos."},
    {"type": "paragraph", "text": "Rogava-nos que rezássemos e fizessemos rezar por ela:"},
    {"type": "paragraph", "text": "... Oh! como é preciso rezar pelos agonizantes! Se se soubesse!"},
    {"type": "paragraph", "text": "Creio que o demônio pediu ao bom Deus permissão de me tentar por uma dor extrema, para me fazer faltar à paciência e à fé."},
    {"type": "paragraph", "text": "Foi a Irmã M. do Sagrado Coração que falou do hino das Completas a propósito das tentações do espírito das trevas e dos fantasmas da noite."},
    {"type": "paragraph", "text": "Era a festa de Santo Luís, fizera uma oração fervorosa a papai, e sem ser atendida."},
    {"type": "paragraph", "text": "... Apesar do que senti no primeiro momento, repeti ao bom Deus que o amava mais e a todos os santos também."},
    {"type": "paragraph", "text": "Partilhei-lhe minha tristeza pensando no que ainda teria de sofrer:"},
    {"type": "paragraph", "text": "Estou pronta para tudo... Vês no entanto que, até agora, não tive além de minhas forças."},
    {"type": "paragraph", "text": "... Há que abandonar-se. Queria que vos alegrásseis."},
    {"type": "paragraph", "text": "... Oh! sim, eu quero bem! sim! mas é bem isso!..."},
    {"type": "paragraph", "text": "O quê então?"},
    {"type": "paragraph", "text": "Sufocarei!"},
    {"type": "heading", "text": "26 de agosto"},
    {"type": "paragraph", "text": "Tinham-lhe deixado acesa toda a noite a vela benzida."},
    {"type": "paragraph", "text": "É por causa da vela benzida que não passei uma noite tão má."},
    {"type": "heading", "text": "À Nossa Madre, durante a oração:"},
    {"type": "paragraph", "text": "Estou bem contente de não ter pedido nada ao bom Deus; assim, Ele é forçado a dar-me coragem."},
    {"type": "paragraph", "text": "Eu dizia-lhe que ela estava feita para muito sofrer, que sua alma tinha fibra para isso:"},
    {"type": "paragraph", "text": "Ah! sofrer da alma, sim, posso muito... mas para a dor do corpo, sou como uma criança pequena, toda pequena. Não tenho pensamento, sofro de minuto em minuto."},
    {"type": "heading", "text": "Devia confessar-se:"},
    {"type": "paragraph", "text": "Minha pequena Madre, teria muito a lhe dizer, se pudesse. Não sei se devo dizer a M"},
    {"type": "paragraph", "text": "r"},
    {"type": "paragraph", "text": "Youf que tive pensamentos de gula, porque pensei em coisas que gosto, mas ofereço-as ao bom Deus."},
    {"type": "paragraph", "text": "Ela sufocava."},
    {"type": "paragraph", "text": "... Ah! vou sufocar! ... Sim!..."},
    {"type": "paragraph", "text": "com voz doce e queixosa, o “sim” era como um pequeno grito.)"},
    {"type": "paragraph", "text": "Durante Matinas eu lhe dizia para mover-se a seu gosto para encontrar um pequeno alívio."},
    {"type": "paragraph", "text": "... Que é difícil com o que tenho encontrar alívio!"},
    {"type": "paragraph", "text": "Um ponto se desfêra no tecido que guarnecia sua túnica, eu tentei refazê-lo mas era muito difícil e mexia-me mal, cansava-a muito, ela já não podia mais e disse-me depois:"},
    {"type": "paragraph", "text": "Ó minha pequena madre, como não há que se espantar que uma pobre enfermeira se zangue às vezes com suas doentes. Vês como sou difícil! Quanto te amo!... És tão doce. Estou-te tão agradecida, choraria por isso!"},
    {"type": "paragraph", "text": "Que longa é tua doença, minha pobre!"},
    {"type": "paragraph", "text": "Oh! não, não a acho longa. Quando acabar, verás que não te parecerá longa."},
    {"type": "paragraph", "text": "Ó minha pequena Madre, quanto é preciso que o bom Deus auxilie quando se sofre tanto!"},
    {"type": "heading", "text": "27 de agosto"},
    {"type": "paragraph", "text": "Oh! como se é infeliz quando se está doente!"},
    {"type": "paragraph", "text": "Mas não, não se é infeliz quando é para morrer. Ai! como é engraçado ter medo de morrer!"},
    {"type": "paragraph", "text": "... Enfim, quando se é casada, se tem um marido e filhos, compreende-se; mas eu que não tenho nada!..."},
    {"type": "paragraph", "text": "... Quanto eu gostaria que Monseigneur não viesse ver-me... Enfim, é uma graça a bênção de um Bispo."},
    {"type": "heading", "text": "Rindo:"},
    {"type": "paragraph", "text": "Se fosse somente S"},
    {"type": "paragraph", "text": "t"},
    {"type": "paragraph", "text": "Nicolau que ressuscitou três meninos!"},
    {"type": "paragraph", "text": "Mons. Hugonin estava em Lisieux."},
    {"type": "paragraph", "text": ")"},
    {"type": "paragraph", "text": "Não estás espantada, minha pequena Madre, da maneira como sofro?"},
    {"type": "paragraph", "text": "... Enfim, tenho uma grande paz no fundo."},
    {"type": "paragraph", "text": "Não levaste nada desde esta manhã."},
    {"type": "paragraph", "text": "Nada tomado! mas tomei duas xícaras de leite, estou empanturrada. Sou empanturrada, não é preciso comprar."},
    {"type": "paragraph", "text": "Faço noites em claro a essa pobre Irmã Geneviève!"},
    {"type": "heading", "text": "Durante a recreação do meio-dia:"},
    {"type": "paragraph", "text": "Disseste-me esta manhã que nada tinhas, e tens pequenas irmãs, uma pequena Madre."},
    {"type": "paragraph", "text": "Não, não tenho nada, porque não as deixo, elas!"},
    {"type": "heading", "text": "Com ar malicioso:"},
    {"type": "paragraph", "text": "Ora! se eu pensasse que as deixo!"},
    {"type": "paragraph", "text": "Ai! se fosses doente até a próxima primavera! Tenho medo, e que dirias?"},
    {"type": "paragraph", "text": "Ora eu diria tanto melhor!"},
    {"type": "paragraph", "text": "Ela teve um momento de grande alívio à tarde e fez-nos todo tipo de gentilezas."},
    {"type": "paragraph", "text": "Sofria continuamente de sede. Irmã Marie do Sagrado Coração disse-lhe: Queres água gelada?"},
    {"type": "paragraph", "text": "Oh! tenho muita vontade!"},
    {"type": "paragraph", "text": "Nossa Madre obrigou-te a pedir tudo quanto te é necessário."},
    {"type": "paragraph", "text": "Peço com efeito tudo quanto necessito."},
    {"type": "paragraph", "text": "Não pedes senão o necessário? nunca o que pode aliviar-te?"},
    {"type": "paragraph", "text": "Não, só o necessário. Assim quando não há uva, não peço."},
    {"type": "paragraph", "text": "Algum tempo depois de ter bebido olhava seu copo de água gelada:"},
    {"type": "paragraph", "text": "Bebe mais um pouco, disse-se."},
    {"type": "paragraph", "text": "Não, não tenho a língua suficientemente seca."},
    {"type": "heading", "text": "28 de agosto"},
    {"type": "paragraph", "text": "Viraram o leito para a janela."},
    {"type": "paragraph", "text": "Oh! como estou contente!"},
    {"type": "paragraph", "text": "Põe-te em frente, minha pequena Madre, para que eu te veja bem."},
    {"type": "paragraph", "text": "Nossa Madre e outras irmãs diziam que ela era bonita, contavam-lhe isso."},
    {"type": "paragraph", "text": "Ah! que me faz! Me faz menos que nada, me aborrece. Quando se está tão perto da morte, não se pode ter alegria com isso."},
    {"type": "heading", "text": "Durante o silêncio do meio-dia:"},
    {"type": "paragraph", "text": "Olhe, vês ali o buraco negro (sob os castanheiros perto do cemitério) onde já não se distingue nada; é num buraco assim que estou para a alma e para o corpo. Ah! sim, que trevas! Mas estou aí em paz."},
    {"type": "paragraph", "text": "Não podia mais e gemia."},
    {"type": "paragraph", "text": "Creio que o bom Deus ficaria mais contente se eu não dissesse nada."},
    {"type": "paragraph", "text": "Minha pequena Madre, tira-me essa tolice coisinha branca."},
    {"type": "paragraph", "text": "O que é isso?"},
    {"type": "paragraph", "text": "Partiu! É uma coisinha bonita que voa durante o verão."},
    {"type": "paragraph", "text": "uma semente"},
    {"type": "paragraph", "text": ")"},
    {"type": "paragraph", "text": "Olhando por uma pequena fenda da cortina a estátua da Santíssima Virgem defronte dela."},
    {"type": "paragraph", "text": "Ora! ela me vigia!"},
  ]),
  makeChapter(7, "detalhe-da-estatua", "A Virgem do Sorriso", "Uma nota sobre a imagem venerada por Teresa", [
    {"type": "paragraph", "text": "detalhe da estátua original da Virgem do Sorriso"},
    {"type": "paragraph", "text": "Gosto muito de flores, rosas, flores vermelhas e as belas margaridas cor-de-rosa."},
    {"type": "paragraph", "text": "Quando ela tossia e fazia o menor movimento em sua cama, os ramos de miosótis se mexiam ao redor de suas imagens."},
    {"type": "paragraph", "text": "As pequenas flores tremem comigo, isso me agrada."},
    {"type": "paragraph", "text": "... Minha boa Santíssima Virgem, é isso que me dá vontade de ir embora: Eu canso demais minhas pequenas irmãs, e ainda lhes faço pena por estar tão doente... Sim, eu gostaria de ir embora!"},
    {"type": "heading", "text": "Depois das Matinas :"},
    {"type": "paragraph", "text": "Ó minha boa Santíssima Virgem, tende piedade de mim... « desta vez ! »"},
    {"type": "heading", "text": "29 de agosto"},
    {"type": "paragraph", "text": "Eu lhe lia o Evangelho de domingo : a parábola do Samaritano."},
    {"type": "paragraph", "text": "... Sou como esse pobre viajante « semivivo », meio morta, meio viva."},
    {"type": "paragraph", "text": "É realmente duro sofrer sem nenhuma consolação interior."},
    {"type": "paragraph", "text": "Sim, mas é um sofrimento sem inquietação. Estou contente de sofrer já que o bom Deus o quer."},
    {"type": "paragraph", "text": "Minha pequena Mãe ?"},
    {"type": "paragraph", "text": "Ela me chamava"},
    {"type": "paragraph", "text": ")"},
    {"type": "paragraph", "text": "O que a senhora quer ?"},
    {"type": "paragraph", "text": "Acabei de contar 9 peras na pereira perto da janela. Deve haver muitas outras. Fico contente, a senhora as comerá. Frutas são tão boas!"},
    {"type": "paragraph", "text": "Ela nos deu esta noite um beijinho."},
    {"type": "heading", "text": "30 de agosto"},
    {"type": "paragraph", "text": "Ela passou a noite muito pacificamente como na noite de 6 de agosto ; muito feliz de pensar que talvez ela fosse morrer."},
    {"type": "paragraph", "text": "... Juntava as mãos muito docilmente esperando a morte."},
    {"type": "paragraph", "text": "A senhora ficaria contente se lhe anunciassem que morrerá com certeza em alguns dias no máximo ? A senhora preferiria isso mesmo do que ser avisada de que sofrerá cada vez mais durante meses e anos ?"},
    {"type": "paragraph", "text": "Oh ! não, eu não ficaria nem um pouco mais contente. O que me contenta unicamente é fazer a vontade do bom Deus."},
    {"type": "paragraph", "text": "A colocaram na cama dobrável e a rolavam até a porta do coro que dá para baixo do claustro. A deixaram ali sozinha bastante tempo. Ela rezava com um olhar tão profundo em direção à grade. Depois ela lançou pétalas de rosa ali."},
    {"type": "paragraph", "text": "A fotografaram antes de voltar."},
    {"type": "meta", "text": "foto 45 ACL"},
    {"type": "paragraph", "text": "O doutor La Néele veio e lhe disse : « Está para breve, minha pequena irmã, tenho certeza. » Então ela o olhou com um sorriso de felicidade."},
    {"type": "paragraph", "text": "O sr. Youf também veio e lhe disse estas palavras que ela me contou :"},
    {"type": "paragraph", "text": "« A senhora sofreu mais do que sofrerá agora. »... Nós terminamos juntos nosso ministério, você como carmelita, eu como sacerdote. »"},
    {"type": "heading", "text": "31 de agosto"},
    {"type": "paragraph", "text": "Nova visita do Dr La Néele."},
    {"type": "paragraph", "text": "["},
    {"type": "paragraph", "text": "No dia seguinte, 31 de agosto, nova visita de Francis, apesar de uma pequena altercação na véspera com Marie de Gonzague, que no fundo teria preferido o velho de Cornière, mais próximo dela do que Francis em nível geracional. Francis tivera sido ríspido com ela, como explicou à Sra. Guérin: « Tenho certeza de que elas não cumprem todas as minhas prescrições. » Marie de Gonzague chorou, enviou-lhe a última foto de Teresa como se para se desculpar. Francis voltará a ver Teresa uma última vez em 5 de setembro. /…"},
    {"type": "meta", "text": "ACL"},
    {"type": "paragraph", "text": "]"},
    {"type": "paragraph", "text": "Se a senhora morresse amanhã, não teria um pouco de medo, seria tão perto !"},
    {"type": "paragraph", "text": "Ah ! mesmo esta noite, eu não teria nenhum medo, teria apenas alegria."},
    {"type": "paragraph", "text": "Que coragem me é necessária para fazer um sinal da cruz !"},
    {"type": "paragraph", "text": "... Ah ! minhas pequenas irmãs ! Ah ! meu Deus ! meu Deus ! ... Meu Deus, tende piedade de mim !... Não tenho mais nada a dizer além disso."},
    {"type": "paragraph", "text": "Em breve esse leito onde vos vemos estará vazio, que dor para nós !"},
    {"type": "paragraph", "text": "Ah ! no seu lugar, como eu estaria contente !"},
    {"type": "paragraph", "text": "... Tenho apetite para toda a vida. Sempre comi como uma mártir, e agora devoraria tudo. Parece-me que morro de fome."},
    {"type": "paragraph", "text": "... Quanto Santa Verônica deve ter sofrido !"},
    {"type": "paragraph", "text": "( Ela havia lido que essa santa morreu de fome. )"},
    {"type": "paragraph", "text": "Uma de nós dizia : « Como ela está oprimida ! Ela poderia muito bem morrer hoje. »"},
    {"type": "paragraph", "text": "Que felicidade !"},
    {"type": "paragraph", "text": "À tarde - Disseram-me que ela dormia ; ela abriu os olhos e me disse :"},
    {"type": "paragraph", "text": "Mas não, aproximem-se, me dá tanto prazer ver vocês !"},
    {"type": "paragraph", "text": "Como preciso ver as maravilhas do Céu ! nada me toca na terra."},
    {"type": "paragraph", "text": "Durante as Matinas."},
    {"type": "paragraph", "text": "Ah ! é incrível como todas as minhas esperanças se realizaram. Quando eu lia São João da Cruz, eu suplicava ao bom Deus que operasse em mim o que ele diz, isto é, a mesma coisa como se eu vivesse muito idosa ; enfim que me consumisse rapidamente no amor, e fui atendida !"},
    {"type": "paragraph", "text": "Depois de olhar longamente a estátua da Santa Virgem :"},
    {"type": "paragraph", "text": "... Quem teria podido inventar a Santa Virgem ?"},
    {"type": "heading", "text": "A mim :"},
    {"type": "paragraph", "text": "... Ah ! se a Senhora me ama, que eu a ame também !"},
    {"type": "paragraph", "text": "Ela me contou que antigamente, para se mortificar, ela pensava em coisas sujas enquanto comia."},
    {"type": "paragraph", "text": "... Mas depois, achei mais simples oferecer ao bom Deus o que me agradava."},
    {"type": "paragraph", "text": "... Outro dia quis fazer um verdadeiro jantar, então peguei um grão de uva e depois um pequeno gole de vinho que ofereci à Santa Virgem. Em seguida fiz a mesma coisa pelo Menino Jesus, e meu pequeno jantar terminou."},
  ]),
  makeChapter(8, "2-de-setembro-de-1897", "2 de setembro de 1897", "Os últimos dias no Carmelo", [
    {"type": "heading", "text": "2 de setembro de 1897"},
    {"type": "paragraph", "text": "Você morrerá, claro, um dia de festa."},
    {"type": "paragraph", "text": "Será uma festa bem bonita! Eu nunca tive vontade de morrer num dia de festa."},
    {"type": "paragraph", "text": "... Talvez fazia dois anos que eu estava aqui quando o bom Deus fez cessar minha provação em relação a Irmã Maria dos Anjos, e eu pude abrir-lhe minha alma... No fim ela me consolava verdadeiramente."},
    {"type": "paragraph", "text": "... Custava-me muito pedir mortificações no refeitório, porque eu era tímida, eu corava, mas nelas fui bem fiel, duas vezes por semana. Quando essa provação de timidez passou, eu prestava menos atenção e devo ter esquecido mais de uma vez minhas duas mortificações."},
    {"type": "paragraph", "text": "Dizíamos a ela que ela era a chefe do grupo, que havia vencido todos os inimigos, e que não havia mais senão segui-la. Ela então fez o gesto bem conhecido para nós de pôr as mãos uma sobre a outra a uma pequeníssima distância, dizendo:"},
    {"type": "paragraph", "text": "«Alta assim na família!»"},
    {"type": "paragraph", "text": "Depois, fazendo de conta que semeava alguma coisa:"},
    {"type": "paragraph", "text": "Joãozinho!"},
    {"type": "heading", "text": "A Irmã Geneviève lhe disse:"},
    {"type": "paragraph", "text": "«Quando se pensa que ainda se espera tanta coisa de você em Saigon!»"},
    {"type": "paragraph", "text": "Irei, irei em breve; se vocês soubessem como eu darei logo minha volta!"},
    {"type": "paragraph", "text": "... Quando se aceita o aborrecimento de ter sido má, o bom Deus volta logo."},
    {"type": "paragraph", "text": "Ofereci sobretudo minha provação interior contra a fé por um membro aliado de nossa família que não tem fé."},
    {"type": "paragraph", "text": "(Sr. Tostain)"},
    {"type": "paragraph", "text": "... Oh! sim, eu desejo o Céu! «Rasgue o pano desse doce encontro», ó meu Deus!"},
    {"type": "heading", "text": "3 de setembro"},
    {"type": "paragraph", "text": "Eu lhe contava o que me haviam dito sobre as honras prestadas ao Czar da Rússia na França."},
    {"type": "paragraph", "text": "Ah! isso não me cega nada! Falem-me do bom Deus, do exemplo dos Santos, de tudo o que é verdade..."},
    {"type": "paragraph", "text": "Quando se pensa que cuidamos de uma pequena santa!"},
    {"type": "paragraph", "text": "Pois bem, que bom! mas eu gostaria que o bom Deus o dissesse."},
    {"type": "paragraph", "text": "A pobre Madre C. de J. estava cada vez mais exigente e as enfermeiras se queixavam de ter que ceder às suas manias."},
    {"type": "paragraph", "text": "... Ah! como eu teria atração por tudo isso!"},
    {"type": "heading", "text": "4 de setembro"},
    {"type": "paragraph", "text": "... Foi assim que tomei o bom Deus e é por isso que serei tão bem recebida por ele na hora da minha morte."},
    {"type": "paragraph", "text": "Fico muito contente que a carne me repugne, porque ao menos nela não encontro prazer."},
    {"type": "paragraph", "text": "(Davam-lhe um pouco de carne)"},
    {"type": "paragraph", "text": "No momento em que eu saía da enfermaria para o refeitório:"},
    {"type": "paragraph", "text": "Eu a amo!"},
    {"type": "paragraph", "text": "Tocavam o Angelus."},
    {"type": "paragraph", "text": "Será que devo desencapuzar minhas mãozinhas?"},
    {"type": "paragraph", "text": "Não, você está até fraca demais para dizer o Angelus. Chame apenas a Santa Virgem dizendo: “Virgem Maria!” Ela retomou:"},
    {"type": "paragraph", "text": "Virgem Maria, eu vos amo de todo o meu coração."},
    {"type": "paragraph", "text": "A Irmã Geneviève lhe disse: «Diga que a ama, por mim também.» Então ela acrescentou bem baixo:"},
    {"type": "paragraph", "text": "por “Srta. Lili”, por Mamãe, por Madrinha, por Léonie, a pequena Maria, meu Tio, minha tia, Jeanne, Francis, “Maurice”, “o pequeno Roulland” e todos os que eu amo."},
    {"type": "paragraph", "text": "Ela tivera vontade de um certo prato, muito simples aliás, e uma de nós o fez saber ao meu Tio."},
    {"type": "paragraph", "text": "... É bem engraçado que se faça saber isso no mundo! Enfim eu o ofereci ao bom Deus."},
    {"type": "paragraph", "text": "Eu lhe disse que não fora culpa minha, porque de fato eu o defendi. Ela retomou pegando o pratinho:"},
    {"type": "paragraph", "text": "Ah! está oferecido ao bom Deus. Isso já não me importa. Que pensem o que quiserem!"},
    {"type": "heading", "text": "Durante as Matinas:"},
    {"type": "paragraph", "text": "Minha pequena Madre, oh! como eu a amo!"},
    {"type": "paragraph", "text": "Com um lindo sorriso, fazendo esforço para falar:"},
    {"type": "paragraph", "text": "Vamos dizer qualquer coisa, vamos dizer..."},
    {"type": "paragraph", "text": "... Se vocês soubessem como o pensamento de ir logo ao Céu me deixa calma. Contudo estou bem feliz, mas não posso dizer que sinto uma alegria viva e arroubos de júbilo, não!"},
    {"type": "paragraph", "text": "Vocês gostam mais assim de morrer do que de viver?"},
    {"type": "paragraph", "text": "Ó minha pequena Madre, eu não prefiro uma coisa à outra, não poderei dizer como Nossa Mãe Santa Teresa: «Morro por não morrer.» O que o bom Deus prefere e escolhe para mim, isso é o que mais me agrada."},
    {"type": "heading", "text": "5 de setembro"},
    {"type": "paragraph", "text": "Você, então, não tem tristeza por deixar “mamãe”?"},
    {"type": "paragraph", "text": "(com um arzinho infantiloide:)"},
    {"type": "paragraph", "text": "Não!... Se não houvesse vida eterna, oh! sim!... mas talvez haja... e mesmo é certo!"},
    {"type": "paragraph", "text": "Se lhe dissessem que vai morrer subitamente, neste exato instante, teria algum receio?"},
    {"type": "paragraph", "text": "... Ah! que felicidade! Eu gostaria de ir!"},
    {"type": "paragraph", "text": "Então você prefere morrer a viver?"},
    {"type": "paragraph", "text": "Não, de modo nenhum. Se eu curasse, os médicos me olhariam espantados e eu lhes diria: “Senhores, estou muito contente de estar curada para servir ainda o bom Deus na terra, pois é sua vontade. Sofri como se devesse morrer; bem, eu recomeçaria outra vez!”"},
    {"type": "paragraph", "text": "Apontando com o dedo seu copo de água tingida, com um arzinho gaiato tão gentil:"},
    {"type": "paragraph", "text": "Para beber, minha pequena Madre, por favor. Tem gelo dentro, é bom!"},
    {"type": "heading", "text": "Depois de beber:"},
    {"type": "paragraph", "text": "Bebi sem sede! Sou uma pequena “bebe sem sede”."},
    {"type": "paragraph", "text": "Eu lhe dizia que ela tivera menos sofrimento durante o silêncio:"},
    {"type": "paragraph", "text": "Oh! tanto quanto antes! muito, muito sofri! Mas foi à Santa Virgem que me queixei."},
    {"type": "paragraph", "text": "Visita do doutor La Néele que, depois de lhe ter afirmado na consulta anterior que ela estava à morte, que poderia até morrer de repente virando-se na cama, lhe disse:"},
    {"type": "paragraph", "text": "“Você é como um navio que não avança nem recua.”"},
    {"type": "paragraph", "text": "Ela ficou primeiro atônita."},
    {"type": "paragraph", "text": "Você ouviu, me disse ela, vê como isso muda! Mas eu não quero mudar, quero continuar a me abandonar ao bom Deus inteiramente."},
    {"type": "heading", "text": "6 de setembro"},
    {"type": "paragraph", "text": "... Diga-me algumas palavrinhas doces, depois do que me aconteceu ontem."},
    {"type": "paragraph", "text": "Ah! como fazer para consolá-la, minha pobre pequena? Estou bem impotente."},
    {"type": "heading", "text": "... com ar de paz:"},
    {"type": "paragraph", "text": "Não preciso ser consolada..."},
    {"type": "paragraph", "text": "Ela chorou de alegria à tarde"},
    {"type": "paragraph", "text": "quando lhe trouxeram uma relíquia do Venerável Théophane Vénard."},
    {"type": "paragraph", "text": "Ela me ofereceu com muita ternura uma pequena margaridinha pelo meu aniversário."},
    {"type": "paragraph", "text": "A tarde inteira ela se mostrou para nós muito afetuosa, e encantadora de todos os modos. Eu lhe disse:"},
    {"type": "paragraph", "text": "Percebi que assim que pode, você volta a ser como antes."},
    {"type": "paragraph", "text": "... Ah! é bem verdade! Sim, quando posso faço o meu melhor para ser alegre, para agradar."},
    {"type": "paragraph", "text": "Ela esperava o Sr. Youf para se confessar; ele não pôde vir e isso foi uma verdadeira decepção para ela. Mas logo ela retomou seu belo ar de paz."},
    {"type": "paragraph", "text": "Trouxeram-lhe um pouco de comida: seu estômago melhorara."},
    {"type": "paragraph", "text": "Ai! onde estou eu com minha doença? Ora, agora eu como!"},
    {"type": "heading", "text": "7 de setembro"},
    {"type": "paragraph", "text": "Ela não me dissera uma palavra no dia, e pensei à tarde: Hoje nada terei para escrever."},
    {"type": "heading", "text": "Mas ela me disse quase imediatamente:"},
    {"type": "paragraph", "text": "Ah! não há alma como você..."},
    {"type": "paragraph", "text": "Depois disso, ela começou a derramar grossas lágrimas pelo receio que tinha de me ter magoado numa circunstância que eu nem sequer tinha notado."},
    {"type": "heading", "text": "8 de setembro"},
    {"type": "paragraph", "text": "Um pequeno tordinho veio pular sobre sua cama."},
    {"type": "paragraph", "text": "Léonie lhe enviou a caixa de música"},
    {"type": "paragraph", "text": "que se conservou e as melodias embora profanas são tão doces que ela as ouviu com muito prazer."},
    {"type": "paragraph", "text": "Finalmente lhe trouxeram um ramalhete de flores do campo para festejar o aniversário de sua Profissão. Vendo-se tão agraciada, ela chorou de reconhecimento e nos disse:"},
    {"type": "paragraph", "text": "É por causa das delicadezas do bom Deus para comigo; externamente estou transbordante, e, no entanto, interiormente estou sempre na provação... mas também na paz."},
    {"type": "heading", "text": "9 de setembro"},
    {"type": "paragraph", "text": "A caixa de música fora demais dada à corda, parecia quebrada. Auguste a consertou, mas desde então faltou-lhe (para uma certa melodia) a nota mais bonita. Fiquei triste e perguntei-lhe se ela também o estava."},
    {"type": "paragraph", "text": "Oh! de maneira nenhuma, eu o estou só porque você o está."},
    {"type": "paragraph", "text": "... Ah! eu sei o que é o sofrimento!"},
    {"type": "heading", "text": "10 de setembro"},
    {"type": "paragraph", "text": "Na consulta do Sr. de Cornière, ele pareceu consternado com seu estado."},
    {"type": "paragraph", "text": "Pois bem, você está contente? lhe disse eu depois da saída do doutor."},
    {"type": "paragraph", "text": "Sim, mas já estou um pouco acostumada, dizem e desdizem!"},
    {"type": "paragraph", "text": "Enquanto ajeitavam seus travesseiros à noite, ela apoiou a cabeça em mim, olhando-me com ternura. Isso me fez lembrar o olhar do Menino Jesus para a Santa Virgem quando ele ouve a música do anjo na imagem onde ela disse da Santa Virgem: “É Pauline em ideal.”"},
    {"type": "heading", "text": "11 de setembro"},
    {"type": "paragraph", "text": "É esta pequena mãe que morrerá por último, iremos buscá-la com Théophane Vénard, quando ela tiver acabado de trabalhar por mim..."},
    {"type": "paragraph", "text": "... a não ser que as pequenas almas precisem dela."},
    {"type": "paragraph", "text": "Eu a amo muito, muito!"},
    {"type": "paragraph", "text": "Quando ouço abrir a porta, sempre acho que é você; e quando você não vem, fico toda triste."},
    {"type": "paragraph", "text": "Dê-me um beijo, um beijo que faça barulho; enfim que os lábios façam “pit!”"},
    {"type": "paragraph", "text": "Só no Céu você saberá o que você é para mim... Você é para mim uma lira, um canto... muito mais que uma caixa de música, vá! mesmo quando você nada diz."},
    {"type": "paragraph", "text": "Ela fizera duas coroas de centáureas para a Santa Virgem, uma estava a seus pés, a outra em sua mão. Eu lhe disse:"},
    {"type": "paragraph", "text": "Você pensa sem dúvida que aquela que ela segura é para lhe dar."},
    {"type": "paragraph", "text": "Oh! não, é como ela quiser, o que lhe dou é para o seu prazer."},
    {"type": "paragraph", "text": "... Tenho medo de ter tido medo da morte... Mas não tenho medo do depois, com certeza! E não me arrependo da vida, oh! não. É só ao me dizer: Que é essa separação misteriosa da alma e do corpo? É a primeira vez que experimento isso, mas me abandonei logo ao bom Deus."},
    {"type": "paragraph", "text": "Quer me dar meu Crucifixo para que eu o beije depois do ato de contrição, para ganhar a indulgência plenária em favor das almas do Purgatório. Não lhes dou mais do que isso!"},
    {"type": "paragraph", "text": "Dê-me agora água benta. Chegue-me as relíquias da Madre Anne de Jésus e de Théophane Vénard, quero beijá-las."},
    {"type": "paragraph", "text": "Depois disso ela fez uma pequena carícia à sua imagem da Virgem Mãe; primeiro ao Menino Jesus e depois à Santa Virgem."},
    {"type": "heading", "text": "Ela não podia adormecer e me disse:"},
    {"type": "paragraph", "text": "Conheço isso, é a malícia do demônio; ele está furioso porque eu não esqueci minhas pequenas devoções. Quando, por um motivo ou outro, não as fiz, adormeço e acordo alguns minutos depois da meia-noite. É para zombar de mim, porque perdi a indulgência plenária."},
    {"type": "paragraph", "text": "Será que devo ter medo do demônio? Parece-me que não porque faço tudo por obediência."},
    {"type": "paragraph", "text": "Oh! não, eu não desejo ver o bom Deus na terra. E, no entanto, eu o amo! Amo também muito a Santa Virgem e os Santos e não desejo vê‑los também."},
    {"type": "heading", "text": "12 de setembro"},
    {"type": "paragraph", "text": "Era a festa do Santo Nome de Maria. Ela me pediu para lhe ler o Evangelho do domingo. Eu não tinha o folheto paroquial e disse-lhe simplesmente: É o Evangelho em que Nosso Senhor nos avisa que «ninguém pode servir a dois senhores». Então ela tomou uma vozinha de criança que recita a lição e me o disse de ponta a ponta."},
    {"type": "heading", "text": "13 de setembro"},
    {"type": "paragraph", "text": "Estava bem mais doente e tinha os pés inchados desde o dia anterior. Não se podia fazer o menor movimento à sua volta, como mexer um pouco a cama e sobretudo tocá-la sem fazê-la muito sofrer, tanto ela estava fraca. Não o supúnhamos a esse ponto, e a Irmã Maria do Sagrado Coração, depois de mim, lhe tocara o pulso bastante tempo. Ela não manifestara primeiro nenhum sinal de cansaço para não nos entristecer, mas no fim, não podendo mais, pôs-se a chorar. E quando depois arrumaram seus travesseiros e seu apoio, ela gemia, dizendo num tom tão doce:"},
    {"type": "paragraph", "text": "Oh! eu gostaria... eu gostaria..."},
    {"type": "paragraph", "text": "O quê?"},
    {"type": "paragraph", "text": "De não mais fazer pena às minhas pequenas irmãs, e por isso partir logo."},
    {"type": "paragraph", "text": "Nesse momento, ela olhou para a Irmã Maria do Sagrado Coração e lhe fez um sorriso ravissant; era sobretudo a ela que temia mais ter contristado."},
    {"type": "paragraph", "text": "Como não conseguiam bem dispor seu apoio, porque não ousavam muito remexê-la, ela disse gentilmente apoiando-se nas mãos e tentando fazê-lo ela mesma:"},
    {"type": "paragraph", "text": "Esperem, vou me empurrar para o fundo da cama, fazendo os movimentos de um pequeno saltitar."},
    {"type": "paragraph", "text": "Uma irmã colherá uma violeta no jardim para ela, ela a ofereceu e retirou-se. Então nossa pequena Thérèse me disse olhando a flor:"},
    {"type": "paragraph", "text": "Ah! o perfume das violetas!"},
    {"type": "paragraph", "text": "depois fez-me um sinal como para saber se podia cheirá-la sem mortificação."},
    {"type": "heading", "text": "14 de setembro"},
    {"type": "paragraph", "text": "Trouxeram-lhe uma rosa; ela a despetalou sobre seu Crucifixo com muita piedade e amor, tomando cada pétala e acariciando as chagas de Nosso Senhor."},
    {"type": "paragraph", "text": "Em setembro, disse ela, a pequena Thérèse ainda despetala “a rosa primaveril”"},
    {"type": "paragraph", "text": "Ao despetalar por Ti, a rosa primaveril,"},
    {"type": "paragraph", "text": "Eu queria enxugar tuas lágrimas!"},
    {"type": "paragraph", "text": "Como as pétalas escorriam da sua cama para o chão da enfermaria, ela disse muito seriamente:"},
    {"type": "paragraph", "text": "Recolham bem essas pétalas, minhas pequenas irmãs, elas lhes servirão para dar alegrias mais tarde... não percam nenhuma..."},
    {"type": "paragraph", "text": "... Ah! agora..."},
    {"type": "paragraph", "text": "“Eu tenho a esperança, meu exílio será curto!”"},
    {"type": "paragraph", "text": "O doutor La Néele lhe dissera que ela não teria agonia, e como sofria cada vez mais:"},
    {"type": "paragraph", "text": "... Disseram-me, no entanto, que eu não teria agonia!..."},
    {"type": "paragraph", "text": "... Mas, afinal, eu aceito ter uma."},
    {"type": "paragraph", "text": "Se lhe fizessem escolher entre ter ou não ter?"},
    {"type": "paragraph", "text": "Eu não escolheria nada!"},
    {"type": "heading", "text": "15 de setembro"},
    {"type": "paragraph", "text": "Quando vocês estiverem no Céu, seus grandes sofrimentos de hoje lhes parecerão pouca coisa, vá!"},
    {"type": "paragraph", "text": "Oh! mesmo na terra acho que é bem pouco."},
    {"type": "heading", "text": "À noite, durante a recreação:"},
    {"type": "paragraph", "text": "Quando a Irmã Geneviève disse há pouco à Irmã Marthe, que perguntara notícias minhas: “Ela está bem cansada!” pensei comigo mesma: É bem verdade, é isso mesmo! Sim, sou como um viajante cansado, exausto, que cai ao chegar ao fim de sua viagem."},
    {"type": "paragraph", "text": "... Sim, mas é nos braços do bom Deus que eu caio!"},
    {"type": "paragraph", "text": "Nossa Madre me disse que eu não tinha nada a fazer para me preparar à morte, porque eu já estava preparada antecipadamente."},
    {"type": "heading", "text": "16 de setembro"},
    {"type": "heading", "text": "Só para mim, sobre perguntas que eu lhe fazia:"},
    {"type": "paragraph", "text": "O que nos atrai as luzes e o auxílio do bom Deus para guiar e consolar as almas, é não contar suas penas a si para aliviar-se; aliás, isso não é um verdadeiro alívio, mais excita do que apazigua."},
    {"type": "heading", "text": "17 de setembro"},
    {"type": "heading", "text": "Em redor dos doentes há que ser alegre:"},
    {"type": "paragraph", "text": "(Nós lhe expressávamos nosso pesar)"},
    {"type": "paragraph", "text": "Ora, não há que lamentar-se como pessoas que não têm esperança."},
    {"type": "heading", "text": "Com um ar um pouco malicioso:"},
    {"type": "paragraph", "text": "Vocês acabarão por me fazer sentir saudade da vida."},
    {"type": "paragraph", "text": "Oh! teríamos bem dificuldade!"},
    {"type": "paragraph", "text": "É verdade! Eu disse isso para assustar vocês."},
    {"type": "paragraph", "text": "Falando-me de sua infância ela contou que um dia lhe deram um cestinho e que ela exclamou em sua alegria:"},
    {"type": "paragraph", "text": "Agora não desejo mais nada na terra!"},
    {"type": "heading", "text": "Depois se retificou para dizer logo:"},
    {"type": "paragraph", "text": "Se, desejo ainda uma coisa, é o Céu!"},
    {"type": "heading", "text": "18 de setembro"},
    {"type": "paragraph", "text": "Eu lhe dizia que tinha medo de cansá-la ao falar:"},
    {"type": "paragraph", "text": "Minha pequena Madre, sua conversa é tão agradável para mim! Oh! não, ela não me cansa. É como uma música para mim... Não há duas como você na terra. Oh! como eu a amo!"},
    {"type": "paragraph", "text": "Olhando pela janela a hera toda vermelha sobre o eremitério da Santa Face:"},
    {"type": "paragraph", "text": "A Santa Face está em toda a sua esplendor. Vejam, há ramos de hera até acima dos castanheiros."},
    {"type": "paragraph", "text": "Estou melhor esta tarde."},
    {"type": "paragraph", "text": "De fato, ela se interessava por tudo. Olhava com prazer a toalha que a Irmã Geneviève fazia para o altar do Oratório, depois o ornamento do Sr. Abade Denis."},
    {"type": "paragraph", "text": "Mas de manhã, quando a Irmã Aimée de Jésus a tomou nos braços para ajeitar um pouco sua cama, achei que ela ia morrer."},
    {"type": "heading", "text": "19 de setembro"},
    {"type": "paragraph", "text": "Trouxeram de fora um buquê de dálias. Ela as mirou com prazer e enfiou os dedos em suas pétalas de um jeito tão gentil!"},
    {"type": "paragraph", "text": "Depois da primeira Missa do Sr. Abade Denis, pediu ver seu cálice. Como olhava longamente o fundo da Taça, lhe disseram: Por que olha tão atentamente o fundo do Cálice?"},
    {"type": "paragraph", "text": "Porque me reflito ali. Na sacristia eu gostava de fazer isso. Eu me alegrava em dizer: Meus traços se refletiram onde o sangue de Jesus repousou e repousará de novo."},
    {"type": "paragraph", "text": "Quantas vezes pensei também que, em Roma, meu rosto se reproduzira nos olhos do Santo Padre."},
    {"type": "heading", "text": "20 de setembro"},
    {"type": "paragraph", "text": "Visita do doutor de Cornière que nos disse que ela deve sofrer um verdadeiro martírio. Ao sair exclamava sobre sua heroica paciência. Eu lhe repeti alguma coisa disso."},
    {"type": "paragraph", "text": "Como pode dizer que eu sou paciente! Mas é mentira! Não paro de gemer, suspiro, grito o tempo todo: Oh! la la! e depois: Meu Deus, não aguento mais! Tende piedade, tende piedade de mim!"},
    {"type": "paragraph", "text": "À tarde, trocaram-lhe a túnica e ficamos impressionadas com sua magreza, pois o rosto permaneceu o mesmo. Fui pedir à Nossa Madre que viesse ver suas costas. Ela demorou muito e admirei o ar tão doce e paciente de nossa pobre pequena doente esperando-a. Nossa Madre ficou surpresamente comovida e disse com bondade: Que é que é uma menina tão magra?"},
    {"type": "paragraph", "text": "Uma"},
    {"type": "paragraph", "text": "que"},
    {"type": "paragraph", "text": "lette!"},
    {"type": "heading", "text": "21 de setembro"},
    {"type": "paragraph", "text": "Tinha ido, sem dizer nada, esvaziar seu cuspidor e o pus perto dela, pensando comigo: Ficaria contente se ela me dissesse que no Céu me o devolveria! E logo, virando-se para mim ela disse:"},
    {"type": "paragraph", "text": "No Céu, eu lhe devolvo isso."},
    {"type": "paragraph", "text": "Quando penso que ela vai morrer, disse a Irmã Geneviève."},
    {"type": "paragraph", "text": "Ah! pois sim! de repente, eu acredito nisso!"},
    {"type": "paragraph", "text": "Dizer que ela não tem uma pequena Thérèse a amar!"},
    {"type": "paragraph", "text": "... Ele me chama de sua pequena Thérèse!"},
    {"type": "paragraph", "text": "Quem?"},
    {"type": "paragraph", "text": "Mas o Padre Bellière!"},
    {"type": "paragraph", "text": "Ele havia escrito e eu quis lhe reler sua carta, acreditando agradá-la ao encontrar essa palavra, mas ela estava cansada demais e me disse:"},
    {"type": "paragraph", "text": "Oh! não, já basta! estou “espertada” da pequena Thérèse!"},
    {"type": "paragraph", "text": "Depois, virando-se para mim com um pequeno gesto carinhoso:"},
    {"type": "paragraph", "text": "Não “espertada” da pequena Pauline também! Oh! não!"},
    {"type": "paragraph", "text": "Vou lavar a louça, tenho duas voltas para fazer."},
    {"type": "paragraph", "text": "Bem duro para mim, oh! sim!"},
    {"type": "paragraph", "text": "A Irmã Geneviève me pediu um lápis, eu também precisava, mas emprestei o nosso mesmo assim. Ela disse então com um tomzinho nítido:"},
    {"type": "paragraph", "text": "Que gentil."},
    {"type": "paragraph", "text": "Ah! o que é a agonia? Parece-me que estou nela o tempo todo! !.."},
    {"type": "paragraph", "text": "Ao enxugar-se os olhos, alguns cílios se soltaram de suas pálpebras:"},
    {"type": "paragraph", "text": "Tomem esses cílios, minha pequena Ir. Geneviève, é preciso dar o mínimo possível à terra."},
    {"type": "paragraph", "text": "Então, fazendo um trocadilho com o nome do Padre Alaterre"},
    {"type": "paragraph", "text": "(um operário)"},
    {"type": "paragraph", "text": ", irmão da Ir. São Vicente de Paulo."},
    {"type": "paragraph", "text": "Pobre coitado, porém, se isso lhe dá prazer!"},
    {"type": "heading", "text": "22 de setembro"},
    {"type": "paragraph", "text": "Depois de lhe haver recordado várias circunstâncias de sua vida religiosa em que fora muito humilhada, acrescentei: Oh! quantas vezes tive piedade de você!"},
    {"type": "paragraph", "text": "Não deveria, eu vos asseguro, ter tido tanta piedade de mim. Se soubessem como eu sobressaía acima de tudo isso! Eu me fortalecia das humilhações; não havia mais valente que eu no fogo."},
    {"type": "paragraph", "text": "Ela queria falar-me e não podia."},
    {"type": "paragraph", "text": "... Ah! como é duro estar numa tal impotência!"},
    {"type": "paragraph", "text": "... Com vocês! Era tão doce quando eu podia falar com vocês! Isso é o que é o mais duro."},
    {"type": "paragraph", "text": "Eu dizia olhando a imagem de Théophane Vénard: Ele está ali com seu chapéu baixo, e para terminar, não vem buscá-la!"},
    {"type": "heading", "text": "Sorrindo:"},
    {"type": "paragraph", "text": "Oh! eu não me risco a zombar dos santos... Eu os amo bem... Eles querem ver..."},
    {"type": "paragraph", "text": "O quê? Se vai perder a paciência?"},
    {"type": "heading", "text": "Com um ar malicioso e profundo ao mesmo tempo:"},
    {"type": "paragraph", "text": "Sim!... sobretudo se for perder a confiança... até onde vou levar minha confiança..."},
    {"type": "paragraph", "text": "Ela chamara a Irmã Geneviève de sua “bobonne”, a Irmã Maria da Trindade sua “boneca” porque a encontrava com rosto de boneca. Era para nos divertir e nunca por dissipação ou infantilidade. Mas abusaram dessas alcunhas e ela disse:"},
    {"type": "paragraph", "text": "Não se deve chamar uns aos outros de todos os nomes. Mesmo assim isso não é religioso!"},
    {"type": "paragraph", "text": "O tempo deve parecer-lhes bem longo?"},
    {"type": "paragraph", "text": "Não, o tempo não me parece longo; parece-me que foi ontem que eu seguia a Comunidade, que escrevia o caderno. (sua vida)"},
    {"type": "paragraph", "text": "Que doença terrível e quanto você sofreu!"},
    {"type": "paragraph", "text": "Sim! !! que graça ter fé! Se eu não tivesse tido fé, teria tirado a própria vida sem hesitar um só instante…"},
    {"type": "heading", "text": "23 de setembro"},
    {"type": "paragraph", "text": "... Oh! tudo que devo a vocês!... Também eu as amo!... mas não quero mais falar nisso, porque choraria..."},
    {"type": "paragraph", "text": "(Isso lhe fazia muito mal chorar)"},
    {"type": "paragraph", "text": "Amanhã será o aniversário da sua Tomada do Véu, e sem dúvida o dia da sua morte."},
    {"type": "paragraph", "text": "Eu não sei quando, estou sempre à espera, mas sei bem que não pode demorar."},
    {"type": "paragraph", "text": "Ela nos sorria frequentemente, a uma ou a outra, mas nem sempre nos dávamos conta."},
    {"type": "paragraph", "text": "... Muitas vezes fiz belos sorrisos perdidos para a “Bobonne” e para outras..."},
    {"type": "paragraph", "text": "À noite ouviu-se como um gorjear de pássaro na janela fechada. Perguntávamos o que poderia ser. Uma dizia: É uma rolinha. Outra: É talvez uma ave de rapina."},
    {"type": "paragraph", "text": "Ora, se é uma ave de rapina, que se dane! As aves de rapina vinham bem jantar os mártires."},
    {"type": "paragraph", "text": "A propósito de uma confidência de pouca importância que uma irmã lhe fizera pedindo segredo:"},
    {"type": "paragraph", "text": "... Se as irmãs defendem, é sagrado... Mesmo que fosse pela menor coisa, não se deveria dizer."},
    {"type": "paragraph", "text": "Depois de um longo silêncio, olhando para a Irmã Maria do Sagrado Coração e para mim que estávamos sozinhas naquele momento junto dela:"},
    {"type": "paragraph", "text": "Minhas pequenas irmãs, foram vocês que me criaram!..."},
    {"type": "paragraph", "text": "e seus olhos se encheram de lágrimas."},
    {"type": "heading", "text": "24 de setembro"},
    {"type": "paragraph", "text": "Para o aniversário de sua Tomada do Véu mandei dizer a Missa por ela."},
    {"type": "paragraph", "text": "Obrigado pela Missa!"},
    {"type": "paragraph", "text": "Como a via tanto sofrer, respondi com tristeza: Ah! vê, não estás mais aliviada!"},
    {"type": "paragraph", "text": "É pois para meu alívio que obtiveram dizer a Missa?"},
    {"type": "paragraph", "text": "É para o seu bem."},
    {"type": "paragraph", "text": "Meu bem é sem dúvida sofrer..."},
    {"type": "paragraph", "text": "Ela me contou uma pena que tivera antigamente, quando, bem tarde naquele ano, foram podados os castanheiros."},
    {"type": "paragraph", "text": "Primeiro foi uma amargura e grandes combates ao mesmo tempo. Eu amava tanto as sombras! e não haveria nenhuma naquele ano. Os ramos já verdes estavam em feixes no chão, nada além de troncos! Depois, de repente, me coloquei acima dizendo: Se eu estivesse em outro Carmelo, que me importaria que cortassem, mesmo inteiramente, os castanheiros do Carmelo de Lisieux! E experimentei uma grande paz e uma alegria celestial."},
    {"type": "paragraph", "text": "Visita do Sr. de Cornière, cada vez mais edificado. Disse à Nossa Madre: “É um anjo! Ela tem um rosto de anjo, seu rosto não está alterado, apesar de seus grandes sofrimentos. Nunca vi isso. Com seu estado de emagrecimento geral, é sobrenatural.”"},
    {"type": "paragraph", "text": "... Eu gostaria de correr pelos prados do Céu..."},
    {"type": "paragraph", "text": "... Eu gostaria de correr por prados onde a relva não se pisaria, onde haveria belas flores que não murchariam e lindos menininhos que seriam pequenos anjos."},
    {"type": "paragraph", "text": "Você nunca parece cansada de sofrer. No fundo, você está?"},
    {"type": "paragraph", "text": "Mas não! quando não posso mais, não posso mais, e pronto!"},
    {"type": "paragraph", "text": "Eu tive vontade de dizer ao Sr. de Cornière: Rio porque você de todo modo não pôde me impedir de ir ao Céu; mas, para seu pesar, quando eu lá estiver impedirei você de ir tão cedo."},
    {"type": "paragraph", "text": "Em breve não falarei senão a linguagem dos anjos."},
    {"type": "paragraph", "text": "Você irá ao Céu entre os Serafins."},
    {"type": "paragraph", "text": "Ah! mas, se eu for entre os Serafins, não farei como eles, azar! Todos se cobrem com suas asas diante do bom Deus; eu me guardarei bem de correr com minhas asas."},
    {"type": "paragraph", "text": "... Meu Deus!... tende piedade da pequenina fi... fi... filha!"},
    {"type": "paragraph", "text": "(Voltando-se com muita dor.)"},
    {"type": "paragraph", "text": "Como ela acaricia seu “Théophane” ele é bem honrado!"},
    {"type": "paragraph", "text": "Não são homenagens..."},
    {"type": "paragraph", "text": "O que é então?"},
    {"type": "paragraph", "text": "São carícias, afinal!"},
    {"type": "paragraph", "text": "...Vocês então não têm intuição do dia da sua morte?"},
    {"type": "paragraph", "text": "Ah! minha Madre, intuições! Se soubessem em que pobreza estou! Não sei nada além do que vocês sabem; não adivinho nada a não ser pelo que vejo e sinto. Mas minha alma, apesar de suas trevas, está numa paz espantosa."},
    {"type": "paragraph", "text": "Quem é que mais a ama na terra?..."},
    {"type": "heading", "text": "25 de setembro"},
    {"type": "paragraph", "text": "Eu lhe contara o que se dissera na recreação, a respeito do Sr. Youf que temia muito a morte. As irmãs conversaram sobre a responsabilidade daqueles que têm carga de almas e que viveram muito tempo."},
    {"type": "paragraph", "text": "... Para os pequenos, serão julgados com extrema mansidão. E pode-se bem permanecer pequeno, mesmo nas funções mais assustadoras, mesmo vivendo muito tempo. Se eu tivesse morrido aos 80 anos, que eu teria ido à China, em toda parte, eu teria morrido, sinto bem, tão pequena quanto hoje. E está escrito que “no fim, o Senhor se levantará para salvar todos os mansos e humildes da terra”. Não diz julgar, mas salvar."},
    {"type": "paragraph", "text": "Ela me dissera, um destes últimos dias, terríveis sofrimentos:"},
    {"type": "paragraph", "text": "Ó minha Madre, é bem fácil escrever belas coisas sobre o sofrimento, mas escrever não é nada, nada! É preciso estar nele para saber!..."},
    {"type": "paragraph", "text": "Guardei dessa palavra uma impressão dolorosa, quando, nesse dia, parecendo lembrar o que me dissera, olhou-me de maneira toda particular e como solene, e pronunciou estas palavras:"},
    {"type": "paragraph", "text": "Sinto bem agora que o que disse e escrevi é verdadeiro por inteiro... É verdade que queria muito sofrer pelo bom Deus, e é verdade que ainda o desejo."},
    {"type": "paragraph", "text": "Diziam-lhe: Ah! é horrível o que sofre!"},
    {"type": "paragraph", "text": "Não, não é horrível. Uma pequena vítima de amor não pode achar horrível o que seu Esposo lhe envia por amor."},
    {"type": "heading", "text": "26 de setembro"},
    {"type": "paragraph", "text": "Ela não tinha mais nenhuma força."},
    {"type": "paragraph", "text": "Oh! como estou abatida!..."},
    {"type": "paragraph", "text": "Olhando pela janela uma folha morta destacada da árvore e sustentada no ar por um fio leve:"},
    {"type": "paragraph", "text": "Vejam, é minha imagem, minha vida não se mantém senão por um fio leve."},
    {"type": "paragraph", "text": "Depois de sua morte, à noite de 30 de setembro, a folha que até então se balançava ao sabor do vento, caiu ao chão, eu a recolhi com seu fio de aranha que ainda lhe aderira."},
    {"type": "heading", "text": "27 de setembro"},
    {"type": "paragraph", "text": "Entre duas e três horas, oferecíamos-lhe bebida. Ela pediu água de Lourdes dizendo:"},
    {"type": "paragraph", "text": "Até às 3 horas, prefiro a água de Lourdes, é mais piedosa."},
    {"type": "heading", "text": "28 de setembro"},
    {"type": "paragraph", "text": "... Mamãe!... o ar da terra me falta, quando o bom Deus me dará o ar do Céu?..."},
    {"type": "paragraph", "text": "... Ah! nunca foi tão curto! (Sua respiração)"},
    {"type": "paragraph", "text": "Minha pobre pequena, você é como os mártires no anfiteatro; não podemos mais nada por você!"},
    {"type": "paragraph", "text": "Oh! sim, só de ver vocês isso já me faz bem."},
    {"type": "paragraph", "text": "A tarde inteira ela nos prodigalizou seus sorrisos."},
    {"type": "paragraph", "text": "Ela me ouviu com atenção quando lhe li estas passagens do Ofício de S. Miguel:"},
    {"type": "paragraph", "text": "“O Arcanjo Miguel veio com uma multidão de anjos. É a ele que Deus confiou as almas dos Santos, para que as conduza às alegrias do Paraíso.”"},
    {"type": "paragraph", "text": "“Arcanjo Miguel, eu te constituí príncipe sobre todas as almas que devem ser recebidas.”"},
    {"type": "paragraph", "text": "Ela fez-me sinal com a mão estendida para mim, depois posta no coração, que eu estava ali, em seu coração."},
    {"type": "heading", "text": "29 de setembro"},
    {"type": "paragraph", "text": "Desde de manhã, parecia em agonia; tinha um rosnado muito penoso e não podia respirar. A comunidade foi chamada e se reuniu ao redor de sua cama para recitar as orações do Manual. Depois de cerca de uma hora, Nossa Madre dispensou as irmãs."},
    {"type": "heading", "text": "Ao meio-dia, disse a Nossa Madre:"},
    {"type": "paragraph", "text": "Minha Madre, é a agonia?... Como é que se faz para morrer? Nunca saberei morrer!..."},
    {"type": "paragraph", "text": "Eu lhe li ainda várias passagens do Ofício de S. Miguel e as orações dos agonizantes em francês. Quando se falou dos demônios, ela fez um gesto infantil como para ameaçá‑los e exclamou sorrindo:"},
    {"type": "paragraph", "text": "Oh! Oh!"},
    {"type": "paragraph", "text": "num tom que queria dizer: Não tenho medo deles."},
    {"type": "heading", "text": "Depois da visita do doutor, disse a Nossa Madre:"},
    {"type": "paragraph", "text": "É hoje, minha Madre?"},
    {"type": "paragraph", "text": "Sim, minha filha."},
    {"type": "heading", "text": "Uma de nós disse então:"},
    {"type": "paragraph", "text": "O bom Deus está bem alegre hoje."},
    {"type": "paragraph", "text": "Eu também!"},
    {"type": "paragraph", "text": "Se eu morresse logo que felicidade!"},
    {"type": "paragraph", "text": "... Quando é que vou ficar completamente sufocada!... Não suporto mais! Ah! rezem por mim!... Jesus! Maria!"},
    {"type": "paragraph", "text": "Sim! Quero, quero bem..."},
    {"type": "paragraph", "text": "A Ir. Maria da Trindade tinha vindo, ela dissera a ela depois de alguns instantes, e muito gentilmente, que se retirasse. Quando ela saiu eu disse: Pobre pequena! ela a amava tanto!"},
    {"type": "paragraph", "text": "Fui má em mandá-la embora?"},
    {"type": "paragraph", "text": "E seu rosto tomou uma expressão de tristeza, mas eu a tranquilizei logo."},
    {"type": "paragraph", "text": "(18h.)"},
    {"type": "paragraph", "text": "Uma espécie de inseto se introduzira em sua manga, a importunavam para o tirar:"},
    {"type": "paragraph", "text": "Deixem, não faz nada."},
    {"type": "paragraph", "text": "Mas sim, você vai ser picada."},
    {"type": "paragraph", "text": "Não, deixem, deixem, eu lhes digo que conheço esses bichinhos."},
    {"type": "paragraph", "text": "Eu tinha uma forte dor de cabeça e fechava os olhos apesar de mim ao velá‑la."},
    {"type": "paragraph", "text": "Façam dodo... e eu também!"},
    {"type": "heading", "text": "Mas ela não podia dormir e me disse:"},
    {"type": "paragraph", "text": "Oh minha Madre, como os nervos doem!"},
    {"type": "paragraph", "text": "Durante a recreação da noite."},
    {"type": "paragraph", "text": "... Ah! se soubessem!"},
    {"type": "paragraph", "text": "(Se soubessem o que sofro)"},
    {"type": "paragraph", "text": "Queria sorrir para vocês o tempo todo e virei-lhes as costas! Isso os entristece?"},
    {"type": "paragraph", "text": "(Foi durante o silêncio)"},
    {"type": "paragraph", "text": "Depois das Matinas quando Nossa Madre foi vê-la, ela tinha as mãos postas e disse com voz doce e resignada:"},
    {"type": "paragraph", "text": "Sim, meu Deus, sim meu Deus, eu quero tudo!..."},
    {"type": "paragraph", "text": "É, pois, atrofiado o que você sofre, disse Nossa Madre?"},
    {"type": "paragraph", "text": "Não, minha Madre, não é atrofiado, mas muito, muito... justo o que posso suportar."},
    {"type": "paragraph", "text": "Ela pediu ficar só à noite, mas Nossa Madre não quis. Ir. Maria do Sagrado Coração e Ir. Geneviève se repartiram essa grande consolação. Eu fiquei na cela, bem perto da enfermaria, que dá sob o claustro."},
    {"type": "heading", "text": "30 de setembro"},
    {"type": "paragraph", "text": "Quinta‑feira, dia de sua preciosa morte."},
    {"type": "paragraph", "text": "De manhã eu a velava durante a Missa. Ela não me dizia palavra. Estava exausta, ofegante; seus sofrimentos, eu pressentia, eram inexprimíveis. Um momento, juntou as mãos e olhando a estátua da Santa Virgem:"},
    {"type": "paragraph", "text": "Oh! rezei a ela com fervor! Mas é a agonia pura, sem nenhum misto de consolação."},
    {"type": "paragraph", "text": "Eu lhe disse algumas palavras de compaixão e afeição e acrescentei que ela muito me edificara durante sua doença."},
    {"type": "paragraph", "text": "E vocês, as consolações que me haveis dado! Ah! são bem grandes!"},
    {"type": "paragraph", "text": "O dia inteiro, sem um instante de trégua, ela permaneceu, pode dizer-se sem exagero, em verdadeiras tormentas. Parecia sem forças e, no entanto, para nossa grande surpresa, podia mover-se, sentar-se em sua cama."},
    {"type": "paragraph", "text": "... Vejam, dizia ela, quanta força eu tenho hoje! Não, não vou morrer! Ainda tenho meses, talvez anos!"},
    {"type": "paragraph", "text": "E se o bom Deus o quisesse, disse Nossa Madre, você aceitaria?"},
    {"type": "heading", "text": "Ela começou a responder, em sua angústia:"},
    {"type": "paragraph", "text": "Ter-se-ia de..."},
    {"type": "paragraph", "text": "Mas, recompondo-se logo, disse com um acento de resignação sublime, recostando-se em seus travesseiros:"},
    {"type": "paragraph", "text": "Eu o quero!"},
    {"type": "paragraph", "text": "Pude recolher essas exclamações, mas é impossível traduzir o acento:"},
    {"type": "paragraph", "text": "Já não creio mais na morte para mim... Já não creio senão no sofrimento... Pois bem, tanto melhor!"},
    {"type": "paragraph", "text": "Ó meu Deus!..."},
    {"type": "paragraph", "text": "Amo o bom Deus!"},
    {"type": "paragraph", "text": "Ó minha boa Santa Virgem, venha em meu socorro!"},
    {"type": "paragraph", "text": "Se isso é a agonia, o que é a morte?!"},
    {"type": "paragraph", "text": "Ah! meu bom Deus!... Sim, ele é bem bom, acho-o bem bom..."},
    {"type": "heading", "text": "Olhando a Santa Virgem:"},
    {"type": "paragraph", "text": "Oh! sabe que estou sufocando!"},
    {"type": "heading", "text": "A mim:"},
    {"type": "paragraph", "text": "Se soubesse o que é sufocar!"},
    {"type": "paragraph", "text": "O bom Deus há de ajudá-la, minha pobre pequena, e logo tudo isso acabará."},
    {"type": "paragraph", "text": "Sim, mas quando,"},
    {"type": "paragraph", "text": "... Meu Deus, tende piedade de vossa pobre filha! Tende piedade!"},
    {"type": "heading", "text": "À Nossa Madre:"},
    {"type": "paragraph", "text": "Ó minha Madre, asseguro‑vos que o cálice está cheio até a borda!..."},
    {"type": "paragraph", "text": "... Mas o bom Deus não vai me abandonar, com certeza..."},
    {"type": "paragraph", "text": "... Ele nunca me abandonou."},
    {"type": "paragraph", "text": "... Sim, meu Deus, tudo o que quiserdes, mas tende piedade de mim!"},
    {"type": "paragraph", "text": "... Minhas pequenas irmãs! minhas pequenas irmãs, rezem por mim!"},
    {"type": "paragraph", "text": "... Meu Deus! meu Deus! Vós que sois tão bom! ! !"},
    {"type": "paragraph", "text": "... Oh! sim, sois bom! eu sei..."},
    {"type": "paragraph", "text": "Depois das Vésperas, Nossa Madre pousou no seu colo uma imagem de N. Sra. do Monte Carmelo."},
    {"type": "paragraph", "text": "Ela a olhou um instante e disse, quando Nossa Madre lhe assegurou que ela logo acariciaria a Santa Virgem como o Menino Jesus nessa imagem:"},
    {"type": "paragraph", "text": "Ó minha Madre, apresente‑me logo à Santa Virgem, sou um bebê que não aguenta mais!... Prepare‑me para morrer bem."},
    {"type": "paragraph", "text": "Nossa Madre respondeu-lhe que, tendo sempre compreendido e praticado a humildade, sua preparação estava feita. Ela refletiu um instante e pronunciou humildemente estas palavras:"},
    {"type": "paragraph", "text": "Sim, parece‑me que nunca busquei senão a verdade; sim, entendi a humildade do coração... Parece‑me que sou humilde."},
    {"type": "heading", "text": "Repetiu ainda:"},
    {"type": "paragraph", "text": "Tudo o que escrevi sobre meus desejos de sofrimento. Oh! é mesmo bem verdade!"},
    {"type": "paragraph", "text": "... E não me arrependo de me ter entregue ao Amor."},
    {"type": "heading", "text": "Com insistência:"},
    {"type": "paragraph", "text": "Oh! não, não me arrependo, ao contrário!"},
    {"type": "heading", "text": "Um pouco depois:"},
    {"type": "paragraph", "text": "Jamais teria crido que fosse possível tanto sofrer! jamais! jamais! Não posso explicar isso senão pelos desejos ardentes que tive de salvar almas."},
    {"type": "paragraph", "text": "Por volta das 17h, eu estava só perto dela. Seu rosto mudou de repente, entendi que era a última agonia."},
    {"type": "paragraph", "text": "Quando a Comunidade entrou na enfermaria, ela acolheu todas as irmãs com um doce sorriso. Segurava seu Crucifixo e o contemplava constantemente."},
    {"type": "paragraph", "text": "Durante mais de duas horas, um rosnado terrível rasgou seu peito. Seu rosto estava congestionado, suas mãos violáceas, tinha os pés gelados e tremia por todos os membros. Um suor abundante perlava em gotas enormes na testa e escorria pelas faces. Estava numa opressão sempre crescente e às vezes soltava para respirar pequenos gritos involuntários."},
    {"type": "paragraph", "text": "Nesse tempo tão cheio de angústia para nós, ouvia‑se pela janela — e eu sofria muito com isso — todo um canto de tordinhos, e outros passarinhos, mas tão alto, tão perto e tão prolongado! Eu pedia ao bom Deus que os fizesse calar, esse concerto me perfurava o coração e eu temia que cansasse nossa pobre pequena Thérèse."},
    {"type": "paragraph", "text": "Num momento pareceu ter a boca tão seca que a Ir. Geneviève, pensando em aliviá‑la, pôs-lhe nos lábios um pequeno pedaço de gelo. Ela o aceitou dando‑lhe um sorriso que eu nunca esquecerei. Foi como uma suprema despedida."},
    {"type": "paragraph", "text": "Às 18h, quando o Angelus tocou, olhou longamente a estátua da Santa Virgem."},
    {"type": "paragraph", "text": "Finalmente, às 19h e poucos minutos, Nossa Madre tendo dispensado a comunidade, ela suspirou:"},
    {"type": "paragraph", "text": "Minha Madre! Não é ainda a agonia?... Não vou morrer?..."},
    {"type": "paragraph", "text": "Sim, minha pobre filha, é a agonia, mas o bom Deus talvez queira prolongá‑la algumas horas."},
    {"type": "heading", "text": "Ela retomou com coragem:"},
    {"type": "paragraph", "text": "Pois bem!... vamos!... Vamos!..."},
    {"type": "paragraph", "text": "Oh! eu não queria sofrer menos tempo..."},
    {"type": "heading", "text": "E olhando seu Crucifixo:"},
    {"type": "paragraph", "text": "Oh! eu o amo!......................"},
    {"type": "paragraph", "text": "Meu Deus... eu vos amo....."},
    {"type": "paragraph", "text": "De repente, depois de pronunciar essas palavras, ela caiu suavemente para trás, a cabeça inclinada à direita. Nossa Madre mandou tocar depressa o sino da enfermaria para chamar a Comunidade."},
    {"type": "paragraph", "text": "“Abram todas as portas”, dizia ela ao mesmo tempo. Essa palavra tinha algo de solene, e me fez pensar que no Céu o bom Deus também a dizia a seus anjos."},
    {"type": "paragraph", "text": "As irmãs tiveram tempo de se ajoelhar ao redor da cama e foram testemunhas do êxtase da santa pequena moribunda. Seu rosto retomara a tez de lírio que tinha em plena saúde, seus olhos estavam fixos para cima brilhantes de paz e alegria. Fazia certos belos movimentos de cabeça, como se Alguém a tivesse divinamente ferido com uma flecha de amor, depois retirado a flecha para feri‑la outra vez..."},
    {"type": "paragraph", "text": "A Ir. Maria da Eucaristia aproximou‑se com um candeeiro para ver mais de perto seu olhar sublime. À luz desse candeeiro, não pareceu movimento nenhum de suas pálpebras. Esse êxtase durou mais ou menos o espaço de um Credo, e ela deu o último suspiro."},
    {"type": "paragraph", "text": "Depois da morte, conservou um sorriso celestial. Estava duma beleza ravissante. Segurava tão forte seu Crucifixo que foi preciso arrancá‑lo de suas mãos para enterrá‑la. A Ir. Maria do Sagrado Coração e eu cumprimos esse ofício com a Ir. Aimée de Jésus e notamos então que ela não tinha mais do que 12 a 13 anos."},
    {"type": "paragraph", "text": "Seus membros permaneceram flexíveis até seu sepultamento, na segunda‑feira 4 de outubro de 1897."},
  ]),
  makeChapter(9, "apendice-30-de-setembro", "Apêndice — 30 de setembro", "Palavras conservadas no último dia", [
    {"type": "heading", "text": "APÊNDICE"},
    {"type": "heading", "text": "30 de setembro"},
    {"type": "paragraph", "text": "... Todos os meus pequenos desejos foram realizados... Então esse grande (morrer de amor) deverá sê-lo!"},
    {"type": "heading", "text": "À tarde :"},
    {"type": "paragraph", "text": "Ah ! quanta força eu tenho hoje !... Tenho para meses ! E amanhã, todos os dias, será ainda pior !..."},
    {"type": "paragraph", "text": "... Pois bem ! tanto melhor !"},
    {"type": "paragraph", "text": "................................................."},
    {"type": "paragraph", "text": "Não consigo respirar, não consigo morrer !..."},
    {"type": "paragraph", "text": "... Eu nunca saberei morrer !............."},
    {"type": "paragraph", "text": "... Sim, meu Deus !... Sim !............."},
    {"type": "paragraph", "text": "... Eu ainda quero sofrer ............."},
    {"type": "paragraph", "text": "Por volta das 5 horas, Madre Marie de Gonzague deixou cair suas relíquias do B. Théophane e da Madre Anne  de Jesus que estavam presas em sua cortina, à direita. As levantaram e ela lhes fez uma pequena carícia."},
  ]),
  makeChapter(10, "observacao-importante", "Observação importante", "Nota de Madre Agnès sobre os testemunhos", [
    {"type": "heading", "text": "Observação importante."},
    {"type": "paragraph", "text": "Quando minha santa pequenina Thérèse me disse, em 16 de julho de 1897 : «Você conhece todos os recantos da minha pequena alma, você só...» estou certa de que, em seu pensamento, ela não excluía dessa compreensão completa de sua alma, Ir. Marie do Sagrado Coração e Ir. Geneviève de la Ste Face. Ir. Marie do Sagrado Coração, a quem ela devia o sorriso da Santíssima Virgem, e que a havia preparado para sua primeira Comunhão, a quem se deve também a resposta maravilhosa de sua afilhada, em 17 de set. de 1896. Ir. Geneviève da Santa Face, sua Céline, que ela chamava tão suavemente : «o doce eco da minha alma.»"},
    {"type": "paragraph", "text": "Mas ela estava inspirada pelo bom Deus para me dizer isso muito particularmente, para que, mais tarde, por causa da autoridade que me seria dada, se pudesse confiar inteiramente no que eu diria e escreveria a seu respeito."},
    {"type": "paragraph", "text": "Ir. Agnès de Jésus"},
    {"type": "paragraph", "text": "c.d.i."},
    {"type": "heading", "text": "28 de agosto de 1940"},
    {"type": "heading", "text": "ÚLTIMOS ENCONTROS COM CÉLINE"},
    {"type": "paragraph", "text": "Foi o pedido de sua irmã Léonie, em 18 de julho, que levou Céline a registrar, a partir do dia 21, as palavras de Thérèse. Mas ela o faz de modo diferente de Madre Agnès. Esta escreve «todas as belas palavras» de sua irmã, Ir. Geneviève reserva‑se «aquelas que me são inteiramente pessoais». Essas dezenas de palavras não têm peso diante das setecentas registradas por Madre Agnès. Mas Céline cobre os meses mais difíceis, agosto e ainda setembro. /… Claude Langlois"},
  ]),
  makeChapter(11, "12-de-julho-de-1897", "12 de julho de 1897", "Conversas com a irmã Genoveva", [
    {"type": "heading", "text": "12 julho 1897"},
    {"type": "paragraph", "text": "No meio de uma conversa, minha pequena Thérèse interrompeu-se de repente, fitando-me com compaixão e ternura. Ela disse:"},
    {"type": "paragraph", "text": "« Ah!... é minha irmãzinha Geneviève quem sentirá mais a minha partida; certamente, é ela quem considero mais digna de compaixão, porque, assim que tem uma pena, vem me procurar, e não terá mais ninguém... »"},
    {"type": "paragraph", "text": "... Sim, mas o bom Deus lhe dará força... e depois, eu voltarei! »"},
    {"type": "heading", "text": "e, dirigindo-se a mim:"},
    {"type": "paragraph", "text": "« Eu virei buscá-la o mais cedo possível e farei Papa tomar parte nisso; você bem sabe que ele tinha sempre pressa.. »"},
    {"type": "paragraph", "text": "(ela não queria dizer com isso que ele fosse simplesmente solícito; aludia ao seu caráter, que o impedia de adiar para o dia seguinte o que se podia fazer na véspera. Jamais a execução de uma decisão tomada se arrastava em suas mãos.)"},
    {"type": "paragraph", "text": "Mais tarde, enquanto eu desempenhava junto dela meu ofício de enfermeira e falava, como sempre, da separação próxima, ela cantarolou, pondo-me em seu lugar, esta estrofe que compunha cantando: (ao ar do Cântico « Ele é meu. »)"},
    {"type": "paragraph", "text": "« Ela é minha, aquela que o próprio Céu"},
    {"type": "paragraph", "text": "« O Céu inteiro veio me arrebatar"},
    {"type": "paragraph", "text": "« Ela é minha, eu a amo, oh! sim, eu a amo"},
    {"type": "paragraph", "text": "« Nada jamais poderá nos desunir. »"},
    {"type": "paragraph", "text": "Eu lhe dizia-« O bom Deus não poderá me levar logo após a sua morte, pois não terei tido tempo de ser boa ». Ela retomou:"},
    {"type": "paragraph", "text": "« Não faz mal; lembre-se de St Joseph de Cupertino: sua inteligência era medíocre, ele era ignorante e conhecia a fundo apenas este Evangelho: Beatus venter qui te portavit. Interrogado justamente sobre esse assunto, respondeu tão bem que todos ficaram na admiração, e foi recebido com grandes honras ao sacerdócio, com seus três companheiros, sem nenhum outro exame. — Pois julgaram, a partir de suas sublimes respostas, que seus companheiros deviam saber tanto quanto ele."},
    {"type": "paragraph", "text": "« Assim, eu responderei por você, e o bom Deus lhe dará grátis tudo o que me tiver dado. »"},
    {"type": "paragraph", "text": "Nesse mesmo dia, enquanto eu ia e vinha na enfermaria, ela disse, olhando para mim:"},
    {"type": "paragraph", "text": "« Meu pequeno Valérien... »"},
    {"type": "paragraph", "text": "(Ela às vezes comparava nossa união à de Ste Cécile e de Valérien.)"},
    {"type": "paragraph", "text": "Julho 1897"},
    {"type": "paragraph", "text": "Reflexões como estas brotavam espontaneamente, ao olhar para mim:"},
    {"type": "paragraph", "text": "« Seremos como dois patinhos, você sabe como eles se seguem de pertinho! »"},
    {"type": "paragraph", "text": "« Que tristeza eu teria se visse qualquer um no outro joelho do bom Deus; eu choraria o dia inteiro!... »"},
    {"type": "paragraph", "text": "Minha pequena Thérèse fora tocada pela passagem do Evangelho em que Jésus recusa aos filhos de Zébédée estarem, no Céu, à sua direita e à sua esquerda, e ela dizia: »Eu imagino que o bom Deus reservou esses lugares para ‘pequeninos’... » Ela então esperava que essas duas crianças privilegiadas fôssemos ela e eu... (É isso que explica as minhas perguntas reiteradas, revelando o temor, fundado, ai de mim!, de jamais ser digna desse favor.)"},
  ]),
  makeChapter(12, "a-graca-de-hoec-facta-est-mihi", "A graça de «Hoec facta est mihi»", "Uma lembrança posterior de irmã Genoveva", [
    {"type": "paragraph", "text": "A graça de l’"},
    {"type": "paragraph", "text": "Hoec facta est mihi"},
    {"type": "paragraph", "text": "sobrevinda cerca de 3 semanas após a sua morte, foi a resposta a essa interrogação íntima formulada de súbito durante o Ofício de Tércia: « Minha Thérèse não me disse que tinha o lugar esperado: estar nos joelhos do bom Deus?... » — Nesse momento preciso o coro dizia:"},
    {"type": "paragraph", "text": "Hoec facta es mihi"},
    {"type": "paragraph", "text": "... eu não compreendia essas palavras, cuja tradução procurei assim que o Ofício terminou:"},
    {"type": "paragraph", "text": "Hoec facta es mihi"},
    {"type": "paragraph", "text": "..."},
    {"type": "paragraph", "text": "Isto me foi feito"},
    {"type": "paragraph", "text": "...."},
    {"type": "paragraph", "text": "Eu tinha dito que, perdendo-a, eu ficaria louca. Ela retomou:"},
    {"type": "paragraph", "text": "« Se você está louca, bobonne, o “Bom Salvador” virá buscar você!... »"},
    {"type": "paragraph", "text": "(‘Bobonne’ era um apelido que ela me dava, com a permissão de nossa Madre, porque eu a servia e, tendo constantemente necessidade de me chamar, era-lhe menos cansativo de pronunciar do que o meu nome.)"},
    {"type": "paragraph", "text": "Vendo a Madre Agnès de Jésus escrevendo todas as belas palavras de nosso Anjo, eu, não anotando apressadamente senão aquelas que me eram absolutamente pessoais, manifestei assim o pesar de não poder escrever tudo — « Eu, não faço como as outras, não tomo nota do que você diz », ela replicou imediatamente:"},
    {"type": "paragraph", "text": "« Você não tem necessidade disso, eu virei buscar você... »"},
    {"type": "paragraph", "text": "(Antes de ter descido à enfermaria, foi no mês de junho, um dia em que ela me via desolada"},
    {"type": "paragraph", "text": "diante da perspectiva de sua partida próxima, dirigiu-se ao Menino Jesus e, com um gesto encantador, erguendo o dedo, falou-lhe como que dando uma lição:"},
    {"type": "paragraph", "text": "« Meu pequeno Jesus, se o Senhor me levar, será preciso também levar a Senhorita Lili"},
    {"type": "paragraph", "text": "1"},
    {"type": "paragraph", "text": ". Eis a minha condição, portanto reflita bem no que vai fazer... Nada de meio-termo, é pegar ou largar! »"},
    {"type": "paragraph", "text": "1"},
    {"type": "paragraph", "text": "Pequeno apelido familiar que datava de nossa infância e que ela me dava na intimidade. Fora inspirado por uma historinha para bebês: « Sr. Toto e Srta. Lili » — ela era o Sr. Toto, eu a Srta. Lili."},
    {"type": "paragraph", "text": "["},
    {"type": "paragraph", "text": "bnf.fr"},
    {"type": "paragraph", "text": "]"},
    {"type": "paragraph", "text": "Em 22 de julho, eu escrevia à minha tia, Sra. Guérin:"},
    {"type": "paragraph", "text": "... Outro dia, eu lia para minha doentinha uma passagem sobre a bem-aventurança do céu, ela me interrompeu para me dizer:"},
    {"type": "paragraph", "text": "« Não é isso que me atrai... »"},
    {"type": "paragraph", "text": "O que então? repliquei eu."},
    {"type": "paragraph", "text": "« Oh! é o Amor! Amar, ser amada e voltar à terra… » [para fazer amar o amor…"},
    {"type": "paragraph", "text": "glosa"},
    {"type": "paragraph", "text": "]"},
    {"type": "paragraph", "text": "(não está no autógrafo)"},
    {"type": "paragraph", "text": "Ela tinha cuspido sangue durante a noite. Toda alegre, com seus modos infantis, ela me mostrava o prato de tempos em tempos. Frequentemente indicava a borda com um arzinho triste que queria dizer: eu gostaria que fosse até aqui!"},
    {"type": "heading", "text": "Eu lhe respondi, tristemente também eu:"},
    {"type": "paragraph", "text": "« Oh! não importa que haja pouco ou muito, o próprio fato é um sinal de sua morte... »"},
    {"type": "paragraph", "text": "Depois acrescentei: « Ai de mim! você é mais feliz do que eu, pois eu não tenho sinal para a minha! »"},
    {"type": "heading", "text": "Ela retomou imediatamente:"},
    {"type": "paragraph", "text": "« Oh! sim, você tem um sinal! A minha morte é um sinal da sua!... »"},
    {"type": "heading", "text": "21 de julho de 1897"},
    {"type": "paragraph", "text": "Enquanto eu cumpria meu ofício na enfermaria, pondo ordem no aposento, ela me seguia com os olhos e rompeu de repente o silêncio com uma palavra que nada havia provocado:"},
    {"type": "paragraph", "text": "« No céu, você tomará assento ao meu lado! »"},
    {"type": "paragraph", "text": "E, mais tarde, citando um trecho de uma bela poesia sobre Louis XVII."},
    {"type": "paragraph", "text": "« Você virá em breve comigo..."},
    {"type": "paragraph", "text": "« embalar a criança que chora"},
    {"type": "paragraph", "text": "« E, na sua morada ardente"},
    {"type": "paragraph", "text": "« De um sopro luminoso rejuvenescer os sóis... »"},
    {"type": "paragraph", "text": "depois, eu lhe porei as asas de azul celeste de um querubim vermelhão... eu mesma as prenderei, pois você não saberia, você as poria ou muito baixo, ou muito alto! »"},
    {"type": "heading", "text": "24 de julho de 1897"},
    {"type": "paragraph", "text": "Ela conhecia uma infinidade de histórias e havia retido uma porção de traços de que se servia quando necessário, o que tornava sua conversação imagética e picante."},
    {"type": "paragraph", "text": "« Você é uma alma de boa vontade, não tema nada, você tem uma pequena “cadelinha” que a salvará de todos os perigos... »"},
    {"type": "paragraph", "text": "(alusão a essa confissão que o demônio fizera ao Pe. Surin, num exorcismo: « Eu dou conta de tudo, só essa cadela de boa vontade contra a qual nada posso. »)"},
    {"type": "paragraph", "text": "Eu lhe dizia: « Você é o meu ideal, e a esse ideal eu não posso chegar, oh! como isso é cruel! Parece-me que não tenho o que é preciso para isso, sou como uma criancinha que não tem consciência das distâncias: no braço de sua mãe, estende a sua pequena mão para apanhar a cortina, um objeto... não se dá conta de que está muito longe! »"},
    {"type": "paragraph", "text": "« Sim, mas no último dia o bom Jesus aproximará sua pequena Céline de tudo quanto ela tiver desejado, e então ela agarrará tudo. »"},
  ]),
  makeChapter(13, "3-e-4-de-agosto-de-1897", "3 e 4 de agosto de 1897", "A pequenez e a confiança", [
    {"type": "heading", "text": "3 agosto 1897"},
    {"type": "paragraph", "text": "«Você é bem pequenina, lembre-se disso; e, quando somos muito pequenos, não temos pensamentos elevados...»"},
    {"type": "heading", "text": "4 de agosto de 1897"},
    {"type": "paragraph", "text": "Meus primeiros anos de vida religiosa me fizeram assistir a uma verdadeira destruição da minha natureza, eu não via ao meu redor senão ruínas, assim eu me lamentava muitas vezes. - Numa dessas circunstâncias eu a ouvi cantar."},
    {"type": "paragraph", "text": "« Bobonne imperfeita sobre a terra"},
    {"type": "paragraph", "text": "« Você será perfeita nos Céus! » (ter.)"},
    {"type": "paragraph", "text": "Para aliviar uma dor muito viva que minha querida irmãzinha sofria no ombro e no braço direitos, eu tivera a ideia, presa ao dossel de sua cama, de uma larga fita feita com pano dobrado, na qual seu braço ficava suspenso no ar. Esse alívio não pôde durar muito, no entanto ela ficou muito agradecida e me disse com ternura:"},
    {"type": "paragraph", "text": "« O bom Deus fará também cabides para a bobonne! »"},
    {"type": "paragraph", "text": "Interrompendo uma conversa exclamei tristemente pensando na sua morte:"},
    {"type": "paragraph", "text": "« Eu não saberei viver sem ela! »"},
    {"type": "paragraph", "text": "« Você tem toda a razão, assim eu lhe trarei duas... » (asas)"},
    {"type": "paragraph", "text": "Quando fiquei a sós com minha Thérèse eu disse-lhe: « Você quer que de um ovo de pardal nasça um passarinho delicioso como você, isso é impossível! »"},
    {"type": "paragraph", "text": "« Sim, mas! vou fazer um truque de física para divertir todos os santos. Vou pegar o ovinho e vou dizer aos santos: Olhem bem, eu vou fazer um truque:"},
    {"type": "paragraph", "text": "« Aqui está um ovinho de pardal, bem! vou fazer sair um lindo passarinho como eu! » Então, eu direi bem baixinho ao bom Deus, apresentando-lhe meu ovinho, mas bem baixinho, bem baixinho: « Mude a natureza do passarinho soprando nele... » Depois, quando ele me o tiver devolvido eu o darei à Santíssima Virgem e lhe pedirei que o beije... Em seguida, o confiarei a São José e pedirei que ele o acaricie... Finalmente direi bem alto a todos os Santos:"},
    {"type": "paragraph", "text": "« Digam que vocês amam tanto quanto eu o passarinho que vai sair do ovinho! »"},
    {"type": "paragraph", "text": "« Logo todos os Santos exclamarão: Nós amamos tanto quanto tu o passarinho que vai sair do ovinho!"},
    {"type": "paragraph", "text": "« Então, com ar triunfante, eu quebrarei o ovinho e um lindo passarinho virá se pôr ao meu lado no colo do bom Deus, e todos os santos ficarão numa alegria que não posso descrever, ao ouvir cantar os dois passarinhos... »"},
    {"type": "heading", "text": "5 de agosto de 1897"},
    {"type": "paragraph", "text": "Sobre esta passagem do Evangelho: « Deux femmes moudront ensemble, on prendra l’une et on laissera l’autre... »"},
    {"type": "paragraph", "text": "« Nós fazemos nosso pequeno comércio juntas, verei bem que você não pode moer o trigo sozinha, então eu virei buscá-la... Vigie, pois você não sabe a que hora deverá vir o seu Senhor. »"},
    {"type": "paragraph", "text": "Ela me lembrava frequentemente que éramos como duas sócias. Que importa que uma seja incapaz? Desde que não se separem, um dia terão parte nos mesmos lucros. Em sua comparação do passarinho no limite do claustro esperando a Águia Divina e não cessando de olhá-la amando-a, minha querida pequena Thérèse dizia-me sempre que ela não se figurava estar só, mas que havia dois passarinhos..."},
    {"type": "paragraph", "text": "Ela se esforçava por incutir-me a pobreza de espírito e de coração por palavras como esta:"},
    {"type": "paragraph", "text": "« Bobonne, ela tem de se manter em seu lugar, que ela não tente ser grande dama, nunca! »"},
    {"type": "paragraph", "text": "E como me restava rezar uma Pequena Hora do meu Ofício, disse num tom infantil:"},
    {"type": "paragraph", "text": "« Vá dizer None. E lembre-se de que você é uma pequena none, a última das nones! »"},
    {"type": "paragraph", "text": "Então vocês vão me deixar!"},
    {"type": "paragraph", "text": "« Oh! nem de uma sola! »"},
    {"type": "heading", "text": "E retomando meu tema favorito:"},
    {"type": "paragraph", "text": "« Você crê que eu ainda posso esperar estar convosco no Céu? Isso me parece impossível, é como se fizessem concorrer um pequeno manco para agarrar o que se encontra no alto de um mastro de cocanha... »"},
    {"type": "paragraph", "text": "« Sim, mas! se ali se encontra um gigante que pega o pequeno manco em seu braço, o eleva bem alto e lhe dá ele mesmo o objeto desejado! »... É assim que o bom Deus fará contigo, mas você não deve se preocupar, deve dizer ao bom Deus: « Eu sei bem que nunca serei digna do que espero, mas estendo-lhe a mão como uma pequena mendiga e tenho certeza de que o Senhor me concederá plenamente, pois Vós sois tão bom!... » »"},
    {"type": "heading", "text": "8 de agosto de 1897"},
    {"type": "paragraph", "text": "Se quando você partir escreverem sua pequena vida, eu gostaria de partir antes... acredita nisso?"},
    {"type": "paragraph", "text": "« Sim, eu creio, mas não se deve perder a paciência... veja, eu, como sou bonitinha, será preciso que você faça assim. »"},
    {"type": "heading", "text": "Agosto de 1897"},
    {"type": "paragraph", "text": "[imagem de duas crianças, das quais uma puxa a outra]"},
    {"type": "paragraph", "text": "Minha querida irmãzinha esforçava-se em todo encontro por desapegar-me de mim mesma e comparava nossa corrida àquela das duas crianças pequenas que representa esta imagem. Ela ia-se livre de tudo, vestindo uma só túnica, não tendo nada nas mãos, exceto sua irmãzinha que ela arrasta. - Esta resiste, precisa colher flores, emaranhar-se num grande buquê sem deixar livre uma única de suas mãos."},
    {"type": "heading", "text": "Um dia ela me contou esta história alegórica:"},
    {"type": "paragraph", "text": "« Era uma vez uma “senhorita” possuidora de riquezas que tornam injusta e às quais ela dava grande valor."},
    {"type": "paragraph", "text": "« Ela tinha um irmãozinho que não possuía nada, e, no entanto, vivia na abundância. Esse pequeno caiu enfermo e disse à sua irmã: “Senhorita”, se você quisesse lançaria ao fogo todas as suas riquezas que não servem senão para inquietá-la, você se tornaria minha bobonne, rejeitando seu título de “senhorita” e eu, quando estiver no país encantado para onde hei de ir em breve, voltarei para buscá-la porque você terá vivido como eu sem se inquietar com o amanhã."},
    {"type": "paragraph", "text": "« A “senhorita” compreendeu que seu irmãozinho tinha razão, ela se tornou pobre como ele, fez-se sua bobonne e jamais foi mais atormentada pela preocupação das riquezas perecíveis que ela lançara ao fogo... » « Seu irmãozinho cumpriu a palavra, veio buscá-la quando esteve no país encantado onde o bom Deus é o Rei, a Santíssima Virgem a Rainha e ambos viverão eternamente no colo do bom Deus, é o lugar que escolheram, porque sendo demasiado pobres, não puderam merecer tronos... »"},
    {"type": "paragraph", "text": "Outra vez, referindo-se ainda à imagem das duas crianças e, além disso, a uma dona de casa à qual nada faltava em todos os seus armários, disse:"},
    {"type": "paragraph", "text": "« Senhorita rica demais: muitos botões de rosa, muitos passarinhos para cantar ao seu ouvido, uma anágua, uma bateria de cozinha, pequenos pacotes... »"},
    {"type": "paragraph", "text": "Retomando um trecho que ela havia lido, onde o autor assim louvava seu herói Th. Vénard: « Ele tinha um botão de rosa nos lábios e um passarinho a cantar em seu ouvido. »"},
    {"type": "paragraph", "text": "Numa noite em que ela me via despir, tomou pena diante da miséria de nossas roupas e, servindo-se de uma expressão cômica que ouvira, exclamou:"},
    {"type": "paragraph", "text": "« Pobrezinha-Pobrezinha! como você está esfarrapada! mas você não ficará sempre assim, eu que lhe digo! »"},
    {"type": "paragraph", "text": "« Quando eu estiver no Céu, irei tirar dos tesouros do bom Deus e direi:"},
    {"type": "paragraph", "text": "« Isto para Maria, isto para Pauline, isto para Léonie, isto para a pequenina Céline... E, fazendo sinal a Papai: “É a menor agora, é preciso apressar-se e ir buscá-la!” » »"},
    {"type": "paragraph", "text": "Ela me contou este sonho que tivera pouco antes de sua doença:"},
    {"type": "paragraph", "text": "« Você estava à beira do mar com duas pessoas que eu não conhecia. Houve uma que propôs fazer um passeio, mas ela e sua companheira eram muito avaras, disseram que era preciso alugar um carneirinho em vez de um burro, para subirem as três juntas. Mas quando vocês o viram carregado dessas duas pessoas, você disse que iria a pé."},
    {"type": "paragraph", "text": "« O pobre carneirinho seguia ao longo das sebes sem poder mais e logo caiu exausto sob seu fardo."},
    {"type": "paragraph", "text": "« Então, ao dobrar de uma estrada apresentou-se diante de vocês um gracioso carneirinho todo branco que se ofereceu a vocês. Você entendeu que ele lhes sustentaria durante toda a viagem da vida; depois o carneirinho acrescentou: “Tu sabes, eu quero também pulsar em ti...”"},
    {"type": "paragraph", "text": "« Depois, eu compreendi que era a recompensa da caridade que você tivera por essas duas pessoas, por as ter suportado sem se queixar. É por isso que o próprio Jesus veio dar-se a você. »"},
    {"type": "heading", "text": "16 de agosto de 1897"},
    {"type": "paragraph", "text": "Tendo-me levantado de madrugada, encontrei minha querida irmãzinha pálida e desfigurada pela dor e pela angústia. Ela me disse:"},
    {"type": "paragraph", "text": "« O demônio está à minha volta, eu não o vejo, mas eu o sinto... ele me atormenta, ele me prende como com uma mão de ferro para me impedir de tomar o menor alívio, ele aumenta meus males para que eu me desespere. ... E eu não posso rezar! Posso apenas olhar para a Santíssima Virgem e dizer: Jesus!... Quão necessária é a oração das completas: “"},
    {"type": "paragraph", "text": "Procul recedant omnia et noctium phantasmata"},
    {"type": "paragraph", "text": "!”"},
    {"type": "paragraph", "text": "Livrai-nos dos fantasmas da noite."},
    {"type": "paragraph", "text": "« Sinto algo de misterioso... Até agora, eu sofria sobretudo do lado direito, mas o bom Deus perguntou-me se eu queria sofrer por vocês, respondi logo que sim... No mesmo instante, o lado esquerdo se apoderou de mim com uma intensidade incrível... Sofro por vocês e o demônio não quer! »"},
    {"type": "paragraph", "text": "Vivamente impressionada acendi um círio benzido e pouco depois a calma lhe foi restituída sem, no entanto, que seu novo sofrimento físico lhe fosse tirado."},
    {"type": "paragraph", "text": "Desde então, ela chamava seu lado direito: « o lado de Thérèse » e seu lado esquerdo: « o lado de Céline »."},
    {"type": "heading", "text": "20 de agosto de 1897"},
    {"type": "paragraph", "text": "« Oh! sim, eu virei buscá-la porque você não tem olhos para viver quando está bonitinha. »"},
    {"type": "heading", "text": "21 de agosto de 1897"},
    {"type": "paragraph", "text": "« Quando eu disser: “Eu sofro”, você responderá “muito bem”! - Eu não tenho força, então é você que concluirá o que eu gostaria de dizer. »"},
    {"type": "paragraph", "text": "A opressão naquele momento era muito forte, e, para ajudar-se a respirar, ela dizia como desfiando um rosário: »Eu sofro, eu sofro... » mas logo se repreendeu como se fosse um lamento e me disse o que acabo de escrever."},
    {"type": "heading", "text": "22 de agosto de 1897"},
    {"type": "paragraph", "text": "« Minha pequena Senhorita? eu a amo muito e é tão doce para mim ser cuidada por você. »"},
    {"type": "paragraph", "text": "Ela me chamara para me dizer isso."},
    {"type": "heading", "text": "24 de agosto de 1897"},
    {"type": "paragraph", "text": "Falávamos juntas uma espécie de linguagem infantil que os outros não podiam compreender. Ir. Sta. Stanislas, a 1ª enfermeira disse num tom admirado:"},
    {"type": "paragraph", "text": "« Como são formosas essas duas menininhas ali com seu jargão ininteligível! »"},
    {"type": "paragraph", "text": "Um pouco mais tarde eu disse à minha Thérèse: -« Sim, como somos formosas nós duas! mas você, você é formosa sozinha, eu só sou formosa com você! »"},
    {"type": "paragraph", "text": "« É por isso que eu virei gritar por você! »"},
    {"type": "paragraph", "text": "(vim buscá-la)"},
    {"type": "heading", "text": "31 de agosto de 1897"},
    {"type": "paragraph", "text": "« Bobonne, eu a amo muito! »"},
  ]),
  makeChapter(14, "3-de-setembro-de-1897", "3 de setembro de 1897", "A paz em meio às preocupações", [
    {"type": "heading", "text": "3 de setembro de 1897"},
    {"type": "paragraph", "text": "Eu estava diante da lareira do enfermário, indo e vindo para fazer a limpeza, e eu me afligia por algo que não saía como eu queria. Ela me disse :"},
    {"type": "paragraph", "text": "« Bobonne, nada de inquietude de espírito ! »"},
    {"type": "paragraph", "text": "Nesse mesmo dia, mas não na mesma circunstância, eu lhe fiz esta observação : - « as criaturas não saberão que nós nos amamos tanto... » Ela respondeu :"},
    {"type": "paragraph", "text": "« Não vale a pena desejar que as criaturas acreditem nisso, o principal é que isso seja... »"},
    {"type": "heading", "text": "E, tomando um tom de segurança :"},
    {"type": "paragraph", "text": "« Sim, mas! já que estaremos nós duas de joelhos diante do bom Deus! »"},
    {"type": "paragraph", "text": "(Ela tinha um modo delicioso de dizer esse « sim, mas! » locução que lhe era particular.)"},
    {"type": "heading", "text": "5 de setembro de 1897"},
    {"type": "paragraph", "text": "« Eu vou protegê-la!... »"},
    {"type": "paragraph", "text": "Eu era muito avarenta dos meus domingos, tempo livre em que me era permitido transcrever as notas tomadas às pressas em papéis informes. Eu disse :"},
    {"type": "paragraph", "text": "« Hoje é um Domingo nulo, eu não escrevi nada em nosso pequeno escrivinhório. »"},
    {"type": "heading", "text": "Ela retomou :"},
    {"type": "paragraph", "text": "« Essa é a medida de Lili, mas não de Jesus! »"},
    {"type": "heading", "text": "11 de setembro de 1897"},
    {"type": "paragraph", "text": "« Minha bobonne, você já não é bobonne, você é minha ama... e você cuida de um bebê que está morrendo. »"},
    {"type": "paragraph", "text": "Voltando-se para a imagem que representava seu querido pequeno Théophane, ela disse, dirigindo-se a ele :"},
    {"type": "paragraph", "text": "« Bobonne me cuida muito bem, então assim que eu estiver lá em cima, nós viremos buscá-la nós dois, não é? »"},
    {"type": "paragraph", "text": "« Eu amo muito a minha bobonne, mas muito... também, quando eu partir, eu vou buscá-la para agradecê-la por me ter cuidado tão bem. »"},
    {"type": "heading", "text": "Olhando-me com ternura :"},
    {"type": "paragraph", "text": "« ... Mas eu irei vê-la de novo e seu coração estará em alegria e ninguém lhe roubará sua alegria! »"},
    {"type": "heading", "text": "16 de setembro de 1897"},
    {"type": "paragraph", "text": "Eu havia acabado de cometer uma imperfeição quando ela me disse com os olhos que arregalou por completo :"},
    {"type": "paragraph", "text": "« Você ainda estará ao meu lado! »"},
    {"type": "paragraph", "text": "Comovida às lágrimas pelos cuidados que eu lhe dava, ela exclamou :"},
    {"type": "paragraph", "text": "« Oh! quanta gratidão eu tenho por você minha pobrezinha bobonne!... Você verá tudo o que eu lhe farei! »"},
    {"type": "heading", "text": "Eu temia que ela tivesse frio e eu disse :"},
    {"type": "paragraph", "text": "« Vou buscar uma pequena ‘consolação’1 »"},
    {"type": "heading", "text": "Mas ela retomou vivamente :"},
    {"type": "paragraph", "text": "« Não: é você que é minha pequena consolação... »"},
    {"type": "paragraph", "text": "1"},
    {"type": "paragraph", "text": "(as ‘consolações’ são simples pedaços de lã que a arrumadeira dá com as roupas de inverno.)"},
    {"type": "heading", "text": "19 de setembro de 1897"},
    {"type": "paragraph", "text": "« Minha bobonne, ela é doce, ela cuida muito bem de mim... Eu lhe retribuirei isso! »"},
    {"type": "heading", "text": "21 de setembro de 1897"},
    {"type": "paragraph", "text": "« Para amá-la, sou eu... e para não amá-la, não é o bom Deus!... é o diabo. »"},
    {"type": "heading", "text": "23 de setembro de 1897"},
    {"type": "paragraph", "text": "« Vocês não precisam entender, vocês são pequenas demais... »"},
    {"type": "paragraph", "text": "(entender o que o bom Deus faz em mim.)"},
    {"type": "heading", "text": "25 de setembro de 1897"},
    {"type": "paragraph", "text": "« Eu vou morrer, isso é certo... eu não sei quando, mas é certo! »"},
    {"type": "paragraph", "text": "Setembro de 1897"},
    {"type": "paragraph", "text": "Eu lhe disse um dia : « Você nos olhará do alto do céu, não é? » - Ela respondeu então espontaneamente :"},
    {"type": "paragraph", "text": "« Não, eu descerei! »"},
    {"type": "paragraph", "text": "Eu me levantava várias vezes à noite, apesar de suas instâncias. Em uma dessas visitas encontrei minha querida pequena irmã de mãos postas e os olhos voltados para o céu :"},
    {"type": "paragraph", "text": "« O que você está fazendo assim? eu lhe disse, você deveria tentar dormir. »"},
    {"type": "paragraph", "text": "« Eu não posso, eu sofro demais, então eu rezo... »"},
    {"type": "paragraph", "text": "[« E o que você diz a Jesus? »]"},
    {"type": "paragraph", "text": "« Eu não lhe digo nada, eu o amo! »"},
    {"type": "paragraph", "text": "Um dos últimos dias de sua vida, num momento de grande sofrimento, ela me suplicou assim :"},
    {"type": "paragraph", "text": "« Oh! minha pequena Irmã Geneviève, reze por mim à Santa Virgem, eu a pediria tanto se você estivesse doente! para si mesmo não se ousa pedir... »"},
    {"type": "paragraph", "text": "(« não se ousa pedir por si mesmo »... esse é o sentido.)"},
    {"type": "heading", "text": "Ela suspirava ainda, dirigindo-se a mim :"},
    {"type": "paragraph", "text": "« Oh! como é preciso rezar pelos Agonizantes, se se soubesse! »"},
    {"type": "paragraph", "text": "(Esta palavra e a maioria das outras escritas à medida por Mãe Agnès de Jésus, eu as ouvi e é porque eu via que eram anotadas que eu não as escrevia. Fui testemunha de todas, exceto as pronunciadas durante as horas do Ofício, Mãe Agnès de Jésus permanecendo então só junto a ela.)"},
    {"type": "paragraph", "text": "Para mais detalhes veja também minha Declaração manuscrita."},
    {"type": "heading", "text": "27 de setembro de 1897"},
    {"type": "paragraph", "text": "« Ó minha bobonne! eu tenho por você uma grande ternura no coração!... »"},
    {"type": "heading", "text": "30 de setembro de 1897"},
    {"type": "paragraph", "text": "Último dia de exílio da minha querida Pequena Thérèse"},
    {"type": "paragraph", "text": "No dia de sua morte, à tarde, Mãe Agnès de Jésus e eu estando sozinhas junto a ela, nossa querida pequena Santa, trêmula e desfalcada, nos chamou ao seu socorro... Ela sofria extremamente em todos os músculos e, pondo um dos seus braços sobre o ombro de Mãe Agnès de Jésus e o outro braço sobre o meu, ela permaneceu assim de braços em Cruz. Nesse momento mesmo, tocaram 3 horas e a lembrança de Jesus na Cruz se apresentou ao nosso espírito : nossa pobre pequena mártir não era ela mesma a imagem viva disso?...."},
    {"type": "paragraph", "text": "A nosso pedido : « Para quem seria seu último olhar? ... » Ela havia respondido alguns dias antes de morrer : - « Se o bom Deus me deixar livre, será para nossa Mãe » (Mãe Marie de Gonzague.)"},
    {"type": "paragraph", "text": "Ora, durante sua agonia, poucos minutos apenas antes de ela expirar, eu passei sobre seus lábios ardentes um pequeno pedaço de gelo ; quando, nesse momento, ela levantou os olhos para mim e me olhou com uma insistência profética."},
    {"type": "paragraph", "text": "Seu olhar estava cheio de ternura, tinha ao mesmo tempo uma expressão sobre-humana feita de encorajamento e de promessas, como se ela me tivesse dito :"},
    {"type": "paragraph", "text": "« Vai, vai! minha Céline, eu estarei com você!... »"},
    {"type": "paragraph", "text": "(O bom Deus lhe revelou então a longa e laboriosa carreira que eu deveria, por causa dela, seguir aqui embaixo e quis, por isso, me consolar do meu exílio? Pois a lembrança desse último olhar, tão desejado por todas, e que foi para mim, essa lembrança me sustenta sempre e me é uma força inexprimível.)"},
    {"type": "paragraph", "text": "A Comunidade presente ficou como suspensa diante desse espetáculo grandioso; mas de repente nossa querida pequena Santa baixou os olhos para procurar nossa Mãe que estava de joelhos ao seu lado, enquanto seu olhar velado retomava a expressão de sofrimento que tivera antes."},
  ]),
  makeChapter(15, "30-de-setembro-de-1897", "30 de setembro de 1897", "As últimas horas", [
    {"type": "heading", "text": "30 de setembro de 1897"},
    {"type": "paragraph", "text": "Oh! isto é realmente o sofrimento puro porque não há consolação. Não, nem uma!"},
    {"type": "paragraph", "text": "Ó meu Deus!!! eu, no entanto, amo o bom Deus... Ó minha boa Santa Virgem, venha em meu socorro!"},
    {"type": "paragraph", "text": "Se isto é a agonia, o que será a morte?..."},
    {"type": "paragraph", "text": "Ó minha Mãe! eu lhe asseguro que o vaso está cheio até a borda!"},
    {"type": "paragraph", "text": "Sim, meu Deus, enquanto o Senhor quiser... mas tenha piedade de mim! Minhas pequenas irmãs... minhas pequenas irmãs... Meu Deus, meu Deus, tenha piedade de mim!"},
    {"type": "paragraph", "text": "Eu não posso mais... eu não posso mais! e, no entanto, tenho que aguentar..."},
    {"type": "paragraph", "text": "Estou... estou reduzida... Não, eu jamais teria acreditado que se pudesse tanto sofrer... jamais, jamais!"},
    {"type": "paragraph", "text": "Ó minha Mãe, não creio mais na morte para mim... não creio mais senão no sofrimento!"},
    {"type": "paragraph", "text": "Amanhã será ainda pior! Enfim, tanto melhor!"},
  ]),
  makeChapter(16, "a-noite-de-30-de-setembro", "A noite de 30 de setembro", "A última invocação de Teresa", [
    {"type": "heading", "text": "A Noite"},
    {"type": "paragraph", "text": "(Nossa Mãe acabara de despedir a Comunidade dizendo que a agonia ainda iria se prolongar, a Santinha doente retomou imediatamente:"},
    {"type": "paragraph", "text": "Pois bem, vamos! vamos! oh! eu não gostaria de sofrer por menos tempo! . . . . . . . . . . . . . . . . . . . . ."},
    {"type": "paragraph", "text": "Oh! Eu o amo..."},
    {"type": "paragraph", "text": "« Meu Deus... eu... o amo! »)"},
  ]),
  makeChapter(17, "varia-com-irma-genevieve", "Varia — conversas com irmã Genoveva", "Testemunhos complementares de Céline", [
    {"type": "heading", "text": "Varia dos Últimos Encontros com Irmã Geneviève"},
    {"type": "heading", "text": "Varia 1"},
    {"type": "paragraph", "text": "beber devagar."},
    {"type": "paragraph", "text": "Oh! eu vejo bem..."},
    {"type": "paragraph", "text": "(que em 3 dias"},
    {"type": "paragraph", "text": "eu não poderei mais"},
    {"type": "paragraph", "text": "me recompor!)"},
    {"type": "paragraph", "text": "sorriso inefável"},
    {"type": "paragraph", "text": "sua vontade"},
    {"type": "heading", "text": "15 de setembro"},
    {"type": "heading", "text": "Varia 2"},
    {"type": "paragraph", "text": "(...) um dia, durante sua enfermidade, eu lhe exprimi a alegria que sentia por ser ela, antes de mim, a glória da família, e que a sua própria elevação me tornava mais feliz do que a minha. Eu então me regozijava em vê-la mais perfeita do que eu e até dando mais glória ao bom Deus.- Ela olhou para mim e, depois de um instante de silêncio, disse-me, com o acento de uma alma que sofre de trevas interiores, tomada pela maior amargura, mas ao mesmo tempo com um acento de verdade que me penetrava:"},
    {"type": "paragraph", "text": "«Os outros gozam muitas vezes mais do que aqueles que possuem...»"},
    {"type": "paragraph", "text": "«É porque agora você está na provação», respondi-lhe, «mas no Céu você gozará.» - Então ela retomou, mas me pareceu que era uma voz Celeste:"},
    {"type": "paragraph", "text": "«Vocês verão que será ainda a mesma coisa....»"},
    {"type": "paragraph", "text": "Não lhe perguntei mais nada, mas estava longe de compreender essa admirável"},
    {"type": "paragraph", "text": "Comunhão dos Santos que fazia suas delícias e seu: \"Tudo é meu, tudo é para mim...\" que a enlevava de alegria e esperança."},
    {"type": "heading", "text": "Varia 3"},
    {"type": "paragraph", "text": "A comida era algo em que eu não podia pensar, aquilo me revirava o estômago,"},
    {"type": "paragraph", "text": "e agora tenho desejos de animal, devoraria tudo o que me dessem, e isso me humilha muito."},
    {"type": "paragraph", "text": "Agosto"},
    {"type": "paragraph", "text": "Oh! rezem à Santíssima Virgem, minha pequenina irmã Geneviève, eu a rogaría tanto se vocês estivessem doentes, a si mesma ninguém ousa pedir!"},
    {"type": "paragraph", "text": "Setembro"},
    {"type": "paragraph", "text": "Eu olho à minha direita e à minha esquerda e procuro com os olhos e não há ninguém que me conheça... só há o Ladrão e Ele está escondido!"},
    {"type": "paragraph", "text": "Não posso mais olhar a Santa Virgem sem chorar."},
    {"type": "paragraph", "text": "Julho"},
    {"type": "paragraph", "text": "Está ficando já esqueleto, é isso que me agrada!"},
    {"type": "paragraph", "text": "(olhando para suas mãos)"},
    {"type": "paragraph", "text": "Vocês têm pena que eu me vá, por quê? eu deveria então ter de os deixar, isso seria lógico; mas sei que eu não vos deixo, ao contrário estarei mais perto de vocês."},
    {"type": "paragraph", "text": "Durante toda a minha vida nada me prendeu às mãos, não é no momento da morte que guardarei algo para mim."},
    {"type": "paragraph", "text": "Uma irmã dizia-lhe que ela poderia ter uma hora de medo da morte para expiar seus pecados."},
    {"type": "paragraph", "text": "«O medo da morte para expiar meus pecados...? isso não teria mais força do que água barrenta! Assim, se eu tiver esses temores eu os oferecerei ao bom Deus pelos pecadores e como será um ato de caridade, esse sofrimento se tornará pelos outros muito mais forte do que a água. - Para mim a única coisa que me purifica é o fogo do Amor Divino.» 12 de julho"},
    {"type": "paragraph", "text": "(A propósito do pequeno cesto de acácias e como ela me pedia para o retirar):"},
    {"type": "paragraph", "text": "Vi as belezas da terra, e minha alma sonhou os Céus."},
    {"type": "paragraph", "text": "(Então você crê que salvará mais almas no Céu?)"},
    {"type": "paragraph", "text": "«Sim, eu creio, a prova é que o bom Deus me faz morrer eu que tanto desejo salvar-Lhe almas...»"},
    {"type": "paragraph", "text": "(Um dia, depois de sua comunhão)"},
    {"type": "paragraph", "text": "Era como se tivessem posto duas crianças juntas e as crianças não se dizem nada; contudo eu lhe disse algumas coisinhas, mas Ele não me respondeu, sem dúvida que Ele dormia."},
    {"type": "paragraph", "text": "Quando penso que morrerei numa cama! eu teria querido morrer numa arena..."},
    {"type": "paragraph", "text": "Quando eu estiver morta não direi nada, não darei conselho nenhum. Se me colocarem à direita ou à esquerda eu não ajudarei. Dir-se-á: ela está melhor deste lado; pode até pôr fogo ao lado de mim, eu não direi nada."},
    {"type": "paragraph", "text": "O bom Deus, Ele tem jardins que confia a proprietários e ordinariamente Ele jamais colhe frutos sem sua permissão; mas o bom Deus tem tanta vontade de um cachinho que o proprietário não quer Lhe dar que Ele vai roubá-lo."},
    {"type": "heading", "text": "12 de julho."},
    {"type": "paragraph", "text": "(Isso foi a propósito da sua morte, porque nossa Mãe não podia resignar-se a dar-lhe permissão, é desde então que ela chamou Jesus: o Ladrão)"},
    {"type": "paragraph", "text": "(A festa ao Bebê... Ela dizia que sempre lhe deveria fazer presentes...)"},
    {"type": "paragraph", "text": "Quando eu tiver partido atentem bem a não levar vida de família, a não contar nada dos parlatórios sem permissão e ainda pedir permissão somente quando são coisas úteis e não divertidas."},
    {"type": "paragraph", "text": "(Um dia que se encontrava diante de uma biblioteca)"},
    {"type": "paragraph", "text": "Oh! como eu ficaria triste de ter lido todos esses livros!"},
    {"type": "paragraph", "text": "Por que então, uma vez que estivessem lidos seria um bem adquirido, eu compreenderia arrepender-me de lê-los mas não de os ter lido."},
    {"type": "paragraph", "text": "«Se eu os tivesse lido eu teria quebrado a cabeça, teria perdido um tempo precioso que poderia empregar simplesmente a amar o bom Deus...»"},
    {"type": "paragraph", "text": "Conto bem não ficar inativa no Céu, meu desejo é trabalhar para a Igreja e as almas, peço-o ao bom Deus e estou certa de que Ele me ouvirá, os Anjos não estão continuamente ocupados conosco sem jamais cessar de ver a Face divina, de se perder no Oceano sem margem do Amor. Por que Jesus não me permitiria imitá-los? Vêem que se eu já abandono o campo de batalha não é com o desejo egoísta de descansar; o pensamento da bem-aventurança eterna mal faz meu coração estremecer, há muito o sofrimento se tornou meu Céu aqui embaixo e tenho dificuldade em conceber como poderei aclimatar-me num país onde a alegria reina sem nenhum misto de tristeza, será preciso que Jesus transforme minha alma e lhe dê a faculdade de gozar, caso contrário eu não poderia suportar os deleites eternos. (Trecho de uma carta)"},
    {"type": "paragraph", "text": "Eu tinha, dizia ela, uma capacidade muito grande para sofrer e muito pequena para gozar, eu não podia suportar a alegria. A alegria, por exemplo, me tirava todo apetite enquanto que os dias em que eu tinha muita pena eu comia como quatro. Era o contrário de todo mundo."},
    {"type": "paragraph", "text": "Estou num estado de espírito em que me parece que não penso mais."},
    {"type": "paragraph", "text": "Não faz nada, o bom Deus conhece vossas intenções, enquanto vocês forem humildes enquanto vocês forem felizes."},
    {"type": "paragraph", "text": "Uma vez que a hora tocava e eu não me levantava depressa o suficiente ela me disse:"},
    {"type": "paragraph", "text": "«Vá ao vosso pequeno dever»"},
    {"type": "heading", "text": "e retificando-se:"},
    {"type": "paragraph", "text": "«não, ao vosso pequeno amor!»"},
    {"type": "paragraph", "text": "E outra vez eu disse: é preciso que eu trabalhe porque Jesus ficaria triste, ela retorquiu:"},
    {"type": "paragraph", "text": "«Mas não, seriam vocês que ficariam tristes, ele não pode ficar triste com nossos arranjos, mas que aflição para nós não Lhe dar tanto quanto podemos!»"},
    {"type": "heading", "text": "Varia 4"},
    {"type": "paragraph", "text": "Ao longo do ano de 1897, irmã Teresa do Menino Jesus me disse, bem antes de ficar doente, que esperava bem morrer naquele ano; eis a razão que ela me deu no mês de junho: quando se viu tomada por uma tuberculose pulmonar:"},
    {"type": "paragraph", "text": "«Vê, disse-me ela, o bom Deus vai me tomar numa idade em que eu não teria tido tempo de ser padre... se eu pudesse ter sido padre, teria sido neste mês de junho, nesta ordenação que eu teria recebido as sagradas Ordens. Ah! bem, para que eu não me arrependa de nada, o bom Deus permite que eu fique doente, portanto eu não poderia aí ir e eu morrerei antes de ter exercido meu ministério.»"},
    {"type": "heading", "text": "Varia 5"},
    {"type": "paragraph", "text": "Quando ocorriam hemorragias, ela se regozijava, pensando que derramava seu sangue para o bom Deus:"},
    {"type": "paragraph", "text": "«Não poderia ser de outro modo, dizia ela, e eu bem sabia que teria essa consolação de ver meu sangue derramado, pois eu morro mártir de amor.»"},
    {"type": "heading", "text": "ÚLTIMOS ENCONTROS COM MARIA"},
  ]),
  makeChapter(18, "8-de-julho-de-1897", "8 de julho de 1897", "A coragem no combate", [
    {"type": "heading", "text": "8 de julho de 1897"},
    {"type": "paragraph", "text": "A respeito de uma noviça que a cansava muito, eu lhe disse: «Isto é para a senhora uma grande luta! A senhora tem medo?»"},
    {"type": "paragraph", "text": "Um soldado não tem medo do combate e eu sou um soldado."},
    {"type": "paragraph", "text": "(Après avoir grondé la même novice)"},
    {"type": "paragraph", "text": "Será que não disse que morrerei com as armas na mão?"},
    {"type": "paragraph", "text": "O «Ladrão» está bem longe, foi roubar outras crianças!"},
    {"type": "paragraph", "text": "Estamos em 8 de julho e, em 9 de junho, eu via o Ladrão. Se é assim que ele age, ele não está prestes a me roubar..."},
    {"type": "paragraph", "text": "puseram-me «em um leito de desgraça», em um leito que faz perder o trem."},
    {"type": "paragraph", "text": "Ela fazia alusão à Madre Geneviève, que, nesse mesmo leito, havia recebido três vezes a Extrema Unção."},
    {"type": "heading", "text": "9 de julho de 1897"},
    {"type": "paragraph", "text": "Após a visita do médico que a encontrava melhor."},
    {"type": "paragraph", "text": "O «Ladrão» partiu de novo! Enfim, como o bom Deus quiser!"},
    {"type": "heading", "text": "12 de julho de 1897"},
    {"type": "paragraph", "text": "Se a senhora tivesse que recomeçar sua vida, como faria?"},
    {"type": "paragraph", "text": "Eu faria como fiz."},
    {"type": "heading", "text": "13 de julho de 1897"},
    {"type": "paragraph", "text": "Se a senhora soubesse como faço planos, como farei coisas quando estiver no Céu... Começarei minha missão..."},
    {"type": "paragraph", "text": "Que planos a senhora tem, então?"},
    {"type": "paragraph", "text": "Planos de voltar com minhas pequenas irmãs, e de ir para lá para ajudar os missionários, e depois impedir que os pequenos selvagens morram antes de serem batizados."},
    {"type": "paragraph", "text": "Eu lhe dizia que quando ela partisse eu não teria mais coragem, parece-me, de dirigir palavra a ninguém, que ficaria num estado de prostração."},
    {"type": "paragraph", "text": "Isso não é conforme à lei evangélica. É preciso fazer-se tudo a todos."},
    {"type": "paragraph", "text": "Alegre-se, a senhora logo será libertada das penas da vida!"},
    {"type": "paragraph", "text": "Eu, que sou uma soldada tão valente!"},
    {"type": "paragraph", "text": "Pequena madrinha, o que é preciso que ela faça?"},
    {"type": "paragraph", "text": "Que ela se eleve acima de tudo o que dizem as irmãs, de tudo o que elas fazem. É preciso que a senhora esteja como se não estivesse em seu mosteiro, como se só devesse passar dois dias aqui. A senhora tomaria grande cuidado em não dizer o que a desagrada, já que deve partir."},
    {"type": "paragraph", "text": "(Como eu terminava de escrever estas palavras enquanto se tocava o Salve)"},
    {"type": "paragraph", "text": "Seria, de muito longe, melhor perder isso e praticar um ato de regularidade. Se se soubesse o que é!"},
    {"type": "heading", "text": "16 de julho de 1897"},
    {"type": "paragraph", "text": "Se o bom Deus me dissesse: «Se tu morres agora mesmo, terás uma glória muito grande. Se morres aos 80 anos, tua glória será bem menor, mas isso me dará muito mais prazer.» Então eu não hesitaria em responder: — Meu Deus, quero morrer aos 80 anos, porque não busco minha glória, mas somente o Vosso prazer."},
    {"type": "paragraph", "text": "Os grandes santos trabalharam para a glória do bom Deus, mas eu, que não sou senão uma alma muito pequenina, trabalho para o seu único prazer, para as suas fantasias, e eu seria feliz em suportar os maiores sofrimentos, mesmo sem que o bom Deus o soubesse, se isso fosse possível, não para lhe dar uma glória passageira, mas se eu soubesse apenas que por isso um sorriso pudesse roçar seus lábios."},
    {"type": "heading", "text": "25 de julho de 1897"},
    {"type": "paragraph", "text": "«Ao me inclinar um pouco, eu via pela janela o sol poente que lançava seus últimos feixes sobre a natureza, e o topo das árvores parecia todo dourado. Eu me dizia então: Que diferença se se fica à sombra ou, ao contrário, se se expõe ao sol do amor... Então parece-se todo dourado. É por isso que pareço toda dourada. Na realidade eu não o sou e cessaria de o ser imediatamente se me afastasse do amor.»"},
    {"type": "heading", "text": "28 de julho de 1897"},
    {"type": "paragraph", "text": "Dizíamos que nos custaria muito perder nossas recreações por qualquer outra pessoa que não ela. Ela respondeu de pronto:"},
    {"type": "paragraph", "text": "E eu teria ficado tão feliz de o fazer! Pois estamos na terra para sofrer, quanto mais se sofre, mais se é feliz... Pratica-se bem mais a caridade obrigando uma pessoa que lhe é menos simpática."},
    {"type": "paragraph", "text": "Oh! Como se sabe mal cuidar das suas pequenas coisas na terra!"},
    {"type": "paragraph", "text": "Eu lhe dizia: como se é feliz por morrer depois de ter passado a vida no amor."},
    {"type": "paragraph", "text": "Sim, mas também não se deve faltar à caridade para com o próximo."},
    {"type": "heading", "text": "29 de julho de 1897"},
    {"type": "paragraph", "text": "Eu lhe dizia que certa pequena música de Santa Marta tinha sido para ela uma ocasião de méritos: Ela retomou imediatamente:"},
    {"type": "paragraph", "text": "Nada de méritos! Fazer feliz o bom Deus... Se eu tivesse acumulado méritos, eu ficaria logo desesperada!"},
  ]),
  makeChapter(19, "agosto-com-irma-genevieve", "Agosto de 1897 — irmã Genoveva", "Confidências sobre a morte e o abandono", [
    {"type": "heading", "text": "1 de agosto de 1897"},
    {"type": "paragraph", "text": "Não sei como farei para morrer... Ah! estou bem abandonada... Como o bom Deus quiser!"},
    {"type": "heading", "text": "10 de agosto de 1897"},
    {"type": "paragraph", "text": "Eu lhe dizia: Eu que pedi para que você não sofresse muito e você sofre tanto!"},
    {"type": "heading", "text": "Ela me respondeu:"},
    {"type": "paragraph", "text": "Pedi ao bom Deus que não escutasse as orações que pudessem colocar obstáculo ao cumprimento de seus desígnios sobre mim e que Ele levantasse todas as dificuldades que se opusessem a isso."},
    {"type": "heading", "text": "1 de agosto de 1897"},
    {"type": "paragraph", "text": "Eu lhe dizia: Então eu não poderei desabafar junto de Madre Inês de Jesus?"},
    {"type": "paragraph", "text": "Só no caso em que ela tivesse necessidade de consolação. Da sua parte, nunca se deve falar com ela para a sua própria consolação enquanto ela não for Priora. Eu lhe asseguro que foi sempre isso que fiz. Assim Nossa Mãe lhe havia dado permissão para me falar, mas eu não a tinha e eu não lhe dizia nada da minha alma. Acho que é isso que torna a vida religiosa um martírio. Sem isso, seria uma vida fácil e sem méritos."},
    {"type": "heading", "text": "15 de agosto de 1897"},
    {"type": "paragraph", "text": "No dia 13, antes de receber a Santa Comunhão, ela ficou particularmente comovida com o Confiteor recitado pela Comunidade. Ela me disse:"},
    {"type": "paragraph", "text": "Quando eu ouvia todas as irmãs dizerem por mim: Eu confesso a Deus Pai todo-Poderoso, à Bem-aventurada Virgem Maria, a todos os Santos, eu pensava: Oh! sim, é bom pedir perdão a todos os Santos... Não posso expressar meus sentimentos. É assim que o bom Deus me faz sentir o quão pequena eu sou. Isso me deixa tão feliz!2Eu lhe dizia: O que me entristece é que você vai ainda sofrer muito."},
    {"type": "paragraph", "text": "Não para mim, porque o bom Deus me dá o que me é necessário."},
    {"type": "paragraph", "text": "Dizíamos: Se o bom Deus a levasse esta noite, ela se iria sem que se percebesse... Que dor teríamos!"},
    {"type": "paragraph", "text": "Ah! acho que seria muito gentil da parte dele, ele me furtaria!"},
    {"type": "heading", "text": "20 de agosto de 1897"},
    {"type": "paragraph", "text": "Não é como as pessoas que sofrem pelo passado, que sofrem pelo futuro. Eu, eu só sofro no momento presente - Assim, não é grande coisa."},
    {"type": "heading", "text": "22 de agosto de 1897"},
    {"type": "paragraph", "text": "Não se sabe o que é sofrer assim... Não! é preciso sentir… (Depois desse mesmo dia de sofrimentos contínuos.) Vejam como o bom Deus é bom! Hoje eu não tive forças para tossir e eu quase não tossi. Agora que estou um pouco melhor, isso vai recomeçar."},
    {"type": "heading", "text": "27 de agosto de 1897"},
    {"type": "paragraph", "text": "Eu lhe disse: quer água gelada?"},
    {"type": "paragraph", "text": "Oh! estou com tanta vontade!... - Nossa Mãe obrigou você a pedir tudo o que lhe é necessário, faça-o por obediência. - Peço tudo aquilo de que preciso."},
    {"type": "paragraph", "text": "Não aquilo que lhe faz prazer? - Não, somente o que me é necessário. Assim, quando eu não tenho uvas eu não pediria."},
    {"type": "paragraph", "text": "(Algum tempo depois de ter bebido, ela olhava seu copo d'água - Eu lhe disse: Beba um pouco.) - Não, eu não tenho a língua ressequida. (Quando penso que, doente como você está, você ainda encontra meio de se mortificar? O que quer, se eu me ouvisse eu beberia com demasiada frequência."},
  ]),
  makeChapter(20, "1-de-setembro-de-1897", "1º de setembro de 1897", "Servir Cristo nos doentes", [
    {"type": "heading", "text": "1 de setembro de 1897"},
    {"type": "paragraph", "text": "(Sobre Madre H. do Coração de Jesus a quem era preciso prestar muitos pequenos serviços.)"},
    {"type": "paragraph", "text": "Como eu teria sido feliz por ser sua enfermeira. Isso talvez me teria custado conforme a natureza, mas parece-me que eu a teria cuidado com tanto amor, porque penso no que disse Nosso Senhor: «Eu estava doente e vocês me aliviaram.»"},
    {"type": "heading", "text": "8 de setembro"},
    {"type": "paragraph", "text": "Ah! a Santa Virgem! Ela não veio me buscar!..."},
    {"type": "heading", "text": "17 de setembro"},
    {"type": "paragraph", "text": "(a propósito do cemitério)"},
    {"type": "paragraph", "text": "Você, eu compreendo que isso lhe cause algo. Mas eu! O que quer que isso me cause?... Vai-se colocar algo de morto na terra; não é como se eu estivesse em letargia, então isso seria cruel."},
    {"type": "heading", "text": "21 de setembro"},
    {"type": "paragraph", "text": "Desejava uma palavra, como se ela se lembrasse do passado e da devoção com que a cercara na infância. Mal tive esse pensamento e ela nos olhou, Madre Agnès de Jésus e eu, com os olhos cheios de lágrimas, dizendo:"},
    {"type": "paragraph", "text": "«Pequinhas irmãs... foram vocês que me criaram!...»"},
    {"type": "heading", "text": "25 de setembro"},
    {"type": "paragraph", "text": "Eu a olhava com ternura."},
    {"type": "paragraph", "text": "«Madrinha, como você é bela quando seu rosto se ilumina com um raio de amor... é tão puro!»"},
    {"type": "heading", "text": "30 de setembro"},
    {"type": "paragraph", "text": "«Oh! é realmente o sofrimento puro porque não há consolação... Não, nenhuma!» Ó meu Deus!!! Eu, no entanto, amo o bom Deus... Ó minha boa Santa Virgem, venha em meu socorro!"},
    {"type": "paragraph", "text": "Se isto é a agonia, que será a morte?..."},
    {"type": "paragraph", "text": "Ó minha pobre pequenina Mãe, asseguro-lhe que o vaso está cheio até a borda!"},
    {"type": "paragraph", "text": "Sim, meu Deus, tudo o que Vós quiserdes!... Mas tenha piedade de mim!"},
    {"type": "paragraph", "text": "Minhas pequeninas irmãs... minhas pequeninas irmãs... Meu Deus... Meu Deus, tenha piedade de mim! Eu não posso mais... eu não posso mais! E, no entanto, é preciso que eu suporte... Estou... estou reduzida... Não, eu nunca teria acreditado que se pudesse tanto sofrer... nunca! nunca!"},
    {"type": "paragraph", "text": "Ó minha Mãe, não acredito mais na morte para mim... Acredito bem no sofrimento!"},
    {"type": "paragraph", "text": "Amanhã será ainda pior? Pois então, tanto melhor!"},
    {"type": "heading", "text": "Última palavra, olhando para seu crucifixo:"},
    {"type": "paragraph", "text": "«Oh! eu o amo..."},
    {"type": "paragraph", "text": "Meu Deus... eu vos amo!»"},
  ]),
  makeChapter(21, "varia-com-irma-maria", "Varia — conversas com irmã Maria", "Últimas palavras a outras irmãs", [
    {"type": "heading", "text": "Varia dos Últimos Conversas com Irmã Marie do Sagrado Coração"},
    {"type": "heading", "text": "Varia 1"},
    {"type": "paragraph", "text": "« Quando se recorre aos Santos, dizia-me ela, eles fazem-nos esperar um pouco, sente-se que eles devem ir apresentar a sua súplica; mas quando peço uma graça à Santa Virgem, é uma ajuda imediata que recebo. »"},
    {"type": "heading", "text": "E acrescentava:"},
    {"type": "paragraph", "text": "« Nunca reparaste nisso? Experimenta e verás... »"},
    {"type": "paragraph", "text": "Pedi-lhe então que me escrevesse o que pensava sobre a Sta. Virgem e ela compôs, no mês de maio de 1897, sua última poesia em sua honra:"},
    {"type": "paragraph", "text": "« Meu pequeno Cântico, dizia-nos ela, expressa tudo o que penso e o que pregaria sobre a Santa Virgem se eu fosse padre. »"},
    {"type": "paragraph", "text": "Trata-se do Cântico intitulado «Pourquoi je t'aime, ô Marie !»"},
    {"type": "paragraph", "text": "Pn54"},
    {"type": "heading", "text": "Varia 2"},
    {"type": "paragraph", "text": "A enfermeira lhe havia aconselhado fazer todos os dias uma pequena caminhada de quinze minutos no jardim. Encontrei-a caminhando penosamente e por assim dizer sem forças."},
    {"type": "paragraph", "text": "« Faria muito melhor, disse-lhe eu, em repousar; essa caminhada não pode lhe fazer nenhum bem em tais condições; você se esgota e pronto. »"},
    {"type": "paragraph", "text": "« É verdade, respondeu-me ela, mas sabe o que me dá forças? Pois bem, eu caminho por um missionário. Penso que lá longe, muito longe, um deles talvez esteja exausto em suas correrias apostólicas, e, para diminuir seus cansaços, ofereço os meus ao bom Deus. »"},
    {"type": "heading", "text": "Varia 3"},
    {"type": "paragraph", "text": "Em razão do caráter peculiar desta palavra, citamos as 3 versões redigidas por irmã Marie do Sagrado Coração, testemunha principal; e as fazemos seguir do testemunho de Madre Agnès de Jésus, e do de irmã Geneviève."},
    {"type": "paragraph", "text": "Irmã Marie do Sagrado Coração"},
    {"type": "paragraph", "text": "Bayeux, I, 371r°, trecho omitido nos Summaria I e II)"},
    {"type": "heading", "text": "E mesmo um dia, disse-nos com um ar gracioso:"},
    {"type": "paragraph", "text": "« Minhas pequenas irmãs, sabem bem que cuidam de uma pequena santa! »"},
    {"type": "heading", "text": "(NP"},
    {"type": "meta", "text": "Referência documental: p.46."},
    {"type": "paragraph", "text": "Noutra ocasião, estávamos nós as três ao redor de sua cama a prestar-lhe alguns cuidados. Ela olhou-nos com um ar celeste e disse-nos:"},
    {"type": "paragraph", "text": "« Sabem bem que cuidam de uma pequena santa... »"},
    {"type": "paragraph", "text": "Essa palavra parecia dita por outra, tal era o acento de candura e de esquecimento de si mesma que havia em seu olhar e em sua voz. O contraste, de fato, era frappante entre suas palavras e a expressão de seu rosto. Sentia-se que era o Espírito Santo que falava nela, como vemos tantos exemplos na vida dos santos."},
    {"type": "paragraph", "text": ", 2339)"},
    {"type": "paragraph", "text": "Por volta de agosto de 1897, cerca de seis semanas antes de sua morte, eu estava junto de sua cama com Madre Agnès de Jésus e Irmã Geneviève. De repente, sem que nenhuma conversa tivesse levado a essa palavra, ela nos olhou com um ar celeste e nos disse muito distintamente:"},
    {"type": "paragraph", "text": "« Sabem bem que cuidam de uma pequena santa. »"},
    {"type": "paragraph", "text": "Perguntada se a Serva de Deus acrescentou alguma explicação ou correção a esta fala, respondeu:"},
    {"type": "paragraph", "text": "Fiquei muito comovida com essa palavra como se tivesse ouvido um santo predizer o que aconteceria depois de sua morte. Sob o impulso dessa comoção, afastei-me um pouco da enfermaria, e não me lembro de ter ouvido outra coisa."},
    {"type": "paragraph", "text": "Madre Agnès de Jesus"},
    {"type": "heading", "text": ".O"},
    {"type": "meta", "text": "Referência documental: 2355 Bayeux I 270v°."},
    {"type": "paragraph", "text": "Um dia que minhas irmãs e eu, alguns dias antes de sua morte, lhe dávamos cuidados, ela nos disse de súbito:"},
    {"type": "paragraph", "text": "« Sabem bem que cuidam de uma pequena santa. »"},
    {"type": "paragraph", "text": "E depois de um momento de silêncio,"},
    {"type": "paragraph", "text": "« Aliás, vocês são santas também. »"},
    {"type": "paragraph", "text": "Perguntada se a Serva de Deus havia sofrido algum delírio ou algo semelhante durante a doença terminal, respondeu:"},
    {"type": "paragraph", "text": "Ela não perdeu por um só instante sua presença de espírito; era, ao contrário, tanto mais serena quanto a morte estava mais próxima."},
    {"type": "paragraph", "text": "(Carta a irmã Françoise-Thérèse Martin, 4/9/1936 em resposta à pergunta desta, datada de 3/9/1936)"},
    {"type": "paragraph", "text": "« É verdade que nossa pequena Thérèse, nos últimos dias de sua vida, lhe disse: sabem, minhas pequenas irmãs, que é uma santa aquela que vocês servem? »"},
    {"type": "paragraph", "text": "(...) respondo à tua pergunta. É muito simples. Um dia que lhe prodigalizávamos os cuidados à nossa pequena Santa muito doente, ela disse:"},
    {"type": "paragraph", "text": "« Sabem bem que cuidam de uma pequena Santa... »"},
    {"type": "paragraph", "text": "Sr M. du S.C. ficou muito impressionada... Depois de um silêncio nossa Thérèse continuou:"},
    {"type": "paragraph", "text": "« Mas vocês são santas também... »"},
    {"type": "paragraph", "text": "A primeira palavra era certamente inspirada... a segunda, não, era como para apagar o efeito da primeira..."},
    {"type": "paragraph", "text": "Irmã Genevieve"},
    {"type": "meta", "text": "Referência documental: 2343."},
    {"type": "paragraph", "text": "Quanto à palavra pronunciada nos últimos dias de sua vida:"},
    {"type": "paragraph", "text": "« Sabem bem que cuidam de uma pequena santa »"},
    {"type": "paragraph", "text": "creio tê-la ouvido diretamente, pois minhas irmãs e eu quase não a deixávamos, e eu, que era enfermeira, a deixava menos ainda do que as outras; no entanto não a anotei em meu caderninho e poderia, rigorosamente, tê-la sabido apenas por minhas irmãs."},
    {"type": "heading", "text": "Varia 4"},
    {"type": "paragraph", "text": "Nos últimos dias de sua vida, estando ela consumida pela febre, eu quis levantar o lençol de sobre seus pés para refrescá-la, mas ela me disse:"},
    {"type": "paragraph", "text": "« Talvez não seja permitido? »"},
    {"type": "paragraph", "text": "Madre Marie de Gonzague nos havia dito outrora: que mesmo no verão era melhor manter a cobertura de lã, e irmã Thérèse de l'Enfant Jésus não se julgava dispensada pela doença de praticar a obediência e a mortificação até o heroísmo. Ela não teria tido senão uma palavra a dizer para obter esse alívio que todas as doentes tomam, aliás, sem sequer pensar que fosse preciso para isso uma permissão."},
    {"type": "heading", "text": "Varia 5"},
    {"type": "heading", "text": "9 de outubro de 1898 - (...) Ela (Thérèse) porém me disse alguns dias antes de morrer"},
    {"type": "paragraph", "text": "Você tem uma natureza orgulhosa!... Mas..."},
    {"type": "paragraph", "text": "Como se pensasse: você não se contém o bastante. E quando eu lhe perguntava se eu me tornaria santa:"},
    {"type": "paragraph", "text": "« Se quiseres... »"},
    {"type": "heading", "text": "ÚLTIMAS PALAVRAS DE THÉRÈSE A OUTRAS IRMÃS"},
    {"type": "paragraph", "text": "Marie de l’Eucharistie"},
    {"type": "paragraph", "text": "(Guérin) -"},
    {"type": "paragraph", "text": "Marie da Trindade"},
    {"type": "paragraph", "text": "-"},
    {"type": "paragraph", "text": "Thérèse de St-Augustin"},
    {"type": "paragraph", "text": "-"},
    {"type": "paragraph", "text": "Hermance du Coeur de Jésus"},
    {"type": "paragraph", "text": "-"},
    {"type": "paragraph", "text": "Marie des Anges"},
    {"type": "paragraph", "text": "-"},
    {"type": "paragraph", "text": "Marthe de Jésus"},
    {"type": "paragraph", "text": "-"},
    {"type": "paragraph", "text": "Marie de Jésus"},
    {"type": "paragraph", "text": "Marie de l’Eucharistie"},
    {"type": "heading", "text": "11 de julho"},
    {"type": "paragraph", "text": "« Aconselho-te, quando tiveres combates contra a Caridade, a ler este capítulo da Imitação: Que é preciso suportar os defeitos dos outros. Verás que teus combates cairão; sempre me fez muito bem, é muito bom e muito verdadeiro. »"},
    {"type": "heading", "text": "18 de julho"},
    {"type": "paragraph", "text": "Pedi-lhe que me obtivesse grandes graças quando ela estivesse no Céu, e ela respondeu-me:"},
    {"type": "paragraph", "text": "« Oh! quando eu estiver no Céu, farei muitas coisas, grandes coisas »... \"É impossível que não seja o bom Deus que me dê ele mesmo esse desejo\", tenho certeza de que Ele me ouvirá! - E ainda, quando eu estiver lá em cima, sou eu que vos seguirei de perto!... »"},
    {"type": "paragraph", "text": "E como eu lhe dizia que ela talvez me amedrontasse:"},
    {"type": "paragraph", "text": "« Teu Anjo da Guarda te assusta?.. Ele, contudo, te segue todo o tempo; pois bem, eu te seguirei do mesmo modo, e ainda mais de perto! não te deixarei passar nada... »"},
    {"type": "paragraph", "text": "Julho"},
    {"type": "paragraph", "text": "« Sempre faz um pouquinho de pena ao bom Deus quando se discute um pouquinho sobre o que diz a Mãe Priora; e faz muita pena quando se discute muito, mesmo em seu coração. »"},
    {"type": "heading", "text": "2 de agosto"},
    {"type": "paragraph", "text": "« Não encontro nenhum prazer natural em ser amada, mimada, mas encontro um muito grande em ser humilhada. Quando fiz uma bobagem que me humilha e me faz ver o que sou, oh! então, é aí que sinto um prazer natural; sinto uma verdadeira alegria como vocês sentiriam em ser amadas. »"},
    {"type": "heading", "text": "11 de setembro"},
    {"type": "paragraph", "text": "« Seria preciso que vocês se tornassem muito brandas; jamais palavras duras, tom duro; nunca tomem um ar duro, sejam sempre suaves."},
    {"type": "paragraph", "text": "« Assim, ontem, vocês fizeram sofrer a Irmã X; alguns instantes depois, outra irmã também a fez sofrer. O que aconteceu?.. Ela chorou!... Pois bem, se vocês não a tivessem tratado duramente, ela teria aceitado melhor a segunda pena, a qual teria passado despercebida. Mas duas dores tão próximas a colocaram num estado de grande tristeza; ao passo que, se vocês tivessem sido brandas, nada teria acontecido. »"},
    {"type": "paragraph", "text": "Um dia, ela me fez prometer ser santa; perguntava-me se eu fazia progressos; então eu retruquei: « Prometo ser santa quando você for para o Céu; nesse momento, vou me dedicar de todo o coração. »"},
    {"type": "paragraph", "text": "— Oh! não espere por isso, respondeu-me ela. Comece desde já. O mês que precedeu minha entrada no Carmelo ficou para mim como uma doce lembrança. No começo, eu dizia a mim mesma como você: \"Serei santa quando estiver no Carmelo; entretanto, não vou me privar.\" Mas o bom Deus me mostrou o valor do tempo; fiz todo o contrário do que pensava; quis preparar-me para minha entrada sendo muito fiel; e é um dos meses mais belos da minha vida."},
    {"type": "paragraph", "text": "« Acredite em mim, nunca espere até amanhã para começar a tornar-se santa. »"},
    {"type": "paragraph", "text": "Marie da Trindade"},
    {"type": "paragraph", "text": "1"},
    {"type": "paragraph", "text": "(...) Tenho sempre presentes os três longos meses de agonia de nosso Anjo (...) eu tinha a proibição de falar com ela, sob o pretexto de que, sendo jovem, poderia contrair sua doença! (Eu estava contudo certa do contrário porque Sr Th. de l'E.J. me havia afirmado que ninguém pegaria sua doença, que ela a havia pedido ao bom Deus.) As notícias de sua saúde eram a cada dia mais tristes; eu sufocava de pena... Um dia fui tomar ar no jardim, vi-a em sua cadeira de doente \\ sob os castanheiros; ela estava sozinha, fez-me sinal de aproximar-me: « Oh! não, disse-lhe eu, nos veriam e eu não tenho permissão. » Entrei no eremitério da Santa Face onde comecei a chorar. Ao erguer a cabeça, vi com surpresa minha pequena irmã Thérèse do Menino Jesus sentada num tronco de árvore, ao meu lado. Ela me disse:"},
    {"type": "paragraph", "text": "« Eu não tenho proibição de vir a ti, mesmo que morra, quero consolar-te. »"},
    {"type": "paragraph", "text": "Enxugou minhas lágrimas apoiando minha cabeça em seu coração. Pedi-lhe que regressasse à sua cadeira, pois tremia de febre:"},
    {"type": "paragraph", "text": "« Sim, mas não antes que você ria para mim! »"},
    {"type": "paragraph", "text": "O que fiz logo, por receio de que ela pegasse algum mal, e ajudei-a a regressar à sua cadeira."},
    {"type": "paragraph", "text": "2"},
    {"type": "paragraph", "text": "Eu sofria muito em vê-la doente e repetia-lhe frequentemente: « Oh! como a vida é triste! » Mas ela logo me repreendia, dizendo:"},
    {"type": "paragraph", "text": "« A vida não é triste! é ao contrário muito alegre. Se dissesses: \"O exílio é triste\", eu te compreenderia. Comete-se um erro ao dar o nome de vida ao que deve acabar. Só às coisas do céu, ao que nunca deve morrer, se deve dar esse verdadeiro nome; e, nesse sentido, a vida não é triste, mas alegre, muito alegre!... »"},
    {"type": "paragraph", "text": "3"},
    {"type": "paragraph", "text": "Num dia de festa no refeitório, esqueceram-se de me dar a sobremesa. Depois do jantar, fui ver Sr Th. de l'Enf. Jésus na enfermaria e, encontrando lá minha vizinha de mesa, fiz-lhe entender bastante habilmente que me haviam esquecido. Sr Th. de l'Enf. J. tendo-me ouvido, obrigou-me a ir avisar a Irmã encarregada do serviço, e como eu lhe suplicava que não me impusesse isso:"},
    {"type": "paragraph", "text": "« Não, disse-me ela, essa será tua penitência, não és digna dos sacrifícios que o bom Deus te pede. Ele te pedia a privação da tua sobremesa, pois é Ele quem permitiu que te esquecessem; Ele te julgava bastante generosa para esse sacrifício, e tu enganas sua expectativa indo reclamá-la! »"},
    {"type": "paragraph", "text": "Posso dizer que sua lição deu frutos e me curou para sempre do desejo de recomeçar."},
    {"type": "paragraph", "text": "4"},
    {"type": "paragraph", "text": "(...) Isso me recorda uma lembrança de intimidade com minha pequena irmã Th. de l'Enf.-J. Foi, mais ou menos, um mês antes de sua morte; toda a Comunidade estava muito triste, e eu não cedia certamente a ninguém em desgosto. Indo vê-la na Enfermaria, vi ao pé de sua cama um grande balão vermelho que lhe haviam dado para distraí-la. Esse balão despertou minha inveja e não pude deixar de lhe dizer: « Como eu gostaria de brincar com ele! » Ela sorriu, mas como sua fraqueza era tão grande que não podia suportar nenhum barulho, disse-me:"},
    {"type": "paragraph", "text": "« Ponha-se atrás de mim enquanto não há ninguém, e então brinque com ele, vou fechar os olhos para que isso não me aturda. »"},
    {"type": "paragraph", "text": "Radiante, peguei o balão e me diverti tanto em minha partida que a pequena Thérèse apertava os olhos para me olhar sem parecer e não podia deixar de rir. Então eu lhe disse: « É muito tempo estar triste para mim! Não aguento mais! Tenho como tentações de me distrair, vontades de brincar com pião que você me deu no Natal; mas se alguém me vê, podem escandalizar-se e dizer que eu não tenho coração."},
    {"type": "paragraph", "text": "— Não, não, respondeu-me ela, eu te obrigarei a pegar teu pião e ir brincar durante uma hora no sótão do Noviciado, lá ninguém te ouvirá e se alguém perceber dirás que fui eu que te disse. Vai depressa, isso me faz muito prazer pensar que vais te divertir. »"},
    {"type": "paragraph", "text": "5"},
    {"type": "paragraph", "text": "(...) oito dias antes de sua morte, havia chorado toda uma noite pensando em sua próxima partida. Ela percebeu e me disse:"},
    {"type": "paragraph", "text": "« Tens chorado. — Foi"},
    {"type": "paragraph", "text": "no recolhimento"},
    {"type": "paragraph", "text": "? »"},
    {"type": "paragraph", "text": "Eu não podia mentir e minha confissão a entristeceu. Ela retomou:"},
    {"type": "paragraph", "text": "« Vou morrer, e não ficarei tranquila quanto a ti, se não me prometeres seguir fielmente minha recomendação. Dou a isso uma importância capital para tua alma. »"},
    {"type": "paragraph", "text": "Eu só tinha que obedecer e dei minha palavra, pedindo todavia, como graça, a permissão de chorar livremente por sua morte."},
    {"type": "paragraph", "text": "« Por que chorar minha morte? São lágrimas bem inúteis. Chorareis minha felicidade! Enfim, tenho pena de tua fraqueza e permito-te chorar nos primeiros dias. Mas, depois disso, será preciso retomar o recolhimento. »"},
    {"type": "paragraph", "text": "6"},
    {"type": "paragraph", "text": "Pode-se acrescentar a essas lembranças as duas palavras consignadas por irmã Marie da Trindade, sobre imagens confeccionadas por ela:"},
    {"type": "paragraph", "text": "1° Suporte cartonado de 10,7 X 6,5 cm, comportando uma vinheta do retrato dito «Thérèse oval» (fuzain de irmã Geneviève) e uma flor de linho, colada, acompanhada desta inscrição, de próprio punho de irmã Marie da Trindade:"},
    {"type": "paragraph", "text": "« Flor de linho cor-de-rosa colhida e acariciada por Sr Thérèse do Menino Jesus e que ela ofereceu a uma de suas novícias dizendo-lhe: \"Será uma lembrança minha.\" »"},
    {"type": "paragraph", "text": "Para que a flor tenha sido colhida por Thérèse ela mesma, esse episódio deve situar-se, no máximo, em junho de 1897, enquanto a doente ainda saia ao jardim."},
    {"type": "paragraph", "text": "2° Suporte cartonado de 10,5 X 7,4 cm, comportando uma vinheta de «Thérèse às rosas», e uma margarida colada, junto da qual está escrito:"},
    {"type": "paragraph", "text": "« Alguns dias antes de sua morte, Santa Thérèse do Menino Jesus me deu esta margarida depois de a ter beijado, dizendo-me: \"Aqui está teu retrato!\" Sr Marie da Trindade r.c.i. »"},
    {"type": "paragraph", "text": "["},
    {"type": "meta", "text": "Documentos de Marie da Trindade ACL"},
    {"type": "paragraph", "text": "]"},
    {"type": "paragraph", "text": "Ela contou-me o episódio seguinte, ocorrido cinco meses antes de sua morte:"},
    {"type": "paragraph", "text": "« Numa noite, a enfermeira veio pôr-me aos pés uma bolsa de água quente e tintura de iodo no peito. Eu estava consumida pela febre, uma sede ardente me devorava. Ao submeter-me a esses remédios, não pude deixar de queixar-me ao Nosso Senhor: \"Meu Jesus, disse-lhe eu, tu és testemunha, eu queimo e trazem-me ainda calor e fogo! Ah! se ao invés de tudo isso eu tivesse meio copo de água!... Meu Jesus! tua filhinha tem tanta sede! Mas ela é feliz, contudo, por encontrar ocasião de faltar ao necessário a fim de se assemelhar mais a Ti e para salvar almas.\" Logo a enfermeira me deixou, e eu já não contava mais revê-la antes da manhã seguinte, quando, para minha grande surpresa, voltou alguns minutos depois trazendo uma bebida refrescante.... Oh! quão bom é nosso Jesus! Quão doce é confiar nele! »"},
    {"type": "paragraph", "text": "Thérèse de St-Augustin"},
    {"type": "paragraph", "text": "1"},
    {"type": "paragraph", "text": "Quando ela (Thérèse) desceu à enfermaria disse-me « que teu sonho se realiza bem »."},
    {"type": "paragraph", "text": "Quando ia vê-la eu lhe pedia: « E a porta negra? » Sabíamos o que isso queria dizer."},
    {"type": "paragraph", "text": "Esse sonho é contado com muitos detalhes nas pp. 7-10 do mesmo documento. Eis como Madre Agnès de Jésus o resumiu na"},
    {"type": "paragraph", "text": "circular de irmã Thérèse de Saint-Augustin"},
    {"type": "heading", "text": ", p. 7:"},
    {"type": "heading", "text": "« Em 8 de janeiro de 1897, ela teve este sonho:"},
    {"type": "paragraph", "text": "« Eu me encontrava, conta ela, num aposento muito escuro, fechado por uma pesada porta negra, por baixo da qual penetrava uma racha de luz éclatante. Do aposento vizinho, que adivinhei deslumbrante de claridade, ergueu-se uma voz: - Chama-se Irmã Thérèse do Menino Jesus! E tive então a impressão de que ao meu lado, numa parte ainda mais obscura do escuro aposento, preparavam minha querida pequena Irmã para responder a esse chamado. O que lhe faziam, ignoro, mas ouvi a mesma voz insistir: - É preciso que ela esteja muito bela! E aí me despertei, persuadida de que minha Irmã Thérèse do Menino Jesus ia em breve nos deixar para o Céu.»"},
    {"type": "paragraph", "text": "Alguns dias depois, irmã Thérèse de Saint-Augustin contou esse sonho a Thérèse, que lhe respondeu:"},
    {"type": "paragraph", "text": "« Que é belo! não é um sonho é uma visão e é por mim que o tiveste. (...) Se soubesses o bem que me fazes; não te falei do estado de minha alma? (...) Não creio na vida eterna, parece-me que depois desta vida mortal não há mais nada. Não posso expressar-lhe as trevas em que estou mergulhada. O que acabas de me contar é exatamente o estado de minha alma. A preparação que me fazem e sobretudo a porta negra é tão bem a imagem do que se passa em mim. Tu não viste senão vermelho nessa porta tão sombria, isto é, que tudo desapareceu para mim e que não me resta senão o amor. »"},
    {"type": "paragraph", "text": "« Oh! respondia-me ela, cada vez mais sombria. Teu sonho é meu único raio de luz, não tenho outro. Sei-o de cor até nos menores detalhes. » Dois dias antes de sua morte disse a uma de suas irmãs: - « Não podeis imaginar quantas vezes penso no sonho de minha Irmã Thérèse de Saint Augustin. Se as pessoas soubessem o bem que ele me fez e que consolações me deu durante minha doença, ele me ajudou a suportá-la. »"},
    {"type": "paragraph", "text": "2"},
    {"type": "paragraph", "text": "Alguns dias depois de sua chegada à enfermaria, fui vê-la. Assim que me viu estendeu-me os braços e exclamou com um acento de ternura inexplicável:"},
    {"type": "paragraph", "text": "« Oh! é minha Irmã Thérèse de Saint Augustin. »"},
    {"type": "heading", "text": "Depois dirigindo-se às jovens Irmãs presentes:"},
    {"type": "paragraph", "text": "« Rogo-vos, deixai-me só com ela, vejo-a tão pouco. »"},
    {"type": "paragraph", "text": "Quando ficamos a sós exprimiu-me de novo a felicidade que tinha em ver-me. Cada uma de minhas visitas era para ela um novo motivo de alegria. Uma vez, entre outras, uma"},
    {"type": "paragraph", "text": "A circular prossegue atribuindo a essas palavras a Thérèse: « Que presságio consolador na minha noite sombria!... E é por ti que o bom Deus me o concede! » Ela insistia nessas palavras: por ti... e lágrimas enchiam-lhe os olhos."},
    {"type": "paragraph", "text": "« Até sua morte, nossa querida pequena Santa mostrou àquela que assim a consolara sua gratidão e afeto, voltando de bom grado conosco, em intimidade, sobre essa delicadeza do bom Deus, que lhe havia dito tanto ao coração... »"},
    {"type": "paragraph", "text": "3"},
    {"type": "paragraph", "text": "Outro dia eu lhe disse: « Sofres muito, mas serás bem recompensada."},
    {"type": "paragraph", "text": "— Não, não pela recompensa, para lhe fazer prazer. Como seria infeliz se eu não fosse abandonada à vontade do bom Deus. Hoje, o Médico diz que estou perdida, amanhã que estou melhor, chega até a sugerir que talvez eu esteja aqui em abril. Que essa alternativa seria fatigante; mas tudo isso não toca minha alma e não perturba sua paz. Eu me abandono."},
    {"type": "paragraph", "text": "— Tens toda razão em não te perturbare. Eu sei mais do que ele e te afirmo que estás perdida, que certamente não estarás aqui em abril mas receio que sofras muito."},
    {"type": "paragraph", "text": "— Oh! não te inquietes com isso. O bom Deus não me dará mais do que posso suportar, é preciso deixá-lo fazer »"},
    {"type": "paragraph", "text": "4"},
    {"type": "paragraph", "text": "« Diz-me se tiveste combates."},
    {"type": "paragraph", "text": "— Oh! se os tive. Eu tinha uma natureza nada cômoda, isso não aparecia mas eu o sentia bem, posso te assegurar que não houve um só dia sem sofrer, nem um só."},
    {"type": "paragraph", "text": "— Mas pretendem que não os tiveste."},
    {"type": "paragraph", "text": "— Ah! os julgamentos das criaturas. Porque não veem, não crêem. »"},
    {"type": "paragraph", "text": "Hermance du Coeur de Jésus"},
    {"type": "paragraph", "text": "No ano passado, durante a doença de nossa angélica pequena irmã Thérèse do Menino Jesus, líamos no refeitório a"},
    {"type": "paragraph", "text": "vida de são Luís Gonzaga"},
    {"type": "paragraph", "text": "quando nossa querida Mãe foi atingida pela afeição tocante e recíproca do jovem Santo e de um venerável religioso da Companhia de Jesus, o Padre Corbinelli: « És tu o pequeno Luís, disse ela à nossa santa criança, e eu sou o velho Padre Corbinelli; quando estiveres no Céu, lembra-te de mim!"},
    {"type": "paragraph", "text": "— Queres, minha Mãe, que eu venha logo te buscar?"},
    {"type": "paragraph", "text": "— Não, ainda não, não sofri o bastante."},
    {"type": "paragraph", "text": "— Oh minha Mãe, eu te digo que já sofreste bastante!... »"},
    {"type": "paragraph", "text": "E Madre du Cœur de Jésus respondeu: « Ainda não ouso dizer-te sim... Para coisa tão grave, precisamos da sanção da autoridade. »"},
    {"type": "paragraph", "text": "De fato, o pedido nos foi dirigido e, sem lhe dar importância, demos resposta afirmativa. Pois bem, um dos últimos dias de sua vida, Sœur Thérèse de l'Enfant Jésus, praticamente sem poder falar, por causa de sua grande fraqueza, recebeu de nossa querida Mãe um pequeno buquê de flores, com oração instante à enfermeira de lho transmitir depois, como agradecimento, uma só palavra de nosso anjo. E eis qual foi essa palavra verdadeiramente profética:"},
    {"type": "paragraph", "text": "« Dize a Madre Cœur de Jésus que, esta manhã, durante a Missa, vi a tumba do Padre Corbinelli muito perto da do pequeno Luís."},
    {"type": "paragraph", "text": "— Está bem, respondeu, toda emocionada, nossa boa Mãe, dize a irmã Thérèse de l'Enfant Jésus que eu entendi! »"},
    {"type": "paragraph", "text": "Marie des Anges"},
    {"type": "paragraph", "text": "Madre Agnès de Jésus dizia-lhe, num dia em que a Comunidade se reunia junto à sua cama: « Se atirasses flores à Comunidade!"},
    {"type": "paragraph", "text": "— Oh! não, minha pequenina mãe, respondeu ela, não me peça isso, imploro-te; não quero atirar flores às criaturas. Eu o aceitaria ainda pela Santa Virgem e São José, mas não por outras criaturas. »"},
    {"type": "paragraph", "text": "Marthe de Jésus"},
    {"type": "paragraph", "text": "Algumas semanas antes de sua morte mandou chamar-me e disse:"},
    {"type": "paragraph", "text": "« Não ficarei tranquila quanto a ti, é preciso que me prometas rezar todos os dias um \"lembras-te\" à Santa Virgem. »"},
    {"type": "paragraph", "text": "Prometi-lhe e fui fiel."},
    {"type": "paragraph", "text": "Marie de Jésus"},
    {"type": "paragraph", "text": "Sua união com Deus era contínua. Lembro-me que no começo de sua doença, sendo eu enfermeira, lhe dava um remédio que exigia um pouco de tempo e isso acontecia durante a oração, fiz-lhe a observação e perguntei se isso não a ia distrair."},
    {"type": "paragraph", "text": "« Não, disse-me ela, vou fazer minha oração, esse remédio não pode impedi-la. »"},
    {"type": "paragraph", "text": "Compreendi como essa alma toda entregada a Deus sabia usar de tudo para não perder sua presença."},
    {"type": "meta", "text": "Último Ano de Vida de Thérèse @ ACL"},
    {"type": "paragraph", "text": "Visita Virtual do Mosteiro carmeldelisieux.fr"},
  ]),
];

